function isMissingAutomationRunLogsTableError(error) {
  const message = String(error?.message || "").toLowerCase();
  return error?.code === "42P01" || message.includes("automation_run_logs") && message.includes("does not exist");
}

function compactAutomationRunLogError(errorMessage) {
  const message = String(errorMessage || "").trim();
  if (!message) {
    return null;
  }

  return message.slice(0, 1200);
}

function normalizeAutomationRunLogSearchMethod(value) {
  const rawValue = String(value || "").trim();
  const normalizedValue = rawValue.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");

  if (!normalizedValue) {
    return "";
  }

  if (normalizedValue.includes("domain_site_search")) {
    return "domain_site_search";
  }

  if (normalizedValue.includes("backup_broad")) {
    return "domain_web_search_backup_broad";
  }

  if (normalizedValue.includes("best_match")) {
    return "domain_web_search_best_match";
  }

  if (normalizedValue.includes("ai_discovery_page")) {
    return "ai_discovery_page";
  }

  if (normalizedValue.includes("product_research") || normalizedValue.includes("web_search") || normalizedValue.includes("ai_web")) {
    return "ai_domain_web_search";
  }

  if (normalizedValue.includes("campaign_search_pool") || normalizedValue.includes("store_search")) {
    return "store_search";
  }

  if (normalizedValue.includes("campaign_catalog_term_match")) {
    return "catalog_campaign_term_match";
  }

  if (normalizedValue.includes("brand_catalog") || normalizedValue.includes("catalog") || normalizedValue.includes("selected")) {
    return "existing_product_catalog";
  }

  return normalizedValue.slice(0, 80);
}

function inferAutomationRunLogSearchMethodForItem(item) {
  const methodCandidates = [
    item?.automation_search_method,
    item?.product_search_method,
    item?.search_method,
    item?.search_attempt,
    item?.web_search_attempt,
    item?.discovery_attempt,
    item?.campaign_fit_source,
    item?.discovery_source,
    item?.catalog_source,
    item?.used_source,
    item?.source,
    item?.selection_source,
    item?.research_source,
  ];

  for (const candidate of methodCandidates) {
    const normalized = normalizeAutomationRunLogSearchMethod(candidate);
    if (normalized) {
      return normalized;
    }
  }

  return "existing_product_catalog";
}

function collectAutomationRunProductLogData({ websiteItem = null, websiteItems = [] } = {}) {
  const allItems = [
    ...(Array.isArray(websiteItems) ? websiteItems : []),
    websiteItem,
  ].filter(Boolean);

  const uniqueByUrl = new Map();

  for (const item of allItems) {
    const key = normalizeComparableValue(item?.url) || normalizeComparableValue(item?.title);
    if (!key || uniqueByUrl.has(key)) {
      continue;
    }

    uniqueByUrl.set(key, item);
  }

  const uniqueItems = Array.from(uniqueByUrl.values());
  const methodCounts = {};
  const productDetails = [];
  let freshProducts = 0;
  let reusedProducts = 0;

  for (const item of uniqueItems) {
    const method = inferAutomationRunLogSearchMethodForItem(item);
    methodCounts[method] = (methodCounts[method] || 0) + 1;
    const isReused = Boolean(
      item?.campaign_rotation_state === "reused" ||
        item?.campaign_was_used_recently ||
        item?.campaign_image_used_this_run ||
        hasWebsiteItemCatalogUsage(item)
    );

    if (isReused) {
      reusedProducts += 1;
    } else {
      freshProducts += 1;
    }

    productDetails.push({
      title: String(item?.title || item?.name || "").trim() || null,
      url: String(item?.url || "").trim() || null,
      image_url: String(item?.image_url || item?.imageUrl || "").trim() || null,
      search_method: method,
      campaign_fit_score: Number.isFinite(Number(item?.campaign_fit_score)) ? Number(item.campaign_fit_score) : null,
      campaign_fit_source: String(item?.campaign_fit_source || "").trim() || null,
      ai_campaign_fit_score:
        item?.ai_campaign_fit_score === undefined ||
        item?.ai_campaign_fit_score === null ||
        item?.ai_campaign_fit_score === ""
          ? null
          : Number.isFinite(Number(item.ai_campaign_fit_score))
            ? Number(item.ai_campaign_fit_score)
            : null,
      ai_campaign_fit_source: String(item?.ai_campaign_fit_source || "").trim() || null,
      ai_campaign_fit_model: String(item?.ai_campaign_fit_model || "").trim() || null,
      campaign_fit_verdict: String(item?.campaign_fit_verdict || "").trim() || null,
      campaign_fit_reason: String(item?.campaign_fit_reason || "").trim() || null,
      discovery_source: String(item?.discovery_source || "").trim() || null,
      catalog_source: String(item?.catalog_source || "").trim() || null,
      selection_priority: Number.isFinite(Number(item?.selection_priority)) ? Number(item.selection_priority) : null,
      times_used: Number.isFinite(Number(item?.times_used)) ? Number(item.times_used) : null,
      last_used_at: String(item?.last_used_at || "").trim() || null,
      campaign_rotation_state:
        String(item?.campaign_rotation_state || "").trim() || (isReused ? "reused" : "fresh"),
      campaign_was_used_recently: Boolean(item?.campaign_was_used_recently || hasWebsiteItemCatalogUsage(item)),
      campaign_image_used_this_run: Boolean(item?.campaign_image_used_this_run),
    });
  }

  const searchMethods = Object.keys(methodCounts).slice(0, 20);

  return {
    productsSelected: uniqueItems.length,
    productTitles: uniqueItems
      .map((item) => String(item?.title || item?.name || "").trim())
      .filter(Boolean)
      .slice(0, 12),
    productUrls: uniqueItems
      .map((item) => String(item?.url || "").trim())
      .filter(Boolean)
      .slice(0, 12),
    searchMethods,
    methodCounts,
    productDetails: productDetails.slice(0, 12),
    productsWithImages: uniqueItems.filter((item) => Boolean(item?.image_url || item?.imageUrl)).length,
    freshProducts,
    reusedProducts,
  };
}

async function createAutomationRunLog({ supabase, rule, startedAtIso }) {
  const ruleName = rule?.name || rule?.title || null;
  const campaignTitle =
    rule?.campaign_title ||
    rule?.campaign_name ||
    rule?.campaign_opportunity_title ||
    ruleName ||
    null;

  try {
    const { data, error } = await supabase
      .from("automation_run_logs")
      .insert({
        user_id: rule.user_id,
        brand_profile_id: rule.brand_profile_id || null,
        rule_id: rule.id,
        status: "running",
        started_at: startedAtIso,
        rule_name: ruleName,
        campaign_title: campaignTitle,
        content_type_id: rule.content_type_id || null,
        content_format: normalizeContentFormat(rule.content_format),
        is_admin_test: rule?.is_admin_test === true,
        admin_test_batch_id: rule?.is_admin_test === true ? rule.admin_test_batch_id || null : null,
        admin_test_job_key: rule?.is_admin_test === true ? rule.admin_test_job_key || null : null,
        product_match_terms: rule.product_match_terms || null,
        product_search_queries: rule.product_search_queries || null,
        metadata: {
          rule_name: ruleName,
          campaign_title: campaignTitle,
          post_type: rule.post_type || null,
          uses_website_content: Boolean(rule.uses_website_content),
          generate_image: Boolean(rule.generate_image),
          is_admin_test: rule?.is_admin_test === true,
          admin_test_batch_id: rule?.admin_test_batch_id || null,
          admin_test_job_key: rule?.admin_test_job_key || null,
          vercel_env: process.env.VERCEL_ENV || null,
          vercel_deployment_id: process.env.VERCEL_DEPLOYMENT_ID || null,
          vercel_git_commit_sha: process.env.VERCEL_GIT_COMMIT_SHA || null,
        },
      })
      .select("id")
      .single();

    if (error) {
      if (!isMissingAutomationRunLogsTableError(error)) {
        console.warn("Could not create automation run log", {
          ruleId: rule.id,
          message: error.message,
        });
      }
      return null;
    }

    return data?.id || null;
  } catch (error) {
    if (!isMissingAutomationRunLogsTableError(error)) {
      console.warn("Could not create automation run log", {
        ruleId: rule?.id,
        message: error.message,
      });
    }
    return null;
  }
}

async function updateAutomationRunLogBrandSnapshot({ supabase, runLogId, brandProfile, rule }) {
  if (!runLogId) {
    return;
  }

  const brandName = String(
    brandProfile?.business_name ||
      brandProfile?.name ||
      brandProfile?.brand_name ||
      ""
  ).trim();
  const brandWebsiteUrl = String(
    brandProfile?.website_product_source_url ||
      brandProfile?.website_url ||
      ""
  ).trim();
  const ruleName = rule?.name || rule?.title || null;
  const campaignTitle =
    rule?.campaign_title ||
    rule?.campaign_name ||
    rule?.campaign_opportunity_title ||
    ruleName ||
    null;

  try {
    const { error } = await supabase
      .from("automation_run_logs")
      .update({
        brand_name: brandName || null,
        brand_website_url: brandWebsiteUrl || null,
        rule_name: ruleName,
        campaign_title: campaignTitle,
        content_type_id: rule?.content_type_id || null,
        content_format: normalizeContentFormat(rule?.content_format),
        updated_at: new Date().toISOString(),
      })
      .eq("id", runLogId);

    if (error && !isMissingAutomationRunLogsTableError(error)) {
      console.warn("Could not update automation run log brand snapshot", {
        runLogId,
        message: error.message,
      });
    }
  } catch (error) {
    if (!isMissingAutomationRunLogsTableError(error)) {
      console.warn("Could not update automation run log brand snapshot", {
        runLogId,
        message: error.message,
      });
    }
  }
}

async function finishAutomationRunLog({
  supabase,
  runLogId,
  status,
  startedAtIso,
  errorMessage = null,
  postId = null,
  websiteItem = null,
  websiteItems = [],
  extraSummary = {},
}) {
  if (!runLogId) {
    return;
  }

  const finishedAtIso = new Date().toISOString();
  const durationMs = Math.max(0, new Date(finishedAtIso).getTime() - new Date(startedAtIso).getTime());
  const productData = collectAutomationRunProductLogData({ websiteItem, websiteItems });

  try {
    const { error } = await supabase
      .from("automation_run_logs")
      .update({
        status,
        finished_at: finishedAtIso,
        duration_ms: Number.isFinite(durationMs) ? durationMs : null,
        error_message: compactAutomationRunLogError(errorMessage),
        post_id: postId || null,
        products_selected: productData.productsSelected,
        product_titles: productData.productTitles,
        product_urls: productData.productUrls,
        search_methods: productData.searchMethods,
        metadata: {
          ...extraSummary,
          website_items_found: Array.isArray(websiteItems) ? websiteItems.length : 0,
          selected_product_count: productData.productsSelected,
          selected_products_with_images: productData.productsWithImages,
          fresh_product_count: productData.freshProducts,
          reused_product_count: productData.reusedProducts,
          search_method_counts: productData.methodCounts,
          product_details: productData.productDetails,
        },
        updated_at: finishedAtIso,
      })
      .eq("id", runLogId);

    if (error && !isMissingAutomationRunLogsTableError(error)) {
      console.warn("Could not finish automation run log", {
        runLogId,
        message: error.message,
      });
    }
  } catch (error) {
    if (!isMissingAutomationRunLogsTableError(error)) {
      console.warn("Could not finish automation run log", {
        runLogId,
        message: error.message,
      });
    }
  }
}

async function setRuleError(supabase, ruleId, message) {
  await supabase
    .from("automation_rules")
    .update({
      last_error: message,
      updated_at: new Date().toISOString(),
    })
    .eq("id", ruleId);
}

// v144.106: the admin queue is created before generation starts. A small
// number of failures can happen before automation_occurrences is claimed, so
// those failures must update the pre-created work item directly or they would
// otherwise only exist in logs/email. Missing-table errors are ignored during
// rolling deploys so the cron remains backwards compatible until SQL is run.
async function markAdminWorkItemFailedBeforeOccurrence({
  supabase,
  rule,
  scheduledFor,
  runLogId = null,
  stage = null,
  failureCode = null,
  message,
  productItems = [],
  workerName = null,
}) {
  if (!rule?.id || !scheduledFor) return;
  const now = new Date().toISOString();
  try {
    const payload = {
      status: "failed",
      run_log_id: runLogId || null,
      failure_code: failureCode || "generation_failed_before_occurrence_claim",
      failure_stage: stage || "unhandled_before_occurrence_claim",
      failure_message: String(message || "Generation failed before occurrence claim").slice(0, 4000),
      rescue_status: "needed",
      technical_log: {
        failure_before_occurrence_claim: true,
        worker_name: workerName || null,
        run_log_id: runLogId || null,
        failed_at: now,
        product_items: Array.isArray(productItems) ? productItems.slice(0, 5) : [],
      },
      updated_at: now,
    };
    const { error } = await supabase
      .from("admin_generation_work_items")
      .update(payload)
      .eq("automation_rule_id", rule.id)
      .eq("scheduled_for", scheduledFor);
    if (error && !/admin_generation_work_items|schema cache|does not exist/i.test(String(error.message || ""))) {
      console.warn("Could not mark admin work item failed before occurrence claim", {
        ruleId: rule.id,
        scheduledFor,
        message: error.message,
      });
    }
  } catch (error) {
    if (!/admin_generation_work_items|schema cache|does not exist/i.test(String(error?.message || ""))) {
      console.warn("Could not mark admin work item failed before occurrence claim", {
        ruleId: rule.id,
        scheduledFor,
        message: error?.message || String(error),
      });
    }
  }
}

function classifyAutomationCreationFailure(errorOrMessage, stage = "unhandled") {
  const message = String(errorOrMessage?.message || errorOrMessage || "Unknown automation error");
  const normalized = message.toLowerCase();
  const normalizedStage = String(stage || "unhandled").toLowerCase();

  if (errorOrMessage?.code === "WEBSITE_RATE_LIMIT_RETRY_EXHAUSTED") {
    return {
      code: "website_rate_limit_exhausted",
      customerMessage:
        "The website continued limiting access after several automatic cooldown attempts. This occurrence has been stopped and will not be retried automatically.",
    };
  }

  if (isProtectedProductResearchRetryError(errorOrMessage)) {
    return {
      code: "website_security_blocked",
      customerMessage:
        "The website's security protection stopped Spreelo from accessing the product information needed for this post. The occurrence has been stopped for Spreelo admin rescue and will not be retried automatically.",
    };
  }

  if (
    [
      "CAROUSEL_EXACT_PRODUCT_POOL_INCOMPLETE",
      "CAMPAIGN_AUTHORITATIVE_WEB_RESEARCH_INSUFFICIENT_ASSETS",
    ].includes(String(errorOrMessage?.code || ""))
  ) {
    return {
      code: "carousel_product_verification_incomplete",
      customerMessage:
        "Spreelo could not verify enough exact product-and-image matches for this carousel. The post was held for Spreelo review instead of risking a wrong product.",
    };
  }

  if (
    /website returned 403|http 403|forbidden|cloudflare|security protection|security_blocked/.test(normalized)
  ) {
    return {
      code: "website_security_blocked",
      customerMessage:
        "The website's security protection stopped Spreelo from accessing the information needed for this post. The occurrence has been stopped for Spreelo admin rescue and will not be retried automatically.",
    };
  }

  if (
    /domain cooldown|rate limit|too many requests|request pacing|retry-after/.test(normalized) &&
    !/openai|quota|billing/.test(normalized)
  ) {
    return {
      code: "website_rate_limited",
      customerMessage:
        "The website temporarily limited access. Spreelo has paused this post and will continue automatically after the website cooldown ends.",
    };
  }

  if (/quota|billing|openai.*429|ai service|model.*unavailable/.test(normalized)) {
    return {
      code: "ai_service_unavailable",
      customerMessage:
        "The AI service could not complete this planned post. This occurrence will not be retried automatically.",
    };
  }

  if (
    /no verified(?: matching)? website product|no usable product|could not find.*product|needs at least .*products|product researcher returned no valid|product.*could not be normalized/.test(
      normalized
    ) || normalizedStage.includes("product_prepare")
  ) {
    return {
      code: "no_suitable_product",
      customerMessage:
        "Spreelo could not verify enough suitable products from the website for this planned post. This occurrence will not be retried automatically.",
    };
  }

  if (
    /product image|website image|no usable image|image.*missing|transparent/.test(normalized) ||
    normalizedStage.includes("image")
  ) {
    return {
      code: "product_image_unusable",
      customerMessage:
        "The product image could not be used to create this planned post. This occurrence will not be retried automatically.",
    };
  }

  if (
    /carousel slides|render|shotstack|animated product video|video could not/.test(normalized) ||
    normalizedStage.includes("render") ||
    normalizedStage.includes("carousel_slide")
  ) {
    return {
      code: "media_render_failed",
      customerMessage:
        "The image or video for this planned post could not be completed. This occurrence will not be retried automatically.",
    };
  }

  if (/empty content|content generation|completion/.test(normalized) || normalizedStage === "content_generation") {
    return {
      code: "content_generation_failed",
      customerMessage:
        "Spreelo could not complete the content for this planned post. This occurrence will not be retried automatically.",
    };
  }

  if (/credit balance|not enough credits/.test(normalized)) {
    return {
      code: "insufficient_credits",
      customerMessage:
        "The planned post could not be created because the account did not have enough available credits. The plan has been paused until credits are available.",
    };
  }

  if (isTransientAutomationError(errorOrMessage)) {
    return {
      code: "transient_runtime_failure",
      customerMessage:
        "A temporary technical dependency did not respond after bounded automatic retries. Spreelo has held the occurrence for internal review.",
    };
  }

  if (/stale|incomplete .*draft|still rendering/.test(normalized)) {
    return {
      code: "incomplete_generation",
      customerMessage:
        "The planned post could not be completed. This occurrence will not be retried automatically.",
    };
  }

  return {
    code: "unexpected_creation_error",
    customerMessage:
      "An unexpected technical error prevented this planned post from being created. This occurrence will not be retried automatically.",
  };
}


function isTransientAutomationError(errorOrMessage) {
  // v144.107: a confirmed protected product source (403 / Access Denied /
  // anti-bot challenge) is deterministic for this server-side occurrence.
  // Retrying the same product-research chain only repeats paid web/AI work, so
  // hand it to Admin Rescue immediately instead of treating it as transient.
  if (isProtectedProductResearchRetryError(errorOrMessage)) return false;
  const message = String(errorOrMessage?.message || errorOrMessage || "").toLowerCase();
  const code = String(errorOrMessage?.code || "").toLowerCase();
  const status = Number(
    errorOrMessage?.status ||
      errorOrMessage?.statusCode ||
      errorOrMessage?.response?.status ||
      0
  );

  if (status === 408 || status === 425 || status === 429 || status >= 500) {
    return true;
  }

  return /request timed out|timed?\s*out|timeout|deadline|aborted|aborterror|econnreset|econnrefused|enotfound|etimedout|socket hang up|network error|fetch failed|temporar(?:y|ily) unavailable|service unavailable|overloaded|bad gateway|gateway timeout|connection reset|connection closed|rate limit|too many requests/.test(
    `${code} ${message}`
  );
}

function buildDeterministicDeliveryCopy(rule) {
  const contract =
    rule?.product_content_contract ||
    buildProductContentContract(
      isCarouselRule(rule)
        ? getCarouselProducts(rule).filter(isValidCarouselProduct)
        : rule?.website_item
          ? [rule.website_item]
          : [],
      []
    );
  const selectedProducts = Array.isArray(contract?.selected_products)
    ? contract.selected_products.filter((item) => item?.title)
    : [];
  const destinationUrl = getPostDestinationUrl(rule);
  const brandName = String(
    rule?.brand_profile?.business_name ||
      rule?.brand_profile?.name ||
      rule?.brand_name ||
      ""
  ).trim();
  const campaignName = String(getProductLabelEyebrow(rule) || "").trim();

  const lines = [];
  if (campaignName) lines.push(campaignName);
  else if (brandName) lines.push(brandName);

  if (selectedProducts.length === 1) {
    const product = selectedProducts[0];
    if (!lines.includes(product.title)) lines.push(product.title);
    const description = truncateText(
      product?.description || rule?.website_item?.description || "",
      260
    ).trim();
    if (description) lines.push(description);
  } else if (selectedProducts.length > 1) {
    lines.push(
      selectedProducts
        .slice(0, CAROUSEL_PRODUCT_SLIDE_TARGET)
        .map((product) => `• ${String(product.title || "").trim()}`)
        .filter(Boolean)
        .join("\n")
    );
  } else {
    const brandDescription = truncateText(
      rule?.brand_profile?.brand_description || "",
      280
    ).trim();
    if (brandDescription) lines.push(brandDescription);
  }

  if (destinationUrl) lines.push(destinationUrl);
  return lines.filter(Boolean).join("\n\n").trim();
}

function escapeAutomationEmailHtml(value) {
  return String(value || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function claimAutomationOccurrenceOnce({
  supabase,
  rule,
  scheduledFor,
  runLogId,
  workerName,
}) {
  const { data, error } = await supabase.rpc("claim_automation_occurrence_once", {
    p_rule_id: rule.id,
    p_scheduled_for: scheduledFor,
    p_run_log_id: runLogId,
    p_worker_name: workerName,
  });

  if (error) {
    throw new Error(
      `The v140 database migration is required before automation can run: ${error.message || "claim_automation_occurrence_once is unavailable"}`
    );
  }

  return data || { claimed: false, occurrence_id: null, status: "unknown" };
}

async function completeAutomationOccurrence({ supabase, openai = null, occurrenceId, postId, metadata = {} }) {
  if (!occurrenceId) return null;
  const { data, error } = await supabase.rpc("complete_automation_occurrence", {
    p_occurrence_id: occurrenceId,
    p_post_id: postId || null,
    p_metadata: metadata || {},
  });
  if (error) {
    console.error("Could not mark automation occurrence completed", {
      occurrenceId,
      postId,
      message: error.message,
    });
    return null;
  }

  if (openai) {
    await cancelCampaignResearchJobsForOccurrence({
      supabase,
      openai,
      occurrenceId,
      reason: "occurrence_completed",
    });
  }

  return data;
}

