function stripDefaultWebsiteTextPromptNoise(value) {
  return String(value || "")
    .replace(/this post is part of a strategic content sequence for the goal:[^\n\r.]*\.?/gi, " ")
    .replace(/^post role:\s*.+$/gim, " ")
    .replace(/^strategic purpose:\s*.+$/gim, " ")
    .replace(/^marketing angle:\s*.+$/gim, " ")
    .replace(/^customer stage:\s*.+$/gim, " ")
    .replace(/^cta strength:\s*.+$/gim, " ")
    .replace(/make this post clearly different from the other posts in the plan\.?/gi, " ")
    .replace(/do not just create a generic mixed post\.?/gi, " ")
    .replace(/if website products are used, choose products that fit this exact role and audience need, not random products from the website\.?/gi, " ")
    .replace(/use the website url from the brand profile\.?/gi, " ")
    .replace(/identify one concrete product, service, listing, offer or other sellable item from the website\.?/gi, " ")
    .replace(/create a social media post that promotes that specific item in a helpful, trustworthy and sales-focused way\.?/gi, " ")
    .replace(/create a social media post caption that promotes that specific item in a helpful, trustworthy and sales-focused way\.?/gi, " ")
    .replace(/the caption should work together with a product-specific ad image\.?/gi, " ")
    .replace(/create a full ad-style image around the selected website item\.?/gi, " ")
    .replace(/use the real website item image as the basis when possible, and design a unique social media ad that fits that exact product\.?/gi, " ")
    .replace(/include short readable marketing text in the image, but do not include price, discounts or ratings\.?/gi, " ")
    .replace(/use only information that clearly appears on the website\.?/gi, " ")
    .replace(/do not invent prices, discounts, guarantees, opening hours, features or availability\.?/gi, " ")
    .replace(/use a relevant image connected to the selected website item if one can be found\.?/gi, " ")
    .replace(/avoid logos, banners, hero images, decorative icons and unrelated images\.?/gi, " ")
    .replace(/if no clearly relevant product, service, listing or offer image can be found, create a professional ai image based on the selected item instead\.?/gi, " ");
}

function isUsefulWebsiteTextIntentToken(token) {
  const value = normalizeSearchText(token).trim();

  return (
    value.length >= 3 &&
    value.length <= 34 &&
    !/^\d+$/.test(value) &&
    !weakShortSearchRoots.has(value) &&
    !genericWebsiteTextIntentTokens.has(value)
  );
}

function extractWebsiteTextIntentTermsFromText(value, limit = WEBSITE_TEXT_INTENT_MATCH_TERM_LIMIT) {
  const normalized = normalizeSearchText(stripDefaultWebsiteTextPromptNoise(value))
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/\bwww\.\S+/g, " ");
  const segments = normalized
    .split(/[\n\r.!?;:|()[\]{}<>]+/u)
    .map((segment) => segment.trim())
    .filter(Boolean);
  const terms = [];

  for (const segment of segments) {
    const tokens = segment
      .split(/[^\p{L}\p{N}]+/u)
      .map((token) => token.trim())
      .filter(isUsefulWebsiteTextIntentToken);

    if (!tokens.length) {
      continue;
    }

    for (let index = 0; index < tokens.length; index += 1) {
      const threeWordPhrase = tokens.slice(index, index + 3);
      const twoWordPhrase = tokens.slice(index, index + 2);

      if (threeWordPhrase.length === 3) {
        terms.push(threeWordPhrase.join(" "));
      }

      if (twoWordPhrase.length === 2) {
        terms.push(twoWordPhrase.join(" "));
      }
    }

    terms.push(...tokens);
  }

  return collectUniqueTerms(terms, limit);
}

function getWebsiteTextIntentSourceText(rule) {
  const prompt = String(rule?.prompt || "");
  const imagePrompt = String(rule?.image_prompt || "");

  return [
    getCustomerFacingCampaignTheme(rule),
    stripDefaultWebsiteTextPromptNoise(prompt),
    stripDefaultWebsiteTextPromptNoise(imagePrompt),
    extractPromptLineValue(prompt, "Campaign"),
    extractPromptLineValue(prompt, "Campaign context"),
    extractPromptLineValue(prompt, "Product selection hint"),
    extractPromptLineValue(prompt, "Product search intent"),
    rule?.campaign_goal,
    rule?.target_customer_need,
    rule?.marketing_angle,
    rule?.strategy_notes,
    rule?.product_search_intent,
  ]
    .filter(Boolean)
    .join("\n");
}

function normalizeWebsiteTextIntentMetadata(metadata = {}) {
  return {
    productMatchTerms: collectUniqueTerms(
      [
        ...splitCampaignTermLine(metadata.product_match_terms),
        ...splitCampaignTermLine(metadata.productMatchTerms),
        ...(Array.isArray(metadata.product_match_terms) ? metadata.product_match_terms : []),
        ...(Array.isArray(metadata.productMatchTerms) ? metadata.productMatchTerms : []),
      ],
      WEBSITE_TEXT_INTENT_MATCH_TERM_LIMIT
    ),
    productSearchQueries: collectUniqueTerms(
      [
        ...splitStoreSearchQueryLine(metadata.product_search_queries),
        ...splitStoreSearchQueryLine(metadata.productSearchQueries),
        ...(Array.isArray(metadata.product_search_queries) ? metadata.product_search_queries : []),
        ...(Array.isArray(metadata.productSearchQueries) ? metadata.productSearchQueries : []),
      ],
      WEBSITE_TEXT_INTENT_QUERY_LIMIT
    ),
    productAvoidTerms: collectUniqueTerms(
      [
        ...splitCampaignTermLine(metadata.product_avoid_terms),
        ...splitCampaignTermLine(metadata.productAvoidTerms),
        ...splitCampaignTermLine(metadata.avoid_terms),
        ...(Array.isArray(metadata.product_avoid_terms) ? metadata.product_avoid_terms : []),
        ...(Array.isArray(metadata.productAvoidTerms) ? metadata.productAvoidTerms : []),
        ...(Array.isArray(metadata.avoid_terms) ? metadata.avoid_terms : []),
      ],
      WEBSITE_TEXT_INTENT_AVOID_LIMIT
    ),
    productSearchIntent: String(
      metadata.product_search_intent ||
        metadata.productSearchIntent ||
        ""
    ).trim(),
  };
}

function buildDeterministicWebsiteTextProductIntent(rule) {
  const sourceText = getWebsiteTextIntentSourceText(rule);
  const inferredTerms = extractWebsiteTextIntentTermsFromText(sourceText);
  const existingMetadata = normalizeWebsiteTextIntentMetadata({
    product_match_terms: rule?.product_match_terms,
    product_search_queries: rule?.product_search_queries,
    product_avoid_terms: rule?.product_avoid_terms,
    avoid_terms: rule?.avoid_terms,
    product_search_intent: rule?.product_search_intent,
  });
  const productMatchTerms = collectUniqueTerms(
    [
      ...existingMetadata.productMatchTerms,
      ...inferredTerms,
    ],
    WEBSITE_TEXT_INTENT_MATCH_TERM_LIMIT
  );
  const productSearchQueries = collectUniqueTerms(
    [
      ...existingMetadata.productSearchQueries,
      ...inferredTerms.slice(0, WEBSITE_TEXT_INTENT_QUERY_LIMIT),
    ],
    WEBSITE_TEXT_INTENT_QUERY_LIMIT
  );
  const productAvoidTerms = existingMetadata.productAvoidTerms;
  const productSearchIntent =
    existingMetadata.productSearchIntent ||
    (productMatchTerms.length
      ? `Prioritize concrete website products matching: ${productMatchTerms.slice(0, 8).join(", ")}.`
      : "");

  return {
    productMatchTerms,
    productSearchQueries,
    productAvoidTerms,
    productSearchIntent,
    hasSpecificIntent:
      hasProductSearchMetadata(rule) ||
      inferredTerms.length >= WEBSITE_TEXT_INTENT_AI_MIN_SIGNAL_TERMS,
  };
}

function applyWebsiteTextProductIntentToRule(rule, intentMetadata) {
  const normalized = normalizeWebsiteTextIntentMetadata({
    product_match_terms: intentMetadata.productMatchTerms,
    product_search_queries: intentMetadata.productSearchQueries,
    product_avoid_terms: intentMetadata.productAvoidTerms,
    product_search_intent: intentMetadata.productSearchIntent,
  });

  if (
    !normalized.productMatchTerms.length &&
    !normalized.productSearchQueries.length &&
    !normalized.productAvoidTerms.length &&
    !normalized.productSearchIntent
  ) {
    return rule;
  }

  return {
    ...rule,
    product_match_terms: normalized.productMatchTerms.join(", "),
    product_search_queries: normalized.productSearchQueries.join(", "),
    product_avoid_terms: normalized.productAvoidTerms.join(", "),
    product_search_intent: normalized.productSearchIntent || rule?.product_search_intent || null,
    website_text_product_intent_applied: true,
  };
}

async function generateWebsiteTextProductIntentWithAi({
  openai,
  rule,
  brandProfile,
  deterministicIntent,
}) {
  if (!openai || !deterministicIntent?.hasSpecificIntent) {
    return null;
  }

  const response = await openai.responses.create({
    model: PRODUCT_RESEARCH_FAST_MODEL,
    ...getReasoningOptionsForModel(PRODUCT_RESEARCH_FAST_MODEL),
    input: `
You create product search metadata for a social media automation product finder.

Goal:
The app must select one real website product/service/listing that fits the user's website post prompt.

Rules:
- Do not use fixed holiday lists or hardcoded Swedish/English campaign words.
- Infer meaning from the brand, language, market, prompt and any existing seed terms.
- Return local-language website search terms that a real store search box could use.
- Prefer short exact terms, category terms, recipient/use-case terms and theme terms.
- Avoid generic words like product, website, post, campaign, custom or offer unless they are truly part of the customer's product vocabulary.
- If the prompt has no specific theme, occasion, recipient, category or product intent, return empty arrays.

Brand profile:
${formatBrandProfileForPrompt(brandProfile)}

Customer-facing campaign/theme:
${getCustomerFacingCampaignTheme(rule) || "None"}

Internal automation/plan names are scheduling metadata and must not be treated as product intent.

Automation prompt:
${stripDefaultWebsiteTextPromptNoise(rule?.prompt || "")}

Image prompt:
${stripDefaultWebsiteTextPromptNoise(rule?.image_prompt || "")}

Existing inferred terms:
${deterministicIntent.productMatchTerms.join(", ") || "None"}

Return strict JSON only:
{
  "product_match_terms": ["5-12 short terms"],
  "product_search_queries": ["3-8 short store-search queries"],
  "product_avoid_terms": ["0-8 short avoid terms"],
  "product_search_intent": "One short internal sentence"
}
    `.trim(),
  });

  const parsed = safeJsonParse(response.output_text || "");
  return normalizeWebsiteTextIntentMetadata(parsed);
}

async function resolveWebsiteTextProductIntentRule({
  openai,
  rule,
  brandProfile,
}) {
  if (!rule?.uses_website_content || isCarouselRule(rule)) {
    return rule;
  }

  const deterministicIntent = buildDeterministicWebsiteTextProductIntent(rule);

  if (!deterministicIntent.hasSpecificIntent) {
    return rule;
  }

  let aiIntent = null;

  if (!isCampaignScopedWebsiteRule(rule)) {
    try {
      aiIntent = await generateWebsiteTextProductIntentWithAi({
        openai,
        rule,
        brandProfile,
        deterministicIntent,
      });
    } catch (error) {
      console.log("Website text product-intent AI expansion failed; using deterministic terms", {
        ruleId: rule?.id,
        brandProfileId: rule?.brand_profile_id,
        message: error.message,
      });
    }
  }

  const mergedIntent = {
    productMatchTerms: collectUniqueTerms(
      [
        ...(aiIntent?.productMatchTerms || []),
        ...deterministicIntent.productMatchTerms,
      ],
      WEBSITE_TEXT_INTENT_MATCH_TERM_LIMIT
    ),
    productSearchQueries: collectUniqueTerms(
      [
        ...(aiIntent?.productSearchQueries || []),
        ...deterministicIntent.productSearchQueries,
      ],
      WEBSITE_TEXT_INTENT_QUERY_LIMIT
    ),
    productAvoidTerms: collectUniqueTerms(
      [
        ...(aiIntent?.productAvoidTerms || []),
        ...deterministicIntent.productAvoidTerms,
      ],
      WEBSITE_TEXT_INTENT_AVOID_LIMIT
    ),
    productSearchIntent:
      aiIntent?.productSearchIntent ||
      deterministicIntent.productSearchIntent,
  };

  return applyWebsiteTextProductIntentToRule(rule, mergedIntent);
}

function getCampaignThemeSourceText(rule) {
  const prompt = String(rule?.prompt || "");

  return normalizeSearchText([
    getCustomerFacingCampaignTheme(rule),
    extractPromptLineValue(prompt, "Campaign"),
    extractPromptLineValue(prompt, "Campaign context"),
    extractPromptLineValue(prompt, "Product selection hint"),
    extractPromptLineValue(prompt, "Product search intent"),
    rule?.campaign_goal,
    rule?.target_customer_need,
    rule?.strategy_notes,
    rule?.marketing_angle,
    prompt,
  ].filter(Boolean).join(" "));
}

function hasAnyCampaignThemeToken(text, tokens) {
  return (tokens || []).some((token) => {
    const value = normalizeSearchText(token).trim();
    return value && (text.includes(value) || new RegExp(`\b${value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\b`, "i").test(text));
  });
}

// Campaign product terms come from AI-generated metadata saved on the rule
// and/or prompt context. Do not infer localized theme words in code; Spreelo
// must work globally across languages and markets.

function extractRawExplicitCampaignMatchTerms(rule) {
  const prompt = String(rule?.prompt || "");
  const imagePrompt = String(rule?.image_prompt || "");
  return collectUniqueTerms(
    [
      ...splitCampaignTermLine(rule?.product_match_terms),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Product match terms")),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Campaign product match terms")),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Product terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Product match terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Campaign product match terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Product terms")),
    ],
    30
  );
}

function campaignTermIsSupportedByCampaignContext(term, rule) {
  const normalizedTerm = normalizeSearchText(term).trim();
  const sourceText = normalizeSearchText(getCampaignAnchorSourceText(rule));

  if (!normalizedTerm || !sourceText) {
    return true;
  }

  if (hasCampaignPhraseMatch(sourceText, normalizedTerm)) {
    return true;
  }

  const termTokens = tokenizeSearchText(normalizedTerm);
  const sourceTokens = tokenizeSearchText(sourceText)
    .filter((word) => word.length >= 4 && !weakShortSearchRoots.has(word));

  if (!termTokens.length || !sourceTokens.length) {
    return true;
  }

  for (const sourceToken of sourceTokens) {
    const compactThemeRoot = getCompactCampaignThemeRoot(sourceToken);

    for (const termToken of termTokens) {
      if (!termToken || termToken.length < 3) continue;

      if (termToken === sourceToken) {
        return true;
      }

      const minLength = Math.min(termToken.length, sourceToken.length);
      const commonLength = getCommonPrefix([termToken, sourceToken]).length;

      if (commonLength >= Math.min(6, minLength) || commonLength >= Math.ceil(minLength * 0.75)) {
        return true;
      }

      if (
        compactThemeRoot &&
        (termToken === compactThemeRoot ||
          (termToken.startsWith(compactThemeRoot) && termToken.length >= compactThemeRoot.length + 2))
      ) {
        return true;
      }
    }
  }

  return false;
}

function filterCampaignMatchTermsForRule(terms, rule) {
  const rawTerms = collectUniqueTerms(terms, 30);

  if (!rawTerms.length || !isCampaignScopedWebsiteRule(rule)) {
    return rawTerms;
  }

  const filteredTerms = rawTerms.filter((term) =>
    campaignTermIsSupportedByCampaignContext(term, rule)
  );

  return filteredTerms.length ? filteredTerms : rawTerms;
}

function getCampaignTermAnchorTokensForRule(rule) {
  const sourceText = normalizeSearchText(getCampaignAnchorSourceText(rule));
  const tokens = sourceText
    .split(/[^\p{L}\p{N}]+/u)
    .map((word) => word.trim())
    .filter((word) => word.length >= 3 && !/^\d+$/.test(word) && !weakShortSearchRoots.has(word));
  const anchors = [];
  const seen = new Set();

  for (const token of tokens) {
    const compactRoot = getCompactCampaignThemeRoot(token);

    for (const value of [compactRoot, token]) {
      if (!value || seen.has(value)) {
        continue;
      }

      seen.add(value);
      anchors.push(value);

      if (anchors.length >= 10) {
        return anchors;
      }
    }
  }

  return anchors;
}

function anchorCampaignTermsForRule(terms, rule, limit = 30) {
  const rawTerms = collectUniqueTerms(terms, limit);

  if (!rawTerms.length || !isCampaignScopedWebsiteRule(rule)) {
    return rawTerms;
  }

  const anchorTokens = getCampaignTermAnchorTokensForRule(rule);
  const primaryAnchor = anchorTokens.find(Boolean);

  if (!primaryAnchor) {
    return rawTerms;
  }

  return collectUniqueTerms(
    rawTerms.map((term) =>
      campaignTermIsSupportedByCampaignContext(term, rule)
        ? term
        : `${primaryAnchor} ${term}`.slice(0, 70)
    ),
    limit
  );
}

function extractExplicitCampaignMatchTerms(rule) {
  return filterCampaignMatchTermsForRule(
    extractRawExplicitCampaignMatchTerms(rule),
    rule
  );
}

function extractCampaignAvoidTerms(rule) {
  const prompt = String(rule?.prompt || "");
  const imagePrompt = String(rule?.image_prompt || "");
  return collectUniqueTerms(
    [
      ...splitCampaignTermLine(rule?.product_avoid_terms),
      ...splitCampaignTermLine(rule?.avoid_terms),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Avoid product terms")),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Avoid terms")),
      ...splitCampaignTermLine(extractPromptLineValue(prompt, "Campaign avoid terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Avoid product terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Avoid terms")),
      ...splitCampaignTermLine(extractPromptLineValue(imagePrompt, "Campaign avoid terms")),
    ],
    30
  );
}

function extractCampaignTerms(rule) {
  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const prompt = String(rule?.prompt || "");
  const source = [
    getCustomerFacingCampaignTheme(rule),
    extractPromptLineValue(prompt, "Campaign"),
    extractPromptLineValue(prompt, "Product selection hint"),
    extractPromptLineValue(prompt, "Campaign context"),
    rule?.campaign_goal,
    rule?.target_customer_need,
    rule?.strategy_notes,
    rule?.marketing_angle,
    prompt,
  ]
    .filter(Boolean)
    .join(" ");

  const normalized = normalizeSearchText(source);
  const rawWords = normalized
    .split(/[^\p{L}\p{N}]+/u)
    .map((word) => word.trim())
    .filter((word) => word.length >= 4 && !/^\d+$/.test(word));

  const seen = new Set();
  const terms = [];

  for (const word of [...explicitTerms, ...rawWords]) {
    if (seen.has(word)) {
      continue;
    }
    seen.add(word);
    terms.push(word);
    if (terms.length >= 24) {
      break;
    }
  }

  return terms;
}

function getCommonPrefix(values) {
  const words = (values || []).filter(Boolean);

  if (!words.length) {
    return "";
  }

  let prefix = words[0];

  for (const word of words.slice(1)) {
    let index = 0;
    const maxLength = Math.min(prefix.length, word.length);

    while (index < maxLength && prefix[index] === word[index]) {
      index += 1;
    }

    prefix = prefix.slice(0, index);

    if (!prefix) {
      break;
    }
  }

  return prefix;
}

function getCampaignTermWords(terms) {
  return (terms || [])
    .flatMap((term) =>
      normalizeSearchText(term)
        .split(/[^\p{L}\p{N}]+/u)
        .map((word) => word.trim())
    )
    .filter((word) => word.length >= 3 && !/^\d+$/.test(word));
}

function isUsefulShortCampaignRoot(term) {
  const value = normalizeSearchText(term).trim();

  return (
    value.length >= 3 &&
    value.length <= 6 &&
    !/^\d+$/.test(value) &&
    !weakShortSearchRoots.has(value)
  );
}

function extractCompactPrimaryCampaignRoots(explicitTerms) {
  const normalizedExplicitTerms = collectUniqueTerms(explicitTerms, 40);
  const words = getCampaignTermWords(normalizedExplicitTerms);
  const groupedByPrefix = new Map();

  // Only keep very short direct terms when AI explicitly supplied that exact
  // term as a campaign/product match term. This avoids accidental roots from
  // broad business words while staying language-neutral.
  const directShortTerms = words.filter((word) =>
    isUsefulShortCampaignRoot(word) &&
    normalizedExplicitTerms.some((term) => term === word)
  );

  for (const word of words.filter((term) => term.length >= 6)) {
    const key = word.slice(0, 3);

    if (!isUsefulShortCampaignRoot(key)) {
      continue;
    }

    if (!groupedByPrefix.has(key)) {
      groupedByPrefix.set(key, new Set());
    }

    groupedByPrefix.get(key).add(word);
  }

  const sharedRoots = [];

  for (const groupSet of groupedByPrefix.values()) {
    const group = Array.from(groupSet);

    // A short root is useful only when several explicit AI-created terms point
    // to the same theme root. A single long term must not create a broad
    // three-letter root by itself.
    if (group.length < 2) {
      continue;
    }

    const prefix = getCommonPrefix(group);

    if (isUsefulShortCampaignRoot(prefix)) {
      sharedRoots.push(prefix);
    } else if (prefix.length > 6) {
      const compactRoot = prefix.slice(0, 3);

      if (isUsefulShortCampaignRoot(compactRoot)) {
        sharedRoots.push(compactRoot);
        sharedRoots.push(prefix);
      }
    }
  }

  return collectUniqueTerms([...directShortTerms, ...sharedRoots], 8);
}

function extractPrimaryCampaignTerms(rule) {
  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const compactPrimaryRoots = extractCompactPrimaryCampaignRoots(explicitTerms);
  const prompt = String(rule?.prompt || "");
  const source = [
    getCustomerFacingCampaignTheme(rule),
    extractPromptLineValue(prompt, "Campaign"),
    extractPromptLineValue(prompt, "Campaign context"),
    rule?.campaign_goal,
  ]
    .filter(Boolean)
    .join(" ");

  const normalized = normalizeSearchText(source);
  const rawWords = normalized
    .split(/[^\p{L}\p{N}]+/u)
    .map((word) => word.trim())
    .filter((word) => word.length >= 5 && !/^\d+$/.test(word));

  const seen = new Set();
  const terms = [];

  for (const word of [...explicitTerms, ...compactPrimaryRoots, ...rawWords]) {
    if (seen.has(word)) {
      continue;
    }
    seen.add(word);
    terms.push(word);
    if (terms.length >= 10) {
      break;
    }
  }

  return terms;
}

function getPrimaryCampaignShortRoots(rule) {
  return new Set(extractCompactPrimaryCampaignRoots(extractExplicitCampaignMatchTerms(rule)));
}

function hasCampaignPhraseMatch(text, term) {
  const normalizedText = normalizeSearchText(text);
  const normalizedTerm = normalizeSearchText(term).trim();

  if (!normalizedText || !normalizedTerm) {
    return false;
  }

  const escapedTerm = normalizedTerm.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(^|[^\p{L}\p{N}])${escapedTerm}([^\p{L}\p{N}]|$)`, "u").test(normalizedText);
}

function tokenizeSearchText(value) {
  return normalizeSearchText(value)
    .split(/[^\p{L}\p{N}]+/u)
    .map((token) => token.trim())
    .filter(Boolean);
}

function getWebsiteItemCampaignText(item) {
  return [
    item?.title,
    item?.url,
    item?.product_url,
    item?.item_url,
    item?.source_url,
    item?.description,
    item?.reason,
    item?.catalog_source,
    item?.discovery_source,
    item?.campaign_fit_source,
  ]
    .filter(Boolean)
    .join(" ");
}

function getWebsiteItemDirectCampaignText(item) {
  return [
    item?.title,
    item?.url,
    item?.product_url,
    item?.item_url,
    item?.description,
    item?.category,
    ...(Array.isArray(item?.tags) ? item.tags : []),
  ]
    .filter(Boolean)
    .join(" ");
}

function getCampaignTitleCandidates(rule) {
  const prompt = String(rule?.prompt || "");
  const imagePrompt = String(rule?.image_prompt || "");

  return collectUniqueTerms(
    [
      getCustomerFacingCampaignTheme(rule),
      extractPromptLineValue(prompt, "Campaign"),
      extractPromptLineValue(prompt, "Campaign title"),
      extractPromptLineValue(prompt, "Campaign name"),
      extractPromptLineValue(imagePrompt, "Campaign"),
      extractPromptLineValue(imagePrompt, "Campaign title"),
      extractPromptLineValue(imagePrompt, "Campaign name"),
    ].filter(Boolean),
    8
  );
}

function getCampaignCoreTitleSegment(value) {
  // The campaign meaning is semantic, not positional. A dash, colon or other
  // delimiter has no privileged meaning and the complete title is retained.
  return String(value || "").trim();
}

function getCompactCampaignThemeRoot(word) {
  const value = normalizeSearchText(word).trim();

  // Long compound campaign words can contain the useful search root at the
  // beginning. Keep this generic and only use it for longer words so ordinary
  // short words do not become noisy roots.
  if (value.length < 10) {
    return "";
  }

  const root = value.slice(0, 3);

  return isUsefulShortCampaignRoot(root) ? root : "";
}

function extractCampaignTitleThemeTerms(rule) {
  const contract = getCampaignThemeContract(rule);
  if (contract) {
    return contract.essentialThemeTerms;
  }

  const terms = [];

  for (const candidate of getCampaignTitleCandidates(rule)) {
    const segment = getCampaignCoreTitleSegment(candidate);
    const words = tokenizeSearchText(segment).filter(
      (word) =>
        word.length >= 3 &&
        !/^\d+$/.test(word) &&
        !weakShortSearchRoots.has(word)
    );
    const phraseWords = words.slice(0, 3);

    if (phraseWords.length >= 2) {
      terms.push(phraseWords.join(" "));
    }

    const primaryWord = words.find((word) => word.length >= 4);
    if (!primaryWord) continue;

    terms.push(primaryWord);
    const compactRoot = getCompactCampaignThemeRoot(primaryWord);
    if (compactRoot) {
      terms.push(compactRoot);
    }
  }

  return collectUniqueTerms(terms, 8);
}

function extractCampaignCoreThemeTerms(rule) {
  const contract = getCampaignThemeContract(rule);
  if (contract) {
    return contract.essentialThemeTerms;
  }

  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const explicitRoots = extractCompactPrimaryCampaignRoots(explicitTerms);
  const titleCandidates = getCampaignTitleCandidates(rule);
  const terms = [...explicitRoots];

  for (const candidate of titleCandidates) {
    const segment = getCampaignCoreTitleSegment(candidate);
    const words = tokenizeSearchText(segment)
      .filter((word) => word.length >= 3 && !/^\d+$/.test(word));
    const phraseWords = words.slice(0, 3);

    // Preserve the meaningful campaign-title phrase, but do not turn every
    // following product/category word into a hard theme guard. In a title such
    // as “Halloween Candy”, “Halloween” is the occasion while “candy” describes
    // the assortment. Treating both as equal core themes allowed ordinary candy
    // to pass as Halloween-specific.
    if (phraseWords.length >= 2) {
      terms.push(phraseWords.join(" "));
    }

    const primaryWord = words.find(
      (word) => word.length >= 4 && !weakShortSearchRoots.has(word)
    );

    if (primaryWord) {
      terms.push(primaryWord);

      const compactRoot = getCompactCampaignThemeRoot(primaryWord);
      if (compactRoot) {
        terms.push(compactRoot);
      }
    }
  }

  return collectUniqueTerms(terms, 10);
}

function countCampaignThemeTermMatchesInText(value, rule) {
  const terms = extractCampaignCoreThemeTerms(rule);

  if (!terms.length) {
    return 0;
  }

  const campaignText = normalizeSearchText(value);
  const tokenSet = new Set(tokenizeSearchText(campaignText));
  const shortRoots = new Set(terms.filter(isUsefulShortCampaignRoot));
  let matches = 0;

  for (const term of terms) {
    if (hasStrongCampaignTermMatchAgainstTokens({ campaignText, tokens: tokenSet, term, shortRoots })) {
      matches += 1;
    }
  }

  return matches;
}

function countCampaignCoreThemeTermMatches(item, rule) {
  return countCampaignThemeTermMatchesInText(getWebsiteItemDirectCampaignText(item), rule);
}

function extractCampaignContextualProductTerms(rule) {
  const contract = getCampaignThemeContract(rule);
  const strategy = normalizeCampaignMarketingStrategy(
    rule?.campaign_marketing_strategy
  );
  const directions = normalizeCampaignStrategyList(
    [
      ...(contract?.secondaryContext || []),
      ...(strategy?.contextualProductDirections || []),
      ...(strategy?.selectionSlots || []).flatMap((slot) => [
        ...(slot?.preferredProductTypes || []),
        ...(slot?.searchQueries || []),
      ]),
    ],
    24,
    100
  );
  const directionWords = directions
    .flatMap((direction) => tokenizeSearchText(direction))
    .filter(
      (word) =>
        word.length >= 4 &&
        !/^\d+$/u.test(word) &&
        !weakShortSearchRoots.has(word)
    );

  return collectUniqueTerms([...directions, ...directionWords], 40);
}

function countCampaignContextualProductMatches(item, rule) {
  return countCampaignSearchTermMatches(
    getWebsiteItemDirectCampaignText(item),
    extractCampaignContextualProductTerms(rule)
  );
}

function getWebsiteItemCampaignSourceText(item) {
  const sourceValues = [
    item?.source_page_url,
    item?.source_url,
    item?.website_url,
    item?.catalog_source_url,
    item?.discovery_url,
    item?.reason,
    item?.catalog_source,
    item?.discovery_source,
    item?.campaign_fit_source,
  ].filter(Boolean);

  return sourceValues
    .flatMap((value) => {
      const raw = String(value || "");
      const plusAsSpace = raw.replace(/\+/g, " ");

      try {
        return [raw, decodeURIComponent(plusAsSpace)];
      } catch {
        return [raw, plusAsSpace];
      }
    })
    .join(" ");
}

function isLikelyCampaignFocusedSourceText(value) {
  const text = normalizeSearchText(value);

  if (!text) {
    return false;
  }

  return /(^|[\s/_.?=&-])(collection|collections|category|categories|kategori|kategorier|produktkategori|search|sok|sokning|products)([\s/_.?=&-]|$)/u.test(text);
}

function countCampaignSourceThemeMatches(item, rule) {
  const sourceText = getWebsiteItemCampaignSourceText(item);

  if (!isLikelyCampaignFocusedSourceText(sourceText)) {
    return 0;
  }

  return countCampaignThemeTermMatchesInText(sourceText, rule);
}

function getCampaignThemeSourceLockedItems(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  if (!extractCampaignCoreThemeTerms(rule).length) {
    return [];
  }

  return dedupeWebsiteItemsByUrlTitleAndImage(items)
    .map((item) => ({
      ...item,
      campaign_source_theme_matches: countCampaignSourceThemeMatches(item, rule),
      campaign_theme_term_matches: countCampaignCoreThemeTermMatches(item, rule),
      primary_campaign_term_matches: countPrimaryCampaignTermMatches(item, rule),
    }))
    .filter((item) => Number(item.campaign_source_theme_matches || 0) > 0)
    .sort((a, b) => {
      const sourceDelta =
        Number(b.campaign_source_theme_matches || 0) -
        Number(a.campaign_source_theme_matches || 0);
      if (sourceDelta !== 0) return sourceDelta;

      const themeDelta =
        Number(b.campaign_theme_term_matches || 0) -
        Number(a.campaign_theme_term_matches || 0);
      if (themeDelta !== 0) return themeDelta;

      const primaryDelta =
        Number(b.primary_campaign_term_matches || 0) -
        Number(a.primary_campaign_term_matches || 0);
      if (primaryDelta !== 0) return primaryDelta;

      return scoreWebsiteItemForRule(b, rule) - scoreWebsiteItemForRule(a, rule);
    });
}

function getCampaignThemeMatchedItems(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  if (!extractCampaignCoreThemeTerms(rule).length) {
    return [];
  }

  return dedupeWebsiteItemsByUrlTitleAndImage(items)
    .map((item) => ({
      ...item,
      campaign_theme_term_matches: countCampaignCoreThemeTermMatches(item, rule),
      primary_campaign_term_matches: countPrimaryCampaignTermMatches(item, rule),
    }))
    .filter((item) => Number(item.campaign_theme_term_matches || 0) > 0)
    .sort((a, b) => {
      const themeDelta =
        Number(b.campaign_theme_term_matches || 0) -
        Number(a.campaign_theme_term_matches || 0);
      if (themeDelta !== 0) return themeDelta;

      const primaryDelta =
        Number(b.primary_campaign_term_matches || 0) -
        Number(a.primary_campaign_term_matches || 0);
      if (primaryDelta !== 0) return primaryDelta;

      return scoreWebsiteItemForRule(b, rule) - scoreWebsiteItemForRule(a, rule);
    });
}

function isLikelyGenericCustomTemplateProduct(item) {
  const directText = normalizeSearchText(getWebsiteItemDirectCampaignText(item));

  if (!directText) {
    return false;
  }

  const genericTemplatePatterns = [
    /\bditt\s+tryck\b/u,
    /\beget\s+tryck\b/u,
    /\bpersonligt\s+tryck\b/u,
    /\bdesigna\s+sjalv\b/u,
    /\bdesigna\s+dina\s+egna\b/u,
    /\btryckta\s+klader\b/u,
    /\bskapa\s+din\s+unika\b/u,
    /\begna\s+tryckta\b/u,
    /\btryck\s+har\b/u,
    /\byour\s+(?:text|logo|design|print)\b/u,
    /\badd\s+your\s+(?:text|logo|design)\b/u,
    /\bcustom\s+(?:text|logo|design|print)\b/u,
    /\bpersonalized\s+(?:text|logo|design|print)\b/u,
    /\bdesign\s+your\s+own\b/u,
  ];

  return genericTemplatePatterns.some((pattern) => pattern.test(directText));
}

function preferConcreteCampaignProducts(items) {
  const dedupedItems = dedupeWebsiteItemsByUrlTitleAndImage(items);
  const concreteItems = dedupedItems.filter(
    (item) => !isLikelyVisuallyEmptyProductTemplate(item)
  );

  return concreteItems.length ? concreteItems : [];
}


function getCampaignAnchorSourceText(rule) {
  const prompt = String(rule?.prompt || "");
  const imagePrompt = String(rule?.image_prompt || "");

  return [
    getCustomerFacingCampaignTheme(rule),
    extractPromptLineValue(prompt, "Campaign"),
    extractPromptLineValue(prompt, "Campaign title"),
    extractPromptLineValue(prompt, "Campaign name"),
    extractPromptLineValue(prompt, "Campaign context"),
    extractPromptLineValue(prompt, "Product selection guidance"),
    extractPromptLineValue(imagePrompt, "Campaign"),
    extractPromptLineValue(imagePrompt, "Campaign title"),
    extractPromptLineValue(imagePrompt, "Campaign name"),
    extractPromptLineValue(imagePrompt, "Campaign context"),
    rule?.campaign_goal,
  ]
    .filter(Boolean)
    .join(" ");
}

function isCampaignTermRelatedToCompactRoots(term, roots) {
  const normalizedTerm = normalizeSearchText(term).trim();
  const tokens = tokenizeSearchText(normalizedTerm);

  if (!normalizedTerm || !Array.isArray(roots) || !roots.length) {
    return false;
  }

  return roots.some((root) => (
    normalizedTerm === root ||
    hasCampaignPhraseMatch(normalizedTerm, root) ||
    tokens.some((token) => token.startsWith(root) && token.length >= root.length + 2)
  ));
}

function extractCampaignAnchorTerms(rule) {
  const source = normalizeSearchText(getCampaignAnchorSourceText(rule));
  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const compactPrimaryRoots = extractCompactPrimaryCampaignRoots(explicitTerms);
  const explicitWords = new Set(getCampaignTermWords(explicitTerms));
  const sourceWords = source
    .split(/[^\p{L}\p{N}]+/u)
    .map((word) => word.trim())
    .filter((word) => word.length >= 4 && !/^\d+$/.test(word) && !weakShortSearchRoots.has(word));

  const anchors = [];
  const seen = new Set();

  for (const root of compactPrimaryRoots) {
    if (!seen.has(root)) {
      anchors.push(root);
      seen.add(root);
    }
  }

  for (const word of sourceWords) {
    if (compactPrimaryRoots.length && !isCampaignTermRelatedToCompactRoots(word, compactPrimaryRoots)) {
      continue;
    }

    const derivedRootTerms = [];
    const supportedByExplicitTerm = explicitWords.has(word) || Array.from(explicitWords).some((explicitWord) => {
      if (!explicitWord || explicitWord.length < 4 || word.length < 4) return false;
      const minLength = Math.min(explicitWord.length, word.length);
      const commonPrefix = getCommonPrefix([explicitWord, word]);
      const commonLength = commonPrefix.length;

      if (commonLength >= Math.min(6, minLength) || commonLength >= Math.ceil(minLength * 0.75)) {
        const compactRoot = commonPrefix.slice(0, 3);

        if (commonPrefix.length > 6 && isUsefulShortCampaignRoot(compactRoot)) {
          derivedRootTerms.push(compactRoot, commonPrefix);
        }
      }

      return commonLength >= Math.min(6, minLength) || commonLength >= Math.ceil(minLength * 0.75);
    });

    // Prefer campaign-title/context terms that AI also reflected in the dynamic
    // product_match_terms. This keeps generic business words from becoming hard
    // product filters while still allowing language-specific roots without
    // hardcoding any theme language.
    if (!supportedByExplicitTerm && explicitTerms.length) {
      continue;
    }

    for (const derivedRootTerm of derivedRootTerms) {
      if (!seen.has(derivedRootTerm)) {
        anchors.push(derivedRootTerm);
        seen.add(derivedRootTerm);
      }
    }

    if (!seen.has(word)) {
      anchors.push(word);
      seen.add(word);
    }

    if (anchors.length >= 8) break;
  }

  return anchors;
}

function hasStrongCampaignTermMatchAgainstTokens({ campaignText, tokens, term, shortRoots }) {
  if (!term) return false;

  if (tokens.has(term) || hasCampaignPhraseMatch(campaignText, term)) {
    return true;
  }

  if (
    shortRoots?.has(term) &&
    Array.from(tokens).some((token) => token.startsWith(term) && token.length >= term.length + 2)
  ) {
    return true;
  }

  if (term.length >= 6) {
    for (const token of tokens) {
      if (!token || token.length < 4) continue;
      const minLength = Math.min(token.length, term.length);
      const commonLength = getCommonPrefix([token, term]).length;

      // Handles normal inflections/plurals without requiring language-specific
      // rules. This is a support for the campaign anchor, not a generic
      // substring match.
      if (commonLength >= Math.min(7, minLength) || commonLength >= Math.ceil(minLength * 0.8)) {
        return true;
      }
    }
  }

  return false;
}

function countCampaignAnchorTermMatches(item, rule) {
  const terms = extractCampaignAnchorTerms(rule);

  if (!terms.length) {
    return 0;
  }

  const campaignText = getWebsiteItemDirectCampaignText(item);
  const tokenSet = new Set(tokenizeSearchText(campaignText));
  const shortRoots = getPrimaryCampaignShortRoots(rule);
  let matches = 0;

  for (const term of terms) {
    if (hasStrongCampaignTermMatchAgainstTokens({ campaignText, tokens: tokenSet, term, shortRoots })) {
      matches += 1;
    }
  }

  return matches;
}

function getCampaignAnchorMatchedItems(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  const anchorTerms = extractCampaignAnchorTerms(rule);

  if (!anchorTerms.length) {
    return [];
  }

  return dedupeWebsiteItemsByUrlTitleAndImage(items)
    .map((item) => ({
      ...item,
      campaign_anchor_term_matches: countCampaignAnchorTermMatches(item, rule),
      primary_campaign_term_matches: countPrimaryCampaignTermMatches(item, rule),
    }))
    .filter((item) => Number(item.campaign_anchor_term_matches || 0) > 0)
    .sort((a, b) => {
      const anchorDelta = Number(b.campaign_anchor_term_matches || 0) - Number(a.campaign_anchor_term_matches || 0);
      if (anchorDelta !== 0) return anchorDelta;

      const primaryDelta = Number(b.primary_campaign_term_matches || 0) - Number(a.primary_campaign_term_matches || 0);
      if (primaryDelta !== 0) return primaryDelta;

      return scoreWebsiteItemForRule(b, rule) - scoreWebsiteItemForRule(a, rule);
    });
}

function countPrimaryCampaignTermMatches(item, rule) {
  const terms = extractPrimaryCampaignTerms(rule);

  if (!terms.length) {
    return 0;
  }

  const campaignText = getWebsiteItemDirectCampaignText(item);
  const tokens = tokenizeSearchText(campaignText);
  const tokenSet = new Set(tokens);
  const shortRoots = getPrimaryCampaignShortRoots(rule);
  let matches = 0;

  for (const term of terms) {
    if (!term) {
      continue;
    }

    if (hasStrongCampaignTermMatchAgainstTokens({
      campaignText,
      tokens: tokenSet,
      term,
      shortRoots,
    })) {
      matches += 1;
    }
  }

  return matches;
}

function getPrimaryCampaignMatchedItems(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  return dedupeWebsiteItemsByUrlTitleAndImage(items)
    .map((item) => ({
      ...item,
      primary_campaign_term_matches: countPrimaryCampaignTermMatches(item, rule),
    }))
    .filter((item) => Number(item.primary_campaign_term_matches || 0) > 0)
    .sort((a, b) => {
      const matchDelta =
        Number(b.primary_campaign_term_matches || 0) -
        Number(a.primary_campaign_term_matches || 0);
      if (matchDelta !== 0) return matchDelta;

      return scoreWebsiteItemForRule(b, rule) - scoreWebsiteItemForRule(a, rule);
    });
}

function getCampaignStoreSearchQuery(item) {
  // Audit-only provenance label retained for diagnostics:
  // Found by retailer search query:
  // This value is deliberately excluded from both AI product-fit prompts.
  return normalizeSearchText(
    item?.found_by_query ||
      getStoreSearchQueryFromUrl(item?.source_search_url) ||
      ""
  )
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function hasTrustedCampaignStoreSearchSignal(item, rule) {
  const foundByQuery = getCampaignStoreSearchQuery(item);
  const sourceSearchUrl = String(item?.source_search_url || "").trim();

  if (!foundByQuery || !sourceSearchUrl) {
    return false;
  }

  const configuredQueries = normalizeStoreSearchQueries(
    splitStoreSearchQueryLine(rule?.product_search_queries),
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  ).map((query) => normalizeSearchText(query).replace(/[-_]+/g, " ").trim());

  return configuredQueries.some(
    (query) =>
      query &&
      (query === foundByQuery ||
        query.includes(foundByQuery) ||
        foundByQuery.includes(query))
  );
}

function getCampaignProductAcceptanceScore(item, rule) {
  return CAMPAIGN_STORE_SEARCH_PRODUCT_FIT_SCORE;
}

function getSafeCampaignProductCandidates(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  const themeContract = getCampaignThemeContract(rule);
  if (themeContract) {
    return preferConcreteCampaignProducts(
      dedupeWebsiteItemsByUrlTitleAndImage(items)
        .map((item) => ({
          ...item,
          campaign_theme_term_matches:
            countCampaignCoreThemeTermMatches(item, rule),
        }))
        .filter(
          (item) =>
            getCampaignProductSignalState(
              item,
              rule,
              CAMPAIGN_STORE_SEARCH_PRODUCT_FIT_SCORE
            ).hasMeaningfulCampaignSignal
        )
        .sort((left, right) => {
          const evidenceDelta =
            Number(right.campaign_theme_term_matches || 0) -
            Number(left.campaign_theme_term_matches || 0);
          if (evidenceDelta !== 0) return evidenceDelta;

          const aiDelta =
            Number(getAiCampaignFitScore(right) ?? -1) -
            Number(getAiCampaignFitScore(left) ?? -1);
          if (aiDelta !== 0) return aiDelta;

          return (
            scoreWebsiteItemForRule(right, rule) -
            scoreWebsiteItemForRule(left, rule)
          );
        })
    );
  }

  const dedupedItems = dedupeWebsiteItemsByUrlTitleAndImage(items).filter((item) => {
    const aiScore = getAiCampaignFitScore(item);

    if (isCampaignFitRejectedForRule(item, rule)) {
      return false;
    }

    // A concrete product verified from a campaign-created retailer search is
    // already backed by useful retrieval context. Keep medium product-level
    // matches available instead of requiring every title to name the occasion.
    return aiScore === null || aiScore >= getCampaignProductAcceptanceScore(item, rule);
  });
  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const anchorTerms = extractCampaignAnchorTerms(rule);
  const themeTerms = extractCampaignCoreThemeTerms(rule);
  const themeSourceLockedItems = getCampaignThemeSourceLockedItems(dedupedItems, rule);
  const themeMatchedItems = getCampaignThemeMatchedItems(dedupedItems, rule);
  const anchorMatchedItems = getCampaignAnchorMatchedItems(dedupedItems, rule);
  const primaryMatchedItems = getPrimaryCampaignMatchedItems(dedupedItems, rule);
  const concreteThemeSourceLockedItems = preferConcreteCampaignProducts(themeSourceLockedItems);
  const concreteThemeMatchedItems = preferConcreteCampaignProducts(themeMatchedItems);
  const concreteAnchorMatchedItems = preferConcreteCampaignProducts(anchorMatchedItems);
  const concretePrimaryMatchedItems = preferConcreteCampaignProducts(primaryMatchedItems);
  const aiApprovedItems = preferConcreteCampaignProducts(
    dedupedItems.filter((item) => {
      const aiScore = getAiCampaignFitScore(item);
      return aiScore !== null && aiScore >= getCampaignProductAcceptanceScore(item, rule);
    })
  );
  const safeSourceLockedItems = concreteThemeSourceLockedItems.filter((item) =>
    getCampaignProductSignalState(
      item,
      rule,
      getCampaignProductAcceptanceScore(item, rule)
    ).hasMeaningfulCampaignSignal
  );

  // Search/category pages are discovery sources only. Every product must still
  // prove its own campaign relevance through its product data or an AI fit score.
  if (themeTerms.length || anchorTerms.length) {
    return dedupeWebsiteItemsByUrlTitleAndImage([
      ...concreteThemeMatchedItems,
      ...concreteAnchorMatchedItems,
      ...aiApprovedItems,
      ...safeSourceLockedItems,
    ]);
  }

  if (explicitTerms.length) {
    return dedupeWebsiteItemsByUrlTitleAndImage([
      ...concretePrimaryMatchedItems,
      ...aiApprovedItems,
    ]);
  }

  if (concreteAnchorMatchedItems.length || concretePrimaryMatchedItems.length || aiApprovedItems.length) {
    return dedupeWebsiteItemsByUrlTitleAndImage([
      ...concreteAnchorMatchedItems,
      ...concretePrimaryMatchedItems,
      ...aiApprovedItems,
    ]);
  }

  return preferConcreteCampaignProducts(getStrongCampaignFitItems(dedupedItems, rule));
}

function getReviewedOrDirectCampaignProductCandidates(items, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  return preferConcreteCampaignProducts(
    dedupeWebsiteItemsByUrlTitleAndImage(items)
      .filter((item) => {
        const state = getCampaignProductSignalState(
          item,
          rule,
          CAMPAIGN_STORE_SEARCH_PRODUCT_FIT_SCORE
        );

        return (
          !state.explicitlyRejected &&
          (state.hasDirectCampaignSignal || state.hasAiCampaignApproval)
        );
      })
      .sort((left, right) => {
        const leftState = getCampaignProductSignalState(left, rule);
        const rightState = getCampaignProductSignalState(right, rule);
        const directDelta =
          Number(rightState.hasDirectCampaignSignal) -
          Number(leftState.hasDirectCampaignSignal);
        if (directDelta !== 0) return directDelta;

        const aiDelta =
          Number(rightState.aiCampaignFitScore ?? -1) -
          Number(leftState.aiCampaignFitScore ?? -1);
        if (aiDelta !== 0) return aiDelta;

        return (
          scoreWebsiteItemForRule(right, rule) -
          scoreWebsiteItemForRule(left, rule)
        );
      })
  );
}

function getAiCampaignFitScore(item) {
  if (item?.ai_campaign_fit_score === undefined || item?.ai_campaign_fit_score === null) {
    return null;
  }

  const score = Number(item.ai_campaign_fit_score);

  if (!Number.isFinite(score)) {
    return null;
  }

  return Math.min(Math.max(Math.round(score), 0), 100);
}

function normalizeCampaignFitVerdict(value) {
  return normalizeSearchText(value).trim();
}

function getCampaignThemeFitDecision(item) {
  if (item?.campaign_theme_fit === true) return true;
  if (item?.campaign_theme_fit === false) return false;
  return null;
}

function isExplicitCampaignFitRejected(item) {
  return evaluateSimpleCampaignThemeFit({
    fitsTheme: getCampaignThemeFitDecision(item),
    verdict: item?.campaign_fit_verdict,
    score: getAiCampaignFitScore(item),
  }).rejected;
}

function hasDirectCampaignEvidenceForRule(item, rule) {
  return Math.max(
    countCampaignCoreThemeTermMatches(item, rule),
    countCampaignAnchorTermMatches(item, rule),
    countPrimaryCampaignTermMatches(item, rule)
  ) > 0;
}

function isCampaignFitRejectedForRule(item, rule) {
  // Once either AI review explicitly rejects a product, discovery keywords or
  // a search-page theme match must never revive it. This keeps the delivery
  // guarantee from publishing a product that the curator already ruled out.
  return isExplicitCampaignFitRejected(item);
}

function isCampaignThemeFitApproved(item) {
  return evaluateSimpleCampaignThemeFit({
    fitsTheme: getCampaignThemeFitDecision(item),
    verdict: item?.campaign_fit_verdict,
    score: getAiCampaignFitScore(item),
  }).approved;
}

function getCampaignProductSignalState(
  item,
  rule,
  minimumAiScore = CAMPAIGN_NEAR_PRODUCT_FIT_SCORE
) {
  const themeMatches = countCampaignCoreThemeTermMatches(item, rule);
  const sourceThemeMatches = countCampaignSourceThemeMatches(item, rule);
  const anchorMatches = countCampaignAnchorTermMatches(item, rule);
  const primaryMatches = countPrimaryCampaignTermMatches(item, rule);
  const hasTrustedStoreSearchSignal = hasTrustedCampaignStoreSearchSignal(item, rule);
  const aiCampaignFitScore = getAiCampaignFitScore(item);
  const themeFitDecision = getCampaignThemeFitDecision(item);
  const campaignFitVerdict = normalizeCampaignFitVerdict(
    item?.campaign_fit_verdict
  );
  const contextualProductMatches = countCampaignContextualProductMatches(
    item,
    rule
  );
  const hasTrustedPrimaryWebResearchSignal =
    isPrimaryCampaignWebResearchProduct(item);
  const coreThemeTerms = extractCampaignCoreThemeTerms(rule);
  const anchorTerms = extractCampaignAnchorTerms(rule);
  const hasCoreThemeGuard = coreThemeTerms.length > 0;
  const hasAnchorGuard = !hasCoreThemeGuard && anchorTerms.length > 0;
  const hasStrictThemeGuard = hasCoreThemeGuard || hasAnchorGuard;

  // When the campaign has a clear occasion/theme such as Halloween, Christmas
  // or Mother's Day, generic product words from the title (for example
  // T-shirt, print, gift or hoodie) must not count as proof of theme relevance.
  // Anchor terms are only allowed as the hard guard when no core theme could be
  // derived at all.
  const hasDirectCampaignSignal = hasCoreThemeGuard
    ? themeMatches > 0
    : hasAnchorGuard
      ? anchorMatches > 0
      : primaryMatches > 0;
  const hasVerifiedContextualCampaignSignal =
    item?.product_page_verified === true &&
    contextualProductMatches > 0 &&
    hasTrustedStoreSearchSignal;

  const hasAiCampaignEvaluation =
    hasTrustedPrimaryWebResearchSignal ||
    aiCampaignFitScore !== null ||
    themeFitDecision !== null ||
    Boolean(campaignFitVerdict);
  const explicitlyRejected = isCampaignFitRejectedForRule(item, rule);
  const hasAiCampaignApproval =
    hasAiCampaignEvaluation &&
    !explicitlyRejected &&
    (
      hasTrustedPrimaryWebResearchSignal ||
      isCampaignThemeFitApproved(item)
    );
  const fallbackEligibility = evaluateCampaignFallbackEligibility({
    explicitlyRejected,
    hasAiEvaluation: hasAiCampaignEvaluation,
    hasAiApproval: hasAiCampaignApproval,
    hasDirectThemeEvidence: hasDirectCampaignSignal,
    productPageVerified: item?.product_page_verified === true,
    contextualProductMatches,
    trustedCampaignSearch: hasTrustedStoreSearchSignal,
  });
  const relevanceTier = hasDirectCampaignSignal
    ? "direct"
    : hasAiCampaignApproval || hasVerifiedContextualCampaignSignal
      ? "contextual"
      : "reject";

  return {
    themeMatches,
    sourceThemeMatches,
    anchorMatches,
    primaryMatches,
    contextualProductMatches,
    aiCampaignFitScore,
    hasCoreThemeGuard,
    hasAnchorGuard,
    hasStrictThemeGuard,
    hasTrustedStoreSearchSignal,
    hasTrustedPrimaryWebResearchSignal,
    hasDirectCampaignSignal,
    hasVerifiedContextualCampaignSignal,
    hasAiCampaignEvaluation,
    explicitlyRejected,
    hasAiCampaignApproval,
    relevanceTier,
    contextualCampaignApproval:
      !hasDirectCampaignSignal &&
      (hasAiCampaignApproval || hasVerifiedContextualCampaignSignal),
    campaignRole: normalizeCampaignStrategyText(
      item?.campaign_role,
      220
    ),
    campaignRelevanceEvidence: normalizeCampaignRelevanceEvidence(
      item?.campaign_relevance_evidence ||
        item?.campaign_final_review_evidence,
      8
    ),
    // A product-level AI verdict normally wins, but direct evidence in the
    // concrete product itself must not be vetoed by a broad category avoid term.
    // Search/category context alone still cannot override a rejection.
    hasMeaningfulCampaignSignal: fallbackEligibility.approved,
  };
}

function normalizeCampaignFitScore(value) {
  const score = Number(value);

  if (!Number.isFinite(score)) {
    return 0;
  }

  return Math.min(Math.max(Math.round(score), 0), 100);
}

function formatProductsForCampaignFitPrompt(candidates) {
  return candidates
    .map(({ item, index }) => {
      const fields = [
        `Index: ${index}`,
        `Title: ${item?.title || "Not provided"}`,
        `URL: ${item?.url || item?.product_url || item?.item_url || "Not provided"}`,
        `Description: ${truncateText(item?.description || "", 500) || "Not provided"}`,
        `Category: ${item?.category || "Not provided"}`,
        `Tags: ${Array.isArray(item?.tags) && item.tags.length ? item.tags.join(", ") : "Not provided"}`,
      ];

      return fields.join("\n");
    })
    .join("\n\n---\n\n");
}

function getReasoningOptionsForModel(model) {
  return /^gpt-5/i.test(String(model || ""))
    ? { reasoning: { effort: "low" } }
    : {};
}

async function evaluateCampaignFitCandidates({
  openai,
  rule,
  brandProfile,
  candidates,
  model,
}) {
  const evaluationByIndex = new Map();
  const batchSize = 20;

  for (let start = 0; start < candidates.length; start += batchSize) {
    const batch = candidates.slice(start, start + batchSize);
    let response;
    try {
      response = await openai.responses.create(
      {
        model,
        ...getReasoningOptionsForModel(model),
        input: `
You are validating product relevance for a social media campaign.

Your job:
Score each candidate product for how well it fits the campaign, buyer intent, recipient/end user, season/occasion/theme, brand, market and audience.

Important:
- Do not use fixed holiday or product keyword lists.
- Infer the campaign meaning from the campaign context, brand profile, market, language and product information.
- Make one simple primary decision: does this concrete product reasonably fit the campaign theme and what this company sells?
- A product can fit directly through its wording/motif or naturally through its use, recipient, season, style or buying situation. It does not need to repeat the campaign word.
- Explain the real reason it fits. Do not demand a formal evidence chain or a theme word in the title.
- A generic category, collection, search, brand, guide or landing page must score 0 even if its title matches the campaign.
- Reject only products that are clearly unrelated, not concrete products, or conflict with the campaign.
- You are intentionally not shown the retailer search query or discovery source. Judge only the verified product facts. Retrieval provenance is never product-level evidence.
- Audience or recipient terms describe who may use or receive a product; they are not proof that the product expresses the campaign occasion/theme.
- A product explicitly made for another recipient, occasion or theme must not be promoted as a direct match merely because it shares a generic product type or buying context.
- Treat an explicit recipient or audience conflict as does_not_fit. For example, when the campaign is expressly for children, a product identified by its supplied title, category, description or URL as adult womenswear or menswear must not be reinterpreted as youth clothing merely because it could theoretically be worn at school.
- Prefer products that naturally support the campaign reason to buy, not products that merely share generic words with the prompt.
- Do not reward generic words such as product, shop, buy, custom, print, collection, gift, offer, post or social media unless the product itself clearly fits the campaign.
- Treat campaign avoid terms as soft ranking guidance, not as a veto. Direct occasion, motif or theme evidence in the concrete product title or description always overrides a broad avoided category.
- Never reject a theme-specific concrete product merely because its general product category is normally a weak campaign choice.

Score guide:
- 80-100: especially strong choice for this campaign.
- 50-79: reasonably fits the campaign and may be selected.
- 1-49: weak or doubtful fit.
- 0: not a concrete product page, category/listing/search/landing page, or unsafe to use.

Brand profile:
${formatBrandProfileForPrompt(brandProfile)}

Campaign context:
${buildCampaignResearchText(rule) || "No campaign context provided."}

Senior marketing strategy:
${formatCampaignMarketingStrategyForPrompt(rule?.campaign_marketing_strategy) || "No structured strategy was available."}

Candidate products:
${formatProductsForCampaignFitPrompt(batch)}

Return strict JSON only:
{
  "scores": [
    {
      "index": 0,
      "fits_theme": true,
      "score": 0,
      "verdict": "fits | does_not_fit",
      "relevance_class": "direct | contextual | generic | reject",
      "campaign_role": "Specific role this product serves in the campaign, or empty",
      "evidence": ["Supplied product facts that justify the class and role"],
      "reason": "Short reason"
    }
  ]
}
        `.trim(),
      },
      { timeout: CAMPAIGN_FAST_REVIEW_TIMEOUT_MS, maxRetries: 0 }
    );

    } catch (error) {
      console.warn("Campaign fit scoring unavailable; preserving deterministic product ranking", {
        ruleId: rule?.id,
        brandProfileId: rule?.brand_profile_id,
        model,
        batchStart: start,
        batchSize: batch.length,
        transient: isTransientAutomationError(error),
        message: error?.message || String(error),
      });
      continue;
    }

    const parsed = safeJsonParse(response.output_text || "");
    const scores = Array.isArray(parsed?.scores) ? parsed.scores : [];

    for (const entry of scores) {
      const index = Number(entry?.index);

      if (!Number.isInteger(index)) {
        continue;
      }

      const evaluation = {
        fitsTheme:
          entry?.fits_theme === true
            ? true
            : entry?.fits_theme === false
              ? false
              : null,
        score: normalizeCampaignFitScore(entry?.score),
        verdict: String(entry?.verdict || "").trim(),
        relevanceClass: normalizeCampaignRelevanceClass(
          entry?.relevance_class || entry?.relevanceClass
        ),
        campaignRole: normalizeCampaignStrategyText(
          entry?.campaign_role || entry?.campaignRole,
          220
        ),
        evidence: normalizeCampaignRelevanceEvidence(entry?.evidence, 8),
        reason: String(entry?.reason || "").trim(),
        model,
      };

      evaluationByIndex.set(index, {
        ...evaluation,
        evaluations: [evaluation],
      });
    }
  }

  return evaluationByIndex;
}

function applyCampaignFitEvaluations(items, evaluationByIndex) {
  return items.map((item, index) => {
    const evaluation = evaluationByIndex.get(index);

    if (!evaluation) {
      return {
        ...item,
        ai_campaign_fit_score:
          item?.ai_campaign_fit_score === undefined ? null : item.ai_campaign_fit_score,
        campaign_fit_score: Number(item?.campaign_fit_score || item?.score || 0),
        campaign_fit_source: item?.campaign_fit_source || "ai_campaign_fit_unscored",
        campaign_fit_reason:
          item?.campaign_fit_reason || "Not evaluated in campaign fit batch; kept existing heuristic score.",
      };
    }

    const aiCampaignFitSource =
      evaluation.model === PRODUCT_RESEARCH_MODEL
        ? "ai_campaign_fit"
        : "ai_campaign_fit_fast";

    const priorEvaluations = Array.isArray(item?.campaign_fit_evaluations)
      ? item.campaign_fit_evaluations
      : [];
    const currentEvaluations = Array.isArray(evaluation?.evaluations)
      ? evaluation.evaluations
      : [
          {
            model: evaluation.model,
            fitsTheme: evaluation.fitsTheme,
            score: evaluation.score,
            verdict: evaluation.verdict,
            relevanceClass: evaluation.relevanceClass,
            campaignRole: evaluation.campaignRole,
            evidence: evaluation.evidence,
            reason: evaluation.reason,
          },
        ];
    const campaignFitEvaluations = [...priorEvaluations, ...currentEvaluations]
      .filter((entry) => entry && entry.model)
      .map((entry) => ({
        model: String(entry.model || ""),
        fitsTheme:
          entry?.fitsTheme === true
            ? true
            : entry?.fitsTheme === false
              ? false
              : null,
        score: normalizeCampaignFitScore(entry.score),
        verdict: String(entry.verdict || "").trim(),
        relevanceClass: normalizeCampaignRelevanceClass(
          entry.relevanceClass || entry.relevance_class
        ),
        campaignRole: normalizeCampaignStrategyText(
          entry.campaignRole || entry.campaign_role,
          220
        ),
        evidence: normalizeCampaignRelevanceEvidence(entry.evidence, 8),
        reason: String(entry.reason || "").trim(),
      }));
    const fastEvaluation = campaignFitEvaluations.find(
      (entry) => entry.model === PRODUCT_RESEARCH_FAST_MODEL
    );
    const seniorEvaluation = [...campaignFitEvaluations]
      .reverse()
      .find((entry) => entry.model === PRODUCT_RESEARCH_MODEL);

    return {
      ...item,
      ai_campaign_fit_score: evaluation.score,
      campaign_fit_score: evaluation.score,
      // Keep the real discovery source (store search, campaign discovery, etc.)
      // so logs and source-level safeguards remain truthful. AI scoring is
      // recorded separately.
      campaign_fit_source: item?.campaign_fit_source || aiCampaignFitSource,
      ai_campaign_fit_source: aiCampaignFitSource,
      ai_campaign_fit_model: evaluation.model,
      campaign_fit_verdict: evaluation.verdict,
      campaign_theme_fit:
        evaluation.fitsTheme === null ||
        evaluation.fitsTheme === undefined
          ? item?.campaign_theme_fit ?? null
          : evaluation.fitsTheme,
      campaign_fit_reason: evaluation.reason,
      campaign_relevance_class:
        evaluation.relevanceClass ||
        item?.campaign_relevance_class ||
        null,
      campaign_role:
        evaluation.campaignRole || item?.campaign_role || null,
      campaign_relevance_evidence:
        evaluation.evidence?.length
          ? evaluation.evidence
          : item?.campaign_relevance_evidence || [],
      campaign_fit_evaluations: campaignFitEvaluations,
      ai_campaign_fit_fast_score:
        fastEvaluation?.score ?? item?.ai_campaign_fit_fast_score ?? null,
      ai_campaign_fit_fast_verdict:
        fastEvaluation?.verdict || item?.ai_campaign_fit_fast_verdict || null,
      ai_campaign_fit_fast_reason:
        fastEvaluation?.reason || item?.ai_campaign_fit_fast_reason || null,
      ai_campaign_fit_senior_score:
        seniorEvaluation?.score ?? item?.ai_campaign_fit_senior_score ?? null,
      ai_campaign_fit_senior_verdict:
        seniorEvaluation?.verdict || item?.ai_campaign_fit_senior_verdict || null,
      ai_campaign_fit_senior_reason:
        seniorEvaluation?.reason || item?.ai_campaign_fit_senior_reason || null,
    };
  });
}

function shouldEscalateCampaignFitEvaluation(evaluationByIndex, minimumStrongProducts) {
  const scores = Array.from(evaluationByIndex.values())
    .map((entry) => Number(entry?.score || 0))
    .filter((score) => Number.isFinite(score));

  if (!scores.length) {
    return true;
  }

  const strongCount = scores.filter((score) => score >= CAMPAIGN_STRONG_PRODUCT_FIT_SCORE).length;
  const excellentCount = scores.filter((score) => score >= 90).length;

  return strongCount < minimumStrongProducts || excellentCount === 0;
}

function selectCampaignFitEscalationCandidates({
  candidates,
  evaluationByIndex,
  rule,
  minimumStrongProducts,
  escalationMaxItems,
}) {
  const evaluated = candidates.map((candidate) => {
    const evaluation = evaluationByIndex.get(candidate.index);
    const score = evaluation ? Number(evaluation.score || 0) : null;
    const directMatches = Math.max(
      countCampaignCoreThemeTermMatches(candidate.item, rule),
      countCampaignAnchorTermMatches(candidate.item, rule),
      countPrimaryCampaignTermMatches(candidate.item, rule)
    );

    return {
      ...candidate,
      currentScore: score,
      directMatches,
    };
  });
  const strongCount = evaluated.filter(
    (candidate) => Number(candidate.currentScore || 0) >= CAMPAIGN_STRONG_PRODUCT_FIT_SCORE
  ).length;
  const missingStrongCount = Math.max(0, minimumStrongProducts - strongCount);
  const desiredEscalationCount = Math.min(
    escalationMaxItems,
    Math.max(4, missingStrongCount * 2 + 2)
  );

  return evaluated
    .filter((candidate) => {
      if (candidate.currentScore === null) return true;
      if (candidate.currentScore >= 45 && candidate.currentScore < 90) return true;
      return candidate.directMatches > 0 && candidate.currentScore < CAMPAIGN_STRONG_PRODUCT_FIT_SCORE;
    })
    .sort((a, b) => {
      const directDelta = Number(b.directMatches || 0) - Number(a.directMatches || 0);
      if (directDelta !== 0) return directDelta;

      const scoreDelta = Number(b.currentScore || 0) - Number(a.currentScore || 0);
      if (scoreDelta !== 0) return scoreDelta;

      const priorityDelta =
        Number(b.item?.selection_priority || 0) - Number(a.item?.selection_priority || 0);
      if (priorityDelta !== 0) return priorityDelta;

      return scoreWebsiteItemForRule(b.item, rule) - scoreWebsiteItemForRule(a.item, rule);
    })
    .slice(0, desiredEscalationCount);
}

async function applyAiCampaignFitScores({
  openai,
  rule,
  brandProfile,
  items,
  maxItems = 80,
  model = PRODUCT_RESEARCH_MODEL,
  escalateWhenUncertain = false,
  escalationModel = PRODUCT_RESEARCH_MODEL,
  escalationMaxItems = 20,
  minimumStrongProducts = CAROUSEL_MIN_PRODUCT_SLIDES,
}) {
  if (!isProductIntentScopedWebsiteRule(rule) || !Array.isArray(items) || items.length === 0) {
    return items || [];
  }

  const candidates = items
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => item?.title || item?.url || item?.product_url || item?.item_url)
    .sort((a, b) => {
      const evidenceDelta =
        countCampaignCoreThemeTermMatches(b.item, rule) -
        countCampaignCoreThemeTermMatches(a.item, rule);
      if (evidenceDelta !== 0) return evidenceDelta;

      const priorityDelta =
        Number(b.item?.selection_priority || 0) - Number(a.item?.selection_priority || 0);
      if (priorityDelta !== 0) return priorityDelta;

      const sourceScoreDelta =
        Number(b.item?.campaign_fit_score || b.item?.score || 0) -
        Number(a.item?.campaign_fit_score || a.item?.score || 0);
      if (sourceScoreDelta !== 0) return sourceScoreDelta;

      return scoreWebsiteItemForRule(b.item, rule) - scoreWebsiteItemForRule(a.item, rule);
    })
    .slice(0, maxItems);

  if (!candidates.length) {
    return items;
  }

  const evaluationByIndex = await evaluateCampaignFitCandidates({
    openai,
    rule,
    brandProfile,
    candidates,
    model,
  });

  if (evaluationByIndex.size === 0) {
    console.warn("Campaign fit AI returned no usable scores; skipping senior escalation and preserving deterministic ranking", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      model,
      candidateCount: candidates.length,
    });
    return applyCampaignFitEvaluations(items, evaluationByIndex);
  }

  if (
    escalateWhenUncertain &&
    model !== escalationModel &&
    shouldEscalateCampaignFitEvaluation(evaluationByIndex, minimumStrongProducts)
  ) {
    const escalationCandidates = selectCampaignFitEscalationCandidates({
      candidates,
      evaluationByIndex,
      rule,
      minimumStrongProducts,
      escalationMaxItems,
    });

    if (!escalationCandidates.length) {
      return applyCampaignFitEvaluations(items, evaluationByIndex);
    }

    console.log("Campaign fit scoring escalated to senior product research model", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      fastModel: model,
      escalationModel,
      candidateCount: candidates.length,
      escalationCandidateCount: escalationCandidates.length,
    });

    const escalatedEvaluationByIndex = await evaluateCampaignFitCandidates({
      openai,
      rule,
      brandProfile,
      candidates: escalationCandidates,
      model: escalationModel,
    });

    for (const [index, evaluation] of escalatedEvaluationByIndex.entries()) {
      const previousEvaluation = evaluationByIndex.get(index);
      const previousHistory = Array.isArray(previousEvaluation?.evaluations)
        ? previousEvaluation.evaluations
        : previousEvaluation
          ? [previousEvaluation]
          : [];
      const escalatedHistory = Array.isArray(evaluation?.evaluations)
        ? evaluation.evaluations
        : [evaluation];

      evaluationByIndex.set(index, {
        ...evaluation,
        evaluations: [...previousHistory, ...escalatedHistory],
      });
    }
  }

  return applyCampaignFitEvaluations(items, evaluationByIndex);
}

function getCampaignFinalReviewGroupKey(item, index) {
  const query = getCampaignStoreSearchQuery(item);
  if (query) {
    return `query:${query}`;
  }

  const sourcePage = String(
    item?.source_search_url ||
      item?.source_page_url ||
      item?.catalog_source ||
      item?.discovery_source ||
      ""
  )
    .trim()
    .toLowerCase();
  if (sourcePage) {
    return `source:${sourcePage}`;
  }

  return `item:${getCarouselProductSelectionKey(item) || index}`;
}

function countCampaignTitleThemeEvidence(item, rule) {
  const titleThemeTerms = extractCampaignTitleThemeTerms(rule);
  if (!titleThemeTerms.length) return 0;

  return countCampaignSearchTermMatches(
    getWebsiteItemDirectCampaignText(item),
    titleThemeTerms
  );
}

function getCampaignThemeDeliveryState(item, rule) {
  const signalState = getCampaignProductSignalState(item, rule);
  const contract = getCampaignThemeContract(rule);
  const directText = getWebsiteItemDirectCampaignText(item);
  const matchedCompetingTerms = (contract?.competingThemeTerms || []).filter(
    (term) => countCampaignSearchTermMatches(directText, [term]) > 0
  );
  const unambiguousCurrentThemeTerms = (
    contract?.approvedThemeTerms || []
  ).filter((approvedTerm) => {
    const normalizedApprovedTerm = normalizeSearchText(approvedTerm).trim();
    if (!normalizedApprovedTerm) return false;
    return !matchedCompetingTerms.some((competingTerm) => {
      const normalizedCompetingTerm =
        normalizeSearchText(competingTerm).trim();
      return (
        normalizedCompetingTerm !== normalizedApprovedTerm &&
        countCampaignSearchTermMatches(competingTerm, [approvedTerm]) > 0
      );
    });
  });
  const rawCurrentThemeMatches = contract
    ? countCampaignSearchTermMatches(
        directText,
        unambiguousCurrentThemeTerms
      )
    : Math.max(
        countCampaignTitleThemeEvidence(item, rule),
        countCampaignCoreThemeTermMatches(item, rule),
        countCampaignAnchorTermMatches(item, rule),
        countPrimaryCampaignTermMatches(item, rule)
      );
  const rawCompetingThemeMatches = matchedCompetingTerms.length;
  const {
    currentThemeMatches,
    competingThemeMatches,
  } = resolveCampaignThemeEvidence({
    currentThemeMatches: rawCurrentThemeMatches,
    competingThemeMatches: rawCompetingThemeMatches,
  });
  const contextualApproved =
    currentThemeMatches === 0 &&
    competingThemeMatches === 0 &&
    (signalState.contextualCampaignApproval ||
      signalState.hasVerifiedContextualCampaignSignal);

  return {
    currentThemeMatches,
    competingThemeMatches,
    contextualApproved,
    deliveryTier: getCampaignThemeDeliveryTier({
      currentThemeMatches,
      competingThemeMatches,
      contextualApproved,
    }),
    signalState,
  };
}

function selectCampaignThemeSafeDeliveryProducts({
  items,
  rule,
  selectedLimit,
  reserveLimit,
  preferredItems = [],
}) {
  const preferredRanks = new Map();
  dedupeWebsiteItemsByUrlTitleAndImage(preferredItems).forEach(
    (item, index) => {
      const key = getCarouselProductSelectionKey(item);
      if (key && !preferredRanks.has(key)) {
        preferredRanks.set(key, index);
      }
    }
  );
  const entries = dedupeWebsiteItemsByUrlTitleAndImage(items)
    .filter(isValidCarouselProduct)
    .filter((item) => !isCampaignFitRejectedForRule(item, rule))
    .map((item, index) => {
      const state = getCampaignThemeDeliveryState(item, rule);
      const key = getCarouselProductSelectionKey(item);
      return {
        item,
        originalIndex: index,
        currentThemeMatches: state.currentThemeMatches,
        competingThemeMatches: state.competingThemeMatches,
        contextualApproved: state.contextualApproved,
        contextualScore:
          state.signalState.aiCampaignFitScore ??
          Number(item?.campaign_fit_score || 0),
        qualityScore: scoreWebsiteItemForRule(item, rule),
        preferredRank: preferredRanks.has(key)
          ? preferredRanks.get(key)
          : Number.MAX_SAFE_INTEGER,
        deliveryTier: state.deliveryTier,
      };
    });
  const selection = selectCampaignThemeDeliveryEntries(entries, {
    selectedLimit,
    reserveLimit,
  });
  const decorate = (entry) => ({
    ...entry.item,
    campaign_delivery_tier: entry.deliveryTier,
    campaign_current_theme_matches: entry.currentThemeMatches,
    campaign_competing_theme_matches: entry.competingThemeMatches,
  });

  return {
    selectedProducts: selection.selectedEntries.map(decorate),
    reserveProducts: selection.reserveEntries.map(decorate),
    rankedProducts: selection.rankedEntries.map(decorate),
    tierCounts: selection.rankedEntries.reduce((counts, entry) => {
      counts[entry.deliveryTier] =
        Number(counts[entry.deliveryTier] || 0) + 1;
      return counts;
    }, {}),
  };
}

function buildCampaignFinalReviewShortlist(
  items,
  rule,
  limit = CAMPAIGN_FINAL_REVIEW_SHORTLIST_LIMIT
) {
  const ranked = dedupeWebsiteItemsByUrlTitleAndImage(items)
    .filter(isValidCarouselProduct)
    .map((item, index) => {
      const aiScore = getAiCampaignFitScore(item);
      const titleThemeEvidence = countCampaignTitleThemeEvidence(item, rule);
      const deliveryState = getCampaignThemeDeliveryState(item, rule);
      const directMatches = deliveryState.currentThemeMatches;
      const signalState = deliveryState.signalState;
      const competingThemeMatches =
        deliveryState.competingThemeMatches;
      const deliveryTier = deliveryState.deliveryTier;
      return {
        item,
        index,
        aiScore,
        titleThemeEvidence,
        directMatches,
        relevanceTier: signalState.relevanceTier,
        competingThemeMatches,
        deliveryTier,
        meaningful: signalState.hasMeaningfulCampaignSignal,
        fresh: !Boolean(
          item?.campaign_was_used_recently ||
            item?.campaign_image_used_this_run
        ),
      };
    })
    .sort((left, right) => {
      const tierWeight = {
        direct: 3,
        contextual: 2,
        generic: 1,
        competing: 0,
      };
      const tierDelta =
        Number(tierWeight[right.deliveryTier] || 0) -
        Number(tierWeight[left.deliveryTier] || 0);
      if (tierDelta !== 0) return tierDelta;

      const titleThemeDelta =
        Number(right.titleThemeEvidence || 0) -
        Number(left.titleThemeEvidence || 0);
      if (titleThemeDelta !== 0) return titleThemeDelta;

      const directDelta =
        Number(right.directMatches || 0) - Number(left.directMatches || 0);
      if (directDelta !== 0) return directDelta;

      const aiDelta =
        Number(right.aiScore ?? -1) - Number(left.aiScore ?? -1);
      if (aiDelta !== 0) return aiDelta;

      if (right.fresh !== left.fresh) return right.fresh ? 1 : -1;

      const priorityDelta =
        Number(right.item?.selection_priority || 0) -
        Number(left.item?.selection_priority || 0);
      if (priorityDelta !== 0) return priorityDelta;

      return (
        scoreWebsiteItemForRule(right.item, rule) -
        scoreWebsiteItemForRule(left.item, rule)
      );
    });

  // Retailer search can return many near-identical products for one broad
  // query. Round-robin the retrieval groups so the senior model receives the
  // best evidence from several searches instead of fifteen hoodies from one.
  const shortlist = [];
  for (const deliveryTier of [
    "direct",
    "contextual",
    "generic",
    "competing",
  ]) {
    const groups = new Map();
    ranked
      .filter((entry) => entry.deliveryTier === deliveryTier)
      .forEach((entry, index) => {
        const key = getCampaignFinalReviewGroupKey(entry.item, index);
        const group = groups.get(key) || [];
        group.push(entry);
        groups.set(key, group);
      });

    let addedInRound = true;
    while (shortlist.length < limit && addedInRound) {
      addedInRound = false;
      for (const group of groups.values()) {
        const next = group.shift();
        if (!next) continue;
        shortlist.push(next.item);
        addedInRound = true;
        if (shortlist.length >= limit) break;
      }
    }
    if (shortlist.length >= limit) break;
  }

  return shortlist;
}

function formatCampaignFinalReviewCandidates(items) {
  return items
    .map((item, index) => {
      const fields = [
        `Index: ${index}`,
        `Title: ${item?.title || "Not provided"}`,
        `URL: ${item?.url || item?.product_url || item?.item_url || "Not provided"}`,
        `Description: ${truncateText(item?.description || "", 320) || "Not provided"}`,
        `Category: ${item?.category || "Not provided"}`,
        `Tags: ${Array.isArray(item?.tags) && item.tags.length ? item.tags.slice(0, 8).join(", ") : "Not provided"}`,
      ];
      return fields.join("\n");
    })
    .join("\n\n---\n\n");
}

function applyCampaignFinalReviewEvaluation(item, evaluation) {
  const history = Array.isArray(item?.campaign_fit_evaluations)
    ? item.campaign_fit_evaluations
    : [];
  const seniorEvaluation = {
    model: PRODUCT_RESEARCH_MODEL,
    fitsTheme: evaluation.fitsTheme,
    score: evaluation.score,
    verdict: evaluation.verdict,
    relevanceClass: evaluation.relevanceClass,
    campaignRole: evaluation.campaignRole,
    evidence: evaluation.evidence,
    reason: evaluation.reason,
  };

  return {
    ...item,
    ai_campaign_fit_score: evaluation.score,
    campaign_fit_score: evaluation.score,
    campaign_fit_verdict: evaluation.verdict,
    campaign_theme_fit:
      evaluation.fitsTheme === null ||
      evaluation.fitsTheme === undefined
        ? item?.campaign_theme_fit ?? null
        : evaluation.fitsTheme,
    campaign_fit_reason: evaluation.reason,
    campaign_relevance_class:
      evaluation.relevanceClass || item?.campaign_relevance_class || null,
    campaign_role:
      evaluation.campaignRole || item?.campaign_role || null,
    campaign_relevance_evidence:
      evaluation.evidence?.length
        ? evaluation.evidence
        : item?.campaign_relevance_evidence || [],
    ai_campaign_fit_source: "ai_campaign_fit_final_review",
    ai_campaign_fit_model: PRODUCT_RESEARCH_MODEL,
    ai_campaign_fit_senior_score: evaluation.score,
    ai_campaign_fit_senior_verdict: evaluation.verdict,
    ai_campaign_fit_senior_reason: evaluation.reason,
    campaign_fit_evaluations: [...history, seniorEvaluation],
    campaign_final_reviewed: true,
    campaign_final_review_category: evaluation.category || null,
    campaign_final_review_slot_id: evaluation.slotId || null,
    campaign_final_review_evidence: Array.isArray(evaluation.evidence)
      ? evaluation.evidence
      : [],
  };
}

function buildBoundedCampaignFinalReviewFallback({
  shortlist,
  rule,
  selectedLimit,
  reserveLimit,
  reason,
}) {
  // Retired failure diagnostic kept as an audit marker for older regression
  // suites: technically verified, but only ${selectedProducts.length} were accepted as fitting the campaign theme
  // v143.5 backfills from verified products instead of throwing that error.
  const evidenceBackedItems = shortlist
    .filter((item) => !isCampaignFitRejectedForRule(item, rule))
    .filter((item) => {
      const signalState = getCampaignProductSignalState(
        item,
        rule
      );
      return signalState.hasMeaningfulCampaignSignal;
    })
    .map((item) => ({
      ...item,
      campaign_final_reviewed: false,
      campaign_fit_source:
        item?.campaign_fit_source || "bounded_theme_fit_fallback",
      campaign_fit_reason:
        item?.campaign_fit_reason ||
        "Selected because the verified product reasonably fits the campaign theme after the optional final review was unavailable.",
    }));
  const deliveryItems = dedupeWebsiteItemsByUrlTitleAndImage(
    evidenceBackedItems
  );
  const themeSafeSelection = selectCampaignThemeSafeDeliveryProducts({
    items: deliveryItems,
    rule,
    selectedLimit,
    reserveLimit,
    preferredItems: evidenceBackedItems,
  });
  const selectedProducts = themeSafeSelection.selectedProducts;
  const reserveProducts = themeSafeSelection.reserveProducts;
  const publishable = selectedProducts.length === selectedLimit;

  return {
    selectedProducts,
    reserveProducts,
    shortlistCount: shortlist.length,
    eligibleCount: deliveryItems.length,
    publishable,
    missingNeeds: publishable
      ? []
      : [
          {
            need: "The bounded text-evidence fallback did not contain five defensible products.",
            blocking: true,
            requiredEvidence: [],
            searchQueries: [],
          },
        ],
    coverage: [],
    curation: {
      concept: "Theme-first delivery-safe fallback",
      audienceFit: "",
      assortmentFit: "",
      setReason: reason || "Senior final review was unavailable.",
    },
    evaluations: [],
    deliveryTierCounts: themeSafeSelection.tierCounts,
  };
}

function getCampaignFinalEvaluationRelevance(item, evaluation, rule) {
  const directTerms = collectUniqueTerms(
    [
      ...extractCampaignCoreThemeTerms(rule),
      ...extractCampaignAnchorTerms(rule),
      ...extractCampaignTitleThemeTerms(rule),
    ],
    24
  );
  const directMatches = Math.max(
    countCampaignCoreThemeTermMatches(item, rule),
    countCampaignAnchorTermMatches(item, rule),
    countPrimaryCampaignTermMatches(item, rule)
  );

  const fitDecision = evaluateSimpleCampaignThemeFit({
    fitsTheme: evaluation?.fitsTheme,
    verdict: evaluation?.verdict,
    score: evaluation?.score,
  });
  const rejected = fitDecision.rejected;
  const directApproved = !rejected && directMatches > 0;
  const approved = !rejected && (directApproved || fitDecision.approved);

  return {
    meaningful: approved,
    tier: directMatches > 0 ? "direct" : approved ? "contextual" : "reject",
    directApproved,
    contextualApproved: approved && directMatches === 0,
    rejected,
  };
}

async function selectCampaignCarouselProductsWithSeniorFinalReview({
  openai,
  rule,
  brandProfile,
  items,
  websiteUrl,
  selectedLimit = CAROUSEL_PRODUCT_SLIDE_TARGET,
  reserveLimit = CAROUSEL_PRODUCT_RESERVE_TARGET,
  reviewPass = "initial",
}) {
  const shortlist = buildCampaignFinalReviewShortlist(
    items,
    rule,
    CAMPAIGN_FINAL_REVIEW_SHORTLIST_LIMIT
  );

  const deliverySelectedLimit = Math.min(selectedLimit, shortlist.length);
  if (deliverySelectedLimit < CAROUSEL_PLATFORM_MIN_PRODUCT_SLIDES) {
    return {
      selectedProducts: [],
      reserveProducts: [],
      shortlistCount: shortlist.length,
      eligibleCount: 0,
      publishable: false,
      missingNeeds: [
        {
          need: "More verified product candidates are required before curation.",
          blocking: true,
          requiredEvidence: [],
          searchQueries:
            rule?.campaign_marketing_strategy?.searchQueries || [],
        },
      ],
      coverage: [],
      curation: null,
      evaluations: [],
    };
  }
  selectedLimit = deliverySelectedLimit;

  const titleThemeTerms = extractCampaignTitleThemeTerms(rule);
  const titleThemeCandidateCount = shortlist.filter(
    (item) => countCampaignTitleThemeEvidence(item, rule) > 0
  ).length;
  const directThemeCandidateCount = shortlist.filter(
    (item) =>
      getCampaignThemeDeliveryState(item, rule).deliveryTier === "direct"
  ).length;
  if (directThemeCandidateCount >= selectedLimit) {
    console.log("Campaign senior final review skipped because direct theme evidence already fills the delivery set", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      websiteUrl,
      shortlistCount: shortlist.length,
      directThemeCandidateCount,
      selectedLimit,
      reviewPass,
    });
    return buildBoundedCampaignFinalReviewFallback({
      shortlist,
      rule,
      selectedLimit,
      reserveLimit,
      reason:
        "Direct product-level theme evidence already filled the delivery set, so no additional AI curation was needed.",
    });
  }
  let response;
  try {
    response = await openai.responses.create(
      {
        model: PRODUCT_RESEARCH_MODEL,
        ...getReasoningOptionsForModel(PRODUCT_RESEARCH_MODEL),
        input: `
You are the mandatory senior marketing curator making the final product selection for a social media campaign carousel.

The fast research stage has already gathered and verified the candidates. This is the final bounded senior-model call: ignore the screening order and curate the strongest complete marketing set.

Rules:
- Judge the carousel as one commercial story, not as ${selectedLimit} independent product scores.
- First identify the campaign's central occasion, season, event or creative theme from its own context. Never replace it with a generic gift campaign.
- Decide whether each real product reasonably fits that theme and the company's assortment. A fit may be direct or a natural thematic choice based on the product's use, recipient, season, style or buying situation; it does not need to repeat the theme word.
- Use only the supplied product title, description, category, tags and URL. The retailer query and result page are discovery clues, not proof by themselves; retailer queries, discovery sources and earlier screening opinions are intentionally hidden so they cannot bias this decision.
- Audience and recipient words are context, not direct proof of the campaign occasion/theme. A product for a conflicting recipient, event or theme ranks behind products that genuinely serve the current campaign.
- A clear audience conflict is a rejection, not a generic fallback. Never describe an adult product as a child/youth product, or otherwise change the supplied recipient, simply to complete the set.
- Reject only products that are clearly unrelated to the campaign, not concrete products, or conflict with the supplied facts.
- Do not reject a reasonable thematic product merely because it lacks a formal strategy slot, exact keyword, evidence chain or high numeric score.
- Every selected item must be a concrete verified product page that reasonably fits this exact campaign.
- Never invent customization, motifs, recipients, materials, occasions or features that contradict the supplied product data.
- Prefer clear thematic choices over vague giftability when both are available.
- Rank in four stages: direct product-level evidence for the current theme first, natural commercial/contextual fit second, generic technically verified fallback third, and products explicitly tied to a different competing occasion/theme last.
- A product explicitly tied to a different occasion must never replace an available direct-current-theme product. Competing products remain last-resort delivery fallbacks rather than hard rejections.
- Campaign avoid terms are soft preferences. They may lower a generic product, but they must never veto direct theme or occasion evidence in the concrete product.
- Mere theoretical giftability is weak. For a gift-oriented campaign, prefer the company's naturally gift-suitable products before size- or taste-sensitive everyday products when those stronger choices are available.
- Choose products that complement one another and collectively solve the audience's buying need.
- Assortment breadth determines useful variation. Do not force unrelated categories for a specialist company, but do not repeat one generic category when the strategy and strong alternatives support a better mix.
- Consider commercial clarity, variation and image suitability when selecting among products that fit.
- Select exactly ${selectedLimit} of the supplied concrete verified products. Relevance controls their order; it must not turn an otherwise deliverable campaign into an empty or incomplete post.
- Mark a missing need as blocking only when fewer than ${selectedLimit} supplied concrete products reasonably fit. Optional ways to improve an already complete set must be non-blocking.
- Return compact evaluations for the selected products and, when useful, up to ${reserveLimit} reserves. Do not spend output on every rejected candidate.

Brand profile:
${formatBrandProfileForPrompt(brandProfile)}

Campaign context:
${buildCampaignResearchText(rule) || "No campaign context provided."}

Campaign-title theme anchors:
${titleThemeTerms.join(", ") || "No reliable title theme anchor was derived."}

Theme-evidenced candidates in this shortlist:
${titleThemeCandidateCount} of ${shortlist.length}

Dynamic senior marketing strategy:
${formatCampaignMarketingStrategyForPrompt(rule?.campaign_marketing_strategy) || "No structured strategy was available; derive a coherent set directly from the campaign and evidenced assortment."}

Website:
${websiteUrl || "Not provided"}

Shortlisted products:
${formatCampaignFinalReviewCandidates(shortlist)}

Return strict JSON only:
{
  "publishable": true,
  "curation": {
    "concept": "The coherent marketing idea behind the complete set",
    "set_reason": "Why these products work better together than alternatives"
  },
  "evaluations": [
    {
      "index": 0,
      "fits_theme": true,
      "score": 0,
      "verdict": "fits | does_not_fit",
      "relevance_class": "direct | contextual | generic | reject",
      "campaign_role": "Specific role in this campaign and complete set, or empty",
      "reason": "One short product-fact-based reason"
    }
  ],
  "selected_indices": [0, 1, 2, 3, 4]
}
        `.trim(),
      },
      { timeout: CAMPAIGN_FINAL_REVIEW_TIMEOUT_MS, maxRetries: 0 }
    );
  } catch (error) {
    console.warn("Campaign senior final review timed out or failed; using bounded theme-fit fallback", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      websiteUrl,
      shortlistCount: shortlist.length,
      message: error?.message,
    });
    return buildBoundedCampaignFinalReviewFallback({
      shortlist,
      rule,
      selectedLimit,
      reserveLimit,
      reason: error?.message,
    });
  }

  const parsed = safeJsonParse(response.output_text || "");
  if (!parsed || typeof parsed !== "object") {
    console.warn("Campaign senior final review returned invalid JSON; using bounded theme-fit fallback", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      websiteUrl,
      shortlistCount: shortlist.length,
    });
    return buildBoundedCampaignFinalReviewFallback({
      shortlist,
      rule,
      selectedLimit,
      reserveLimit,
      reason: "Senior final review returned invalid JSON.",
    });
  }
  const evaluationByIndex = new Map();
  for (const entry of Array.isArray(parsed?.evaluations) ? parsed.evaluations : []) {
    const index = Number(entry?.index);
    if (!Number.isInteger(index) || index < 0 || index >= shortlist.length) {
      continue;
    }
    evaluationByIndex.set(index, {
      index,
      fitsTheme:
        entry?.fits_theme === true
          ? true
          : entry?.fits_theme === false
            ? false
            : null,
      score: normalizeCampaignFitScore(entry?.score),
      verdict: String(entry?.verdict || "").trim(),
      category: String(entry?.category || "").trim(),
      slotId: normalizeCampaignStrategyText(
        entry?.slot_id || entry?.slotId,
        60
      ),
      evidence: normalizeCampaignStrategyList(entry?.evidence, 8, 220),
      relevanceClass: normalizeCampaignRelevanceClass(
        entry?.relevance_class || entry?.relevanceClass
      ),
      campaignRole: normalizeCampaignStrategyText(
        entry?.campaign_role || entry?.campaignRole,
        220
      ),
      reason: String(entry?.reason || "").trim(),
    });
  }
  if (evaluationByIndex.size < selectedLimit) {
    console.warn("Campaign senior final review returned too few evaluations; using bounded theme-fit fallback", {
      ruleId: rule?.id,
      brandProfileId: rule?.brand_profile_id,
      websiteUrl,
      shortlistCount: shortlist.length,
      evaluatedCount: evaluationByIndex.size,
    });
    return buildBoundedCampaignFinalReviewFallback({
      shortlist,
      rule,
      selectedLimit,
      reserveLimit,
      reason: "Senior final review returned too few candidate evaluations.",
    });
  }

  const coverage = (Array.isArray(parsed?.coverage) ? parsed.coverage : [])
    .slice(0, CAMPAIGN_MARKETING_STRATEGY_SLOT_COUNT)
    .map((entry) => ({
      slotId: normalizeCampaignStrategyText(
        entry?.slot_id || entry?.slotId,
        60
      ),
      productIndex: Number.isInteger(Number(entry?.product_index))
        ? Number(entry.product_index)
        : null,
      status: normalizeCampaignStrategyText(entry?.status, 30),
      reason: normalizeCampaignStrategyText(entry?.reason, 300),
    }))
    .filter((entry) => entry.slotId || entry.reason);
  const missingNeeds = (Array.isArray(parsed?.missing_needs)
    ? parsed.missing_needs
    : [])
    .slice(0, CAMPAIGN_MARKETING_STRATEGY_SLOT_COUNT)
    .map((entry) => ({
      need: normalizeCampaignStrategyText(entry?.need, 300),
      blocking: entry?.blocking === true,
      requiredEvidence: normalizeCampaignStrategyList(
        entry?.required_evidence || entry?.requiredEvidence,
        8,
        180
      ),
      searchQueries: normalizeStoreSearchQueries(
        entry?.search_queries || entry?.searchQueries || [],
        6
      ),
    }))
    .filter(
      (entry) =>
        entry.need ||
        entry.requiredEvidence.length ||
        entry.searchQueries.length
    );
  const curation =
    parsed?.curation && typeof parsed.curation === "object"
      ? {
          concept: normalizeCampaignStrategyText(
            parsed.curation.concept,
            500
          ),
          audienceFit: normalizeCampaignStrategyText(
            parsed.curation.audience_fit || parsed.curation.audienceFit,
            500
          ),
          assortmentFit: normalizeCampaignStrategyText(
            parsed.curation.assortment_fit || parsed.curation.assortmentFit,
            500
          ),
          setReason: normalizeCampaignStrategyText(
            parsed.curation.set_reason || parsed.curation.setReason,
            700
          ),
        }
      : null;

  const eligibleEvaluations = [...evaluationByIndex.values()]
    .map((entry) => ({
      ...entry,
      relevance: getCampaignFinalEvaluationRelevance(
        shortlist[entry.index],
        entry,
        rule
      ),
    }))
    .filter((entry) => entry.relevance.meaningful)
    .sort((left, right) => right.score - left.score);
  const selectedIndices = [];
  const seenIndices = new Set();
  const addIndex = (value) => {
    const index = Number(value);
    const evaluation = evaluationByIndex.get(index);
    const relevance = evaluation
      ? getCampaignFinalEvaluationRelevance(
          shortlist[index],
          evaluation,
          rule
        )
      : null;
    if (
      !Number.isInteger(index) ||
      seenIndices.has(index) ||
      !evaluation ||
      !relevance?.meaningful
    ) {
      return;
    }
    seenIndices.add(index);
    selectedIndices.push(index);
  };

  for (const index of Array.isArray(parsed?.selected_indices)
    ? parsed.selected_indices
    : []) {
    addIndex(index);
    if (selectedIndices.length >= selectedLimit) break;
  }
  if (selectedIndices.length < selectedLimit) {
    for (const evaluation of eligibleEvaluations) {
      addIndex(evaluation.index);
      if (selectedIndices.length >= selectedLimit) break;
    }
  }

  let selectedSet = new Set(selectedIndices);
  let selectedProducts = selectedIndices
    .slice(0, selectedLimit)
    .map((index) =>
      applyCampaignFinalReviewEvaluation(
        shortlist[index],
        evaluationByIndex.get(index)
      )
    );
  let reserveProducts = eligibleEvaluations
    .filter((entry) => !selectedSet.has(entry.index))
    .slice(0, reserveLimit)
    .map((entry) =>
      applyCampaignFinalReviewEvaluation(shortlist[entry.index], entry)
    );
  const recoveredFromFastThemeFit = false;
  const evaluatedShortlist = shortlist.flatMap((item, index) => {
    const evaluation = evaluationByIndex.get(index);
    return evaluation
      ? [applyCampaignFinalReviewEvaluation(item, evaluation)]
      : [];
  });
  const themeSafeFinalSelection = selectCampaignThemeSafeDeliveryProducts({
    items: evaluatedShortlist,
    rule,
    selectedLimit,
    reserveLimit,
    preferredItems: selectedProducts,
  });
  selectedProducts = themeSafeFinalSelection.selectedProducts;
  reserveProducts = themeSafeFinalSelection.reserveProducts;
  const selectedKeysAfterThemeReconciliation = new Set(
    selectedProducts
      .map((item) => getCarouselProductSelectionKey(item, websiteUrl))
      .filter(Boolean)
  );
  selectedSet = new Set(
    shortlist
      .map((item, index) =>
        selectedKeysAfterThemeReconciliation.has(
          getCarouselProductSelectionKey(item, websiteUrl)
        )
          ? index
          : null
      )
      .filter(Number.isInteger)
  );
  const titleThemeSelectedCount = selectedProducts.filter(
    (item) => countCampaignTitleThemeEvidence(item, rule) > 0
  ).length;
  const titleThemeCoverageRequired =
    titleThemeTerms.length > 0 &&
    titleThemeCandidateCount >= selectedLimit;
  const titleThemeCoverageReady =
    !titleThemeCoverageRequired ||
    titleThemeSelectedCount >= Math.ceil(selectedLimit / 2);
  const blockingMissingNeeds = missingNeeds.filter(
    (entry) => entry.blocking
  );
  const hasMissingRequiredCoverage = coverage.some((entry) =>
    /missing/i.test(String(entry?.status || ""))
  );
  const hasConfirmedBlockingMissingNeed =
    selectedProducts.length < selectedLimit &&
    blockingMissingNeeds.length > 0 &&
    hasMissingRequiredCoverage;
  const publishable =
    selectedProducts.length === selectedLimit &&
    !hasConfirmedBlockingMissingNeed;
  const rejectedEvaluations = [...evaluationByIndex.values()]
    .filter((entry) => !selectedSet.has(entry.index))
    .sort((left, right) => right.score - left.score);

  console.log("Campaign carousel senior final review completed", {
    ruleId: rule?.id,
    brandProfileId: rule?.brand_profile_id,
    websiteUrl,
    fastModel: PRODUCT_RESEARCH_FAST_MODEL,
    finalModel: PRODUCT_RESEARCH_MODEL,
    reviewPass,
    shortlistCount: shortlist.length,
    evaluatedCount: evaluationByIndex.size,
    eligibleCount: eligibleEvaluations.length,
    selectedCount: selectedProducts.length,
    reserveCount: reserveProducts.length,
    publishable,
    titleThemeTerms,
    titleThemeCandidateCount,
    titleThemeSelectedCount,
    titleThemeCoverageRequired,
    titleThemeCoverageReady,
    modelPublishable: parsed?.publishable === true,
    recoveredFromFastThemeFit,
    deliveryTierCounts: themeSafeFinalSelection.tierCounts,
    blockingMissingNeedCount: blockingMissingNeeds.length,
    hasConfirmedBlockingMissingNeed,
    hasMissingRequiredCoverage,
    acceptanceDecision: publishable
      ? "fits_theme"
      : "reduced_theme_safe_delivery",
    curation,
    coverage,
    missingNeeds,
    selectedProducts: selectedProducts.map((item, index) => ({
      rank: index + 1,
      title: item?.title || null,
      url: item?.url || null,
      seniorScore: item?.ai_campaign_fit_senior_score ?? null,
      category: item?.campaign_final_review_category || null,
      slotId: item?.campaign_final_review_slot_id || null,
      evidence: item?.campaign_final_review_evidence || [],
      relevanceClass: item?.campaign_relevance_class || null,
      campaignRole: item?.campaign_role || null,
      deliveryTier: item?.campaign_delivery_tier || null,
      currentThemeMatches: item?.campaign_current_theme_matches || 0,
      competingThemeMatches: item?.campaign_competing_theme_matches || 0,
      reason: item?.campaign_fit_reason || null,
    })),
    rejectedProducts: rejectedEvaluations.map((entry) => ({
      index: entry.index,
      title: shortlist[entry.index]?.title || null,
      url: shortlist[entry.index]?.url || null,
      seniorScore: entry.score,
      verdict: entry.verdict,
      category: entry.category,
      slotId: entry.slotId || null,
      evidence: entry.evidence,
      relevanceClass: entry.relevanceClass || null,
      campaignRole: entry.campaignRole || null,
      reason: entry.reason,
    })),
  });

  return {
    selectedProducts,
    reserveProducts,
    shortlistCount: shortlist.length,
    eligibleCount: eligibleEvaluations.length,
    publishable,
    missingNeeds,
    coverage,
    curation,
    evaluations: [...evaluationByIndex.values()],
  };
}

function buildCampaignCurationRescueRule(rule, finalReview) {
  const strategy = normalizeCampaignMarketingStrategy(
    rule?.campaign_marketing_strategy
  );
  const missingNeeds = Array.isArray(finalReview?.missingNeeds)
    ? finalReview.missingNeeds
    : [];
  const missingSlotIds = new Set(
    (Array.isArray(finalReview?.coverage) ? finalReview.coverage : [])
      .filter((entry) => /missing/i.test(String(entry?.status || "")))
      .map((entry) => String(entry?.slotId || ""))
      .filter(Boolean)
  );
  const missingSlots = (strategy?.selectionSlots || []).filter(
    (slot) => !missingSlotIds.size || missingSlotIds.has(slot.id)
  );
  const targetedQueries = normalizeStoreSearchQueries(
    [
      ...missingNeeds.flatMap((entry) => entry?.searchQueries || []),
      ...missingSlots.flatMap((slot) => slot.searchQueries || []),
      ...(strategy?.searchQueries || []),
      ...splitStoreSearchQueryLine(rule?.product_search_queries),
    ],
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
  const requiredEvidence = normalizeCampaignStrategyList(
    [
      ...missingNeeds.flatMap((entry) => entry?.requiredEvidence || []),
      ...missingSlots.flatMap((slot) => slot.requiredEvidence || []),
      ...(strategy?.mustHaveEvidence || []),
    ],
    18,
    180
  );
  const missingNeedText = missingNeeds
    .map((entry) => entry.need)
    .filter(Boolean)
    .join("; ");

  return {
    ...rule,
    product_search_queries: targetedQueries,
    product_match_terms: collectUniqueTerms(
      [
        ...(strategy?.productMatchTerms || []),
        ...splitCampaignTermLine(rule?.product_match_terms),
      ],
      18
    ),
    prompt: [
      rule?.prompt,
      "Senior marketing curation rescue:",
      missingNeedText
        ? `Find products that fill these exact missing needs: ${missingNeedText}.`
        : "Find stronger verified alternatives for the uncovered dynamic selection slots.",
      requiredEvidence.length
        ? `Required product-level evidence: ${requiredEvidence.join("; ")}.`
        : "",
      "Do not treat the search query as evidence. Only concrete product-page facts may satisfy a missing need.",
    ]
      .filter(Boolean)
      .join("\n"),
    product_search_intent: [
      rule?.product_search_intent,
      missingNeedText,
      requiredEvidence.join("; "),
    ]
      .filter(Boolean)
      .join("\n"),
  };
}

async function runCampaignCurationTargetedRescue({
  supabase,
  openai,
  rule,
  brandProfile,
  websiteUrl,
  currentItems,
  finalReview,
  verificationCache,
  deadlineMs,
}) {
  const rescueRule = buildCampaignCurationRescueRule(rule, finalReview);
  const targetedQueries = normalizeStoreSearchQueries(
    splitStoreSearchQueryLine(rescueRule?.product_search_queries),
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
  const usedItems = dedupeWebsiteItemsByUrlTitleAndImage(currentItems).map(
    (item) => ({
      item_title: item?.title,
      item_url: item?.url,
      image_url: item?.image_url,
    })
  );
  let rescueCandidates = [];

  console.warn("Campaign carousel starting targeted curation rescue", {
    ruleId: rule?.id,
    brandProfileId: rule?.brand_profile_id,
    websiteUrl,
    selectedBeforeRescue: finalReview?.selectedProducts?.length || 0,
    publishableBeforeRescue: Boolean(finalReview?.publishable),
    missingNeeds: finalReview?.missingNeeds || [],
    targetedQueries,
  });

  try {
    const storeSearchCandidates = await discoverProductCandidatesFromStoreSearch({
      websiteUrl,
      campaignPrompt: buildCampaignResearchText(rescueRule),
      usedItems,
      excludeUsed: false,
      supabase,
      rule: rescueRule,
      deadlineMs,
    });
    if (storeSearchCandidates.length) {
      const verifiedStoreSearch =
        await verifyDiscoveredWebsiteProductCandidates({
          candidates: storeSearchCandidates,
          websiteUrl,
          limit: CAMPAIGN_CURATION_RESCUE_VERIFY_LIMIT,
          deadlineMs,
          verificationCache,
          supabase,
          rule: rescueRule,
        });
      rescueCandidates = dedupeWebsiteItemsByUrlTitleAndImage([
        ...rescueCandidates,
        ...verifiedStoreSearch,
      ]);
    }
  } catch (error) {
    if (isWebsiteRateLimitError(error)) throw error;
    console.warn("Campaign curation rescue store search unavailable", {
      ruleId: rule?.id,
      websiteUrl,
      message: error?.message,
    });
  }

  if (
    rescueCandidates.length < CAROUSEL_PRODUCT_SLIDE_TARGET &&
    Date.now() < deadlineMs - 45_000
  ) {
    try {
      const discoveryCandidates = await discoverProductCandidatesFromWebsite({
        websiteUrl,
        campaignPrompt: buildCampaignResearchText(rescueRule),
        usedItems,
        fastCampaignContinuation: false,
        excludeUsed: false,
        supabase,
        rule: rescueRule,
      });
      if (discoveryCandidates.length) {
        const verifiedDiscovery =
          await verifyDiscoveredWebsiteProductCandidates({
            candidates: discoveryCandidates,
            websiteUrl,
            limit: CAMPAIGN_CURATION_RESCUE_VERIFY_LIMIT,
            deadlineMs,
            verificationCache,
            supabase,
            rule: rescueRule,
          });
        rescueCandidates = dedupeWebsiteItemsByUrlTitleAndImage([
          ...rescueCandidates,
          ...verifiedDiscovery,
        ]);
      }
    } catch (error) {
      if (isWebsiteRateLimitError(error)) throw error;
      console.warn("Campaign curation rescue site discovery unavailable", {
        ruleId: rule?.id,
        websiteUrl,
        message: error?.message,
      });
    }
  }

  if (rescueCandidates.length) {
    rescueCandidates = await applyAiCampaignFitScores({
      openai,
      rule: rescueRule,
      brandProfile,
      items: rescueCandidates,
      maxItems: Math.min(
        CAMPAIGN_CURATION_RESCUE_VERIFY_LIMIT,
        rescueCandidates.length
      ),
      model: PRODUCT_RESEARCH_FAST_MODEL,
      escalateWhenUncertain: false,
      minimumStrongProducts: CAROUSEL_PRODUCT_SLIDE_TARGET,
    });
    rescueCandidates = rescueCandidates.map((item) => ({
      ...item,
      selection_priority: Math.max(
        Number(item?.selection_priority || 0),
        320
      ),
      campaign_fit_source: "campaign_curation_targeted_rescue",
      automation_search_method: "campaign_curation_targeted_rescue",
    }));

    await upsertWebsiteProductCatalogItems({
      supabase,
      userId: rule.user_id,
      brandProfileId: rule.brand_profile_id,
      sourceUrl: websiteUrl,
      items: rescueCandidates,
      discoverySource: "campaign_curation_targeted_rescue",
    });
  }

  console.log("Campaign carousel targeted curation rescue finished", {
    ruleId: rule?.id,
    brandProfileId: rule?.brand_profile_id,
    websiteUrl,
    targetedQueries,
    verifiedCandidateCount: rescueCandidates.length,
    candidates: rescueCandidates.slice(0, 24).map((item) => ({
      title: item?.title || null,
      url: item?.url || null,
      foundByQuery:
        item?.found_by_query ||
        getStoreSearchQueryFromUrl(item?.source_search_url) ||
        null,
      fastScore: item?.ai_campaign_fit_fast_score ?? null,
      reason: item?.ai_campaign_fit_fast_reason || null,
    })),
  });

  return {
    rescueRule,
    targetedQueries,
    candidateItems: rescueCandidates,
  };
}

function scoreCampaignFitForRule(item, rule) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return 0;
  }

  const aiScore = getAiCampaignFitScore(item);

  if (isCampaignFitRejectedForRule(item, rule)) {
    return -200;
  }

  const terms = extractCampaignTerms(rule);
  const explicitTerms = extractExplicitCampaignMatchTerms(rule);
  const avoidTerms = extractCampaignAvoidTerms(rule);
  const themeTerms = extractCampaignCoreThemeTerms(rule);
  const themeMatches = countCampaignCoreThemeTermMatches(item, rule);
  const sourceThemeMatches = countCampaignSourceThemeMatches(item, rule);
  const anchorMatches = countCampaignAnchorTermMatches(item, rule);
  const anchorTerms = extractCampaignAnchorTerms(rule);
  const primaryMatches = countPrimaryCampaignTermMatches(item, rule);
  const hasCoreThemeGuard = themeTerms.length > 0;
  const hasAnchorGuard = !hasCoreThemeGuard && anchorTerms.length > 0;
  const hasStrictThemeGuard = hasCoreThemeGuard || hasAnchorGuard;
  const directCampaignSignalCount = hasCoreThemeGuard
    ? themeMatches
    : hasAnchorGuard
      ? anchorMatches
      : primaryMatches;
  const campaignSignalState = getCampaignProductSignalState(item, rule);
  const campaignThemeFitApproved =
    campaignSignalState.hasAiCampaignApproval;
  const contextualCampaignApproval =
    directCampaignSignalCount === 0 &&
    campaignSignalState.contextualCampaignApproval;
  if (!terms.length && !avoidTerms.length && !anchorTerms.length && !themeTerms.length) {
    return aiScore !== null ? aiScore : Number(item?.campaign_fit_score || 0);
  }

  const title = normalizeSearchText(item?.title);
  const url = normalizeSearchText(item?.url || item?.product_url || item?.item_url);
  const description = normalizeSearchText(item?.description);
  const reason = normalizeSearchText(item?.reason);
  const source = normalizeSearchText(item?.catalog_source || item?.discovery_source || item?.campaign_fit_source);
  const haystack = `${title} ${url} ${description} ${reason}`;
  // campaign_fit_score is a derived value. Starting from a previously derived
  // value made the score grow every time this function was called.
  let score =
    aiScore !== null
      ? campaignThemeFitApproved
        ? Math.max(aiScore, CAMPAIGN_MINIMUM_PRODUCT_FIT_SCORE)
        : aiScore
      : 0;
  if (contextualCampaignApproval) {
    score = Math.max(score, CAMPAIGN_MINIMUM_PRODUCT_FIT_SCORE);
  }

  const shortRoots = getPrimaryCampaignShortRoots(rule);

  if (themeMatches > 0) {
    score += 125 + themeMatches * 45;
  } else if (themeTerms.length) {
    // Direct theme products lead, but a product with a senior/AI-audited,
    // campaign-specific contextual role is a valid supporting candidate.
    score += contextualCampaignApproval ? 15 : -120;
  }

  if (anchorMatches > 0) {
    score += 90 + anchorMatches * 35;
  } else if (explicitTerms.length && anchorTerms.length) {
    // Dynamic broad terms can still help ranking after an anchor matched, but
    // without an anchor they must not promote a generic product into a themed
    // campaign card.
    score += contextualCampaignApproval ? 10 : -80;
  }

  const titleTokens = tokenizeSearchText(title);
  const urlTokens = tokenizeSearchText(url);
  const descriptionTokens = tokenizeSearchText(description);
  const reasonTokens = tokenizeSearchText(reason);

  for (const term of terms) {
    const isExplicit = explicitTerms.includes(term);
    const isShortRoot = shortRoots.has(term);

    if (isShortRoot) {
      const titleRootMatch = titleTokens.some((token) => token.startsWith(term) && token.length >= term.length + 2);
      const urlRootMatch = urlTokens.some((token) => token.startsWith(term) && token.length >= term.length + 2);
      const descriptionRootMatch = descriptionTokens.some((token) => token.startsWith(term) && token.length >= term.length + 2);
      const reasonRootMatch = reasonTokens.some((token) => token.startsWith(term) && token.length >= term.length + 2);

      if (titleRootMatch) score += 48;
      if (urlRootMatch) score += 42;
      if (descriptionRootMatch) score += 10;
      if (reasonRootMatch) score += 8;
      continue;
    }

    if (title.includes(term)) score += isExplicit ? 65 : 35;
    if (url.includes(term)) score += isExplicit ? 65 : 35;
    if (description.includes(term)) score += isExplicit ? 18 : 8;
    if (reason.includes(term)) score += isExplicit ? 16 : 8;
  }

  for (const avoidTerm of avoidTerms) {
    if (!avoidTerm) continue;
    if (title.includes(avoidTerm)) score -= 90;
    if (url.includes(avoidTerm)) score -= 90;
    if (description.includes(avoidTerm)) score -= 35;
    if (haystack.includes(avoidTerm)) score -= 20;
  }

  if (source.includes("ai_campaign_research")) score += 25;
  if (source.includes("campaign")) score += 12;

  if (
    !contextualCampaignApproval &&
    isLikelyGenericCustomTemplateProduct(item) &&
    themeMatches === 0 &&
    sourceThemeMatches === 0 &&
    anchorMatches === 0
  ) {
    score -= 160;
  }

  if (
    hasStrictThemeGuard &&
    directCampaignSignalCount === 0 &&
    !contextualCampaignApproval &&
    getCampaignThemeContract(rule)
  ) {
    // A themed search page does not make every listed product relevant. Under
    // the semantic theme contract, verified product text is mandatory evidence.
    score = Math.min(score, CAMPAIGN_MINIMUM_PRODUCT_FIT_SCORE - 5);
  }

  // Do not let heuristic title/source bonuses promote an AI-evaluated weak or
  // medium product into a stronger tier than the product-level evaluation.
  if (!campaignThemeFitApproved && aiScore !== null && aiScore < 55) {
    score = Math.min(score, 54);
  } else if (
    !campaignThemeFitApproved &&
    aiScore !== null &&
    aiScore < CAMPAIGN_NEAR_PRODUCT_FIT_SCORE
  ) {
    score = Math.min(score, CAMPAIGN_NEAR_PRODUCT_FIT_SCORE - 1);
  }

  return Math.max(score, -200);
}

function getStrongCampaignFitItems(items, rule) {
  return getCampaignFitItemsAtOrAboveScore(
    items,
    rule,
    CAMPAIGN_STRONG_PRODUCT_FIT_SCORE
  );
}

function getSupportingCampaignFitItems(items, rule) {
  return getCampaignFitItemsAtOrAboveScore(
    items,
    rule,
    CAMPAIGN_SUPPORTING_PRODUCT_FIT_SCORE
  );
}

function getCampaignFitItemsAtOrAboveScore(items, rule, minimumScore) {
  if (!isProductIntentScopedWebsiteRule(rule)) {
    return [];
  }

  return (items || [])
    .map((item) => ({
      ...item,
      campaign_fit_score: scoreCampaignFitForRule(item, rule),
    }))
    .filter((item) => Number(item.campaign_fit_score || 0) >= minimumScore)
    .sort((a, b) => Number(b.campaign_fit_score || 0) - Number(a.campaign_fit_score || 0));
}

function scoreWebsiteItemForRule(item, rule) {
  const haystack = `${item?.title || ""} ${item?.description || ""} ${item?.url || ""}`.toLowerCase();
  const promptText = `${rule?.prompt || ""} ${rule?.campaign_goal || ""} ${rule?.strategy_notes || ""}`.toLowerCase();
  const promptWords = promptText
    .split(/[^\p{L}\p{N}]+/u)
    .filter((word) => word.length >= 4);

  let score = 0;

  for (const word of promptWords) {
    if (haystack.includes(word)) {
      score += 4;
    }
  }

  if (isProductIntentScopedWebsiteRule(rule)) {
    score += scoreCampaignFitForRule(item, rule);
  }

  if (item?.image_url) score += 3;
  if (item?.last_used_at) score -= 2;
  score -= Math.min(Number(item?.times_used || 0), 20);

  return score;
}

function isAcceptableWebsiteTextProductSelection(item, rule) {
  if (isProductKnownUnavailableForPromotion(item)) {
    return false;
  }

  if (!isProductIntentScopedWebsiteRule(rule)) {
    return true;
  }

  return (
    isProductEligibleForPromotion(item) &&
    scoreCampaignFitForRule(item, rule) >= CAMPAIGN_MINIMUM_PRODUCT_FIT_SCORE
  );
}

async function chooseUnusedWebsiteItem({
  supabase,
  userId,
  brandProfileId,
  sourceUrl,
  contentType,
  items,
  rule = null,
  usedWebsiteImageUrlsThisRun = new Set(),
  recentUsedItems = null,
  allowReuseWhenExhausted = true,
}) {
  const currentCycle = await getCurrentWebsiteCycle({
    supabase,
    userId,
    brandProfileId,
    sourceUrl,
    contentType,
  });

  const usedItems = Array.isArray(recentUsedItems)
    ? recentUsedItems
    : await getRecentUsedWebsiteItems({
        supabase,
        userId,
        brandProfileId,
        sourceUrl,
        contentType,
      });

  const normalizedItems = (items || [])
    .map((item) => ({
      ...item,
      item_key: item?.item_key || createItemKey(item),
    }))
    .filter((item) => (item?.url || item?.title) && !isProductKnownUnavailableForPromotion(item))
    .sort((a, b) => {
      if (!rule) return 0;

      const aScore = scoreWebsiteItemForRule(a, rule) +
        scoreProductDiversityAgainstRecentHistory(a, usedItems);
      const bScore = scoreWebsiteItemForRule(b, rule) +
        scoreProductDiversityAgainstRecentHistory(b, usedItems);
      const scoreDelta = bScore - aScore;

      if (scoreDelta !== 0) return scoreDelta;

      const aSource = Number(a?.selection_priority || 0);
      const bSource = Number(b?.selection_priority || 0);

      if (aSource !== bSource) return bSource - aSource;

      return String(a?.title || '').localeCompare(String(b?.title || ''));
    });

  const unusedItems = normalizedItems.filter(
    (item) => !hasWebsiteItemAlreadyBeenUsed(item, usedItems, sourceUrl)
  );

  function hasFreshWebsiteImage(item) {
    const imageUrl = normalizeComparableValue(item?.image_url);

    if (!imageUrl) {
      return false;
    }

    return !usedWebsiteImageUrlsThisRun.has(imageUrl);
  }

  function hasDuplicateWebsiteImageThisRun(item) {
    const imageUrl = normalizeComparableValue(item?.image_url);

    if (!imageUrl) {
      return false;
    }

    return usedWebsiteImageUrlsThisRun.has(imageUrl);
  }

  const bestUnusedWithFreshImage = unusedItems.find(hasFreshWebsiteImage);

  if (bestUnusedWithFreshImage) {
    return {
      item: bestUnusedWithFreshImage,
      cycleNumber: currentCycle,
      startedNewCycle: false,
      useWebsiteImage: true,
      reusedBecauseExhausted: false,
    };
  }

  const bestUnusedWithoutImage = unusedItems.find((item) => !item.image_url);

  if (bestUnusedWithoutImage) {
    return {
      item: bestUnusedWithoutImage,
      cycleNumber: currentCycle,
      startedNewCycle: false,
      useWebsiteImage: false,
      reusedBecauseExhausted: false,
    };
  }

  const bestUnusedWithDuplicateImage = unusedItems.find(
    hasDuplicateWebsiteImageThisRun
  );

  if (bestUnusedWithDuplicateImage) {
    return {
      item: bestUnusedWithDuplicateImage,
      cycleNumber: currentCycle,
      startedNewCycle: false,
      useWebsiteImage: false,
      reusedBecauseExhausted: false,
    };
  }

  if (!allowReuseWhenExhausted) {
    return {
      item: null,
      cycleNumber: currentCycle,
      startedNewCycle: false,
      useWebsiteImage: false,
      reusedBecauseExhausted: false,
    };
  }

  const fallbackItem = normalizedItems.find(
    (item) => item?.image_url && !hasDuplicateWebsiteImageThisRun(item)
  );

  if (!fallbackItem) {
    return {
      item: null,
      cycleNumber: currentCycle,
      startedNewCycle: false,
      useWebsiteImage: false,
      reusedBecauseExhausted: false,
    };
  }

  console.log("Website product rotation exhausted; reusing an older product after trying recent-history avoidance", {
    brandProfileId,
    sourceUrl,
    contentType,
    recentUsedCount: usedItems.length,
    candidateCount: normalizedItems.length,
    reuseLimit: WEBSITE_PRODUCT_REUSE_LIMIT,
  });

  return {
    item: fallbackItem,
    cycleNumber: currentCycle + 1,
    startedNewCycle: true,
    useWebsiteImage: hasFreshWebsiteImage(fallbackItem),
    reusedBecauseExhausted: true,
  };
}
function getHostnameWithoutWww(value) {
  try {
    return new URL(value).hostname.toLowerCase().replace(/^www\./, "");
  } catch {
    return "";
  }
}

function isSameOrSubdomainUrl(candidateUrl, websiteUrl) {
  const candidateHost = getHostnameWithoutWww(candidateUrl);
  const websiteHost = getHostnameWithoutWww(websiteUrl);

  if (!candidateHost || !websiteHost) {
    return false;
  }

  return candidateHost === websiteHost || candidateHost.endsWith(`.${websiteHost}`);
}

const WEBSITE_MARKET_PATH_CODES = new Set([
  "ae", "at", "au", "be", "bg", "br", "ca", "ch", "cz", "de", "dk", "ee",
  "es", "eu", "fi", "fr", "gb", "gr", "hr", "hu", "ie", "is", "it", "jp",
  "lt", "lu", "lv", "mx", "nl", "no", "nz", "pl", "pt", "ro", "se", "si",
  "sk", "uk", "us", "cn", "hk", "kr", "sg", "tw", "in", "za", "uz",
]);

const WEBSITE_LANGUAGE_PATH_CODES = new Set([
  "ar", "bg", "cs", "da", "de", "el", "en", "es", "fi", "fil", "fr", "hi",
  "hu", "id", "it", "ja", "ko", "ms", "nb", "nl", "nn", "no", "pl", "pt",
  "ro", "ru", "sv", "th", "tr", "uk", "uz", "vi", "zh",
]);

function getWebsiteLocalePathScope(value) {
  try {
    const segments = new URL(String(value || "")).pathname
      .split("/")
      .map((segment) => segment.trim().toLowerCase().replace(/_/g, "-"))
      .filter(Boolean);
    const first = segments[0] || "";
    const second = segments[1] || "";
    if (!first) return null;

    const compound = first.match(/^([a-z]{2,3})-([a-z]{2})$/);
    if (compound && WEBSITE_LANGUAGE_PATH_CODES.has(compound[1])) {
      return {
        language: compound[1],
        market: compound[2],
        prefix: [first],
      };
    }

    if (WEBSITE_LANGUAGE_PATH_CODES.has(first) && WEBSITE_MARKET_PATH_CODES.has(second)) {
      return { language: first, market: second, prefix: [first, second] };
    }

    if (WEBSITE_MARKET_PATH_CODES.has(first) && WEBSITE_LANGUAGE_PATH_CODES.has(second)) {
      return { language: second, market: first, prefix: [first, second] };
    }

    if (WEBSITE_LANGUAGE_PATH_CODES.has(first) && WEBSITE_MARKET_PATH_CODES.has(first)) {
      return { language: first, market: first, prefix: [first] };
    }
    if (WEBSITE_LANGUAGE_PATH_CODES.has(first)) {
      return { language: first, market: "", prefix: [first] };
    }
    if (WEBSITE_MARKET_PATH_CODES.has(first)) {
      return { language: "", market: first, prefix: [first] };
    }

    return null;
  } catch {
    return null;
  }
}

