const PRODUCT_MARKET_PRIMARY_LANGUAGES = {
  se: ["sv", "en"], dk: ["da", "en"], no: ["no", "nb", "en"], fi: ["fi", "en"],
  de: ["de", "en"], nl: ["nl", "en"], be: ["nl", "fr", "en"], fr: ["fr", "en"],
  es: ["es", "en"], it: ["it", "en"], pt: ["pt", "en"], at: ["de", "en"],
  ch: ["de", "fr", "it", "en"], pl: ["pl", "en"], gb: ["en"], uk: ["en"], us: ["en"],
  ca: ["en", "fr"], au: ["en"], nz: ["en"], ie: ["en"], ae: ["ar", "en"],
  sg: ["en"], in: ["en", "hi"], za: ["en"], br: ["pt", "en"], mx: ["es", "en"], jp: ["ja", "en"],
  cn: ["zh", "en"], hk: ["zh", "en"], kr: ["ko", "en"], tw: ["zh", "en"], uz: ["uz", "ru", "en"],
};

function normalizeProductMarketCode(value) {
  const raw = String(value || "").trim();
  if (!raw || /^(?:auto|automatic|global|international|international \/ global|other)$/i.test(raw)) {
    return "";
  }

  const compact = raw.toLowerCase().replace(/_/g, "-");
  if (/^[a-z]{2}$/.test(compact)) {
    return compact === "uk" ? "gb" : compact;
  }

  for (const [pattern, code] of PRODUCT_MARKET_NAME_PATTERNS) {
    if (pattern.test(raw)) return code;
  }

  return "";
}

function inferProductMarketCodeFromWebsiteUrl(value) {
  const scoped = getWebsiteLocalePathScope(value);
  if (scoped?.market) return scoped.market === "uk" ? "gb" : scoped.market;

  try {
    const tld = new URL(String(value || "")).hostname.toLowerCase().split(".").filter(Boolean).at(-1) || "";
    if (WEBSITE_MARKET_PATH_CODES.has(tld)) return tld === "uk" ? "gb" : tld;
  } catch {
    // No URL market signal.
  }
  return "";
}

function getProductMarketCodeForRule(rule, websiteUrl = "", brandProfile = null) {
  return (
    normalizeProductMarketCode(
      brandProfile?.country_code || rule?.country_code || rule?.brand_profile?.country_code
    ) ||
    normalizeProductMarketCode(
      brandProfile?.content_market || rule?.content_market || rule?.brand_profile?.content_market
    ) ||
    inferProductMarketCodeFromWebsiteUrl(websiteUrl)
  );
}

function matchesConfiguredWebsiteMarket(candidateUrl, websiteUrl, targetMarketCode = "") {
  const configured = getWebsiteLocalePathScope(websiteUrl);
  const candidate = getWebsiteLocalePathScope(candidateUrl);
  const targetMarket =
    normalizeProductMarketCode(targetMarketCode) ||
    (configured?.market === "uk" ? "gb" : configured?.market || "") ||
    inferProductMarketCodeFromWebsiteUrl(websiteUrl);
  const candidateMarket = candidate?.market === "uk" ? "gb" : candidate?.market || "";

  // Product market and content language are intentionally independent.
  // A Swedish-market product may be advertised in German, English or any other
  // customer-selected content language. Only an explicit conflicting MARKET
  // path (for example /da-dk while the target market is SE) is rejected here.
  if (targetMarket && candidateMarket && candidateMarket !== targetMarket) {
    return false;
  }

  const configuredMarket = configured?.market === "uk" ? "gb" : configured?.market || "";
  if (configuredMarket && candidateMarket && candidateMarket !== configuredMarket) {
    return false;
  }

  // Locale-neutral canonical URLs remain eligible. Many Shopify storefronts
  // canonicalize a valid localized product page back to /products/... . Market
  // availability is therefore established by the market-specific discovery
  // source, not by requiring every final canonical URL to contain a locale.
  return true;
}

function isUrlExplicitlyScopedToProductMarket(value, targetMarketCode) {
  const targetMarket = normalizeProductMarketCode(targetMarketCode);
  const scope = getWebsiteLocalePathScope(value);
  const scopedMarket = scope?.market === "uk" ? "gb" : scope?.market || "";
  return Boolean(targetMarket && scopedMarket && scopedMarket === targetMarket);
}

function isLikelyNonProductUrl(value, websiteUrl) {
  try {
    const url = new URL(value);
    const path = url.pathname.toLowerCase();
    const hasProductPath =
      /^\/products?\/[^/]+/i.test(path) ||
      /\/collections\/[^/]+\/products\/[^/]+/i.test(path);

    if (!path || path === "/" || isWeakItemUrl(value, websiteUrl) || isBadProductUrl(value)) {
      return true;
    }

    const blockedPathParts = [
      "/blog",
      "/news",
      "/nyheter",
      "/article",
      "/artiklar",
      "/cart",
      "/checkout",
      "/checkouts",
      "/kundvagn",
      "/kassa",
      "/account",
      "/login",
      "/sign-in",
      "/payment",
      "/payments",
      "/wallet",
      "/api",
      "/graphql",
      "/ajax",
      "/collect",
      "/tracking",
      "/analytics",
      "/pixel",
      "/privacy",
      "/integritet",
      "/cookie",
      "/terms",
      "/villkor",
      "/contact",
      "/kontakt",
      "/about",
      "/om-oss",
      "/search",
      "/sok",
      "/sök",
      "/collection",
      "/collections",
      "/category",
      "/categories",
      "/page",
      "/pages",
    ];

    return blockedPathParts.some((part) => {
      if (hasProductPath && ["/collection", "/collections"].includes(part)) {
        return false;
      }

      return path.includes(part);
    });
  } catch {
    return true;
  }
}

function hasSmallImageDimensionHint(value, minDimension = 500) {
  const rawUrl = String(value || "");
  const lowerUrl = rawUrl.toLowerCase();

  if (!lowerUrl) {
    return true;
  }

  if (/(?:^|[\/_-])(thumb|thumbnail|small|tiny|mini|xs|swatch|preview|icon)(?:[\/_-]|$)/i.test(lowerUrl)) {
    return true;
  }

  // Only an explicit 400x400-style token is a generic filename dimension.
  // Underscores and hyphens also occur in product IDs and content hashes (for
  // example "_H26_46a...") and must not make a verified image look too small.
  const sizeMatches = [...lowerUrl.matchAll(/(?:^|[^0-9])([1-9][0-9]{1,3})[x×]([1-9][0-9]{1,3})(?:[^0-9]|$)/g)];
  for (const match of sizeMatches) {
    const width = Number(match[1]);
    const height = Number(match[2]);

    if (width && height && Math.max(width, height) < minDimension) {
      return true;
    }
  }

  try {
    const parsedUrl = new URL(rawUrl);
    const smallQueryKeys = [
      "w",
      "width",
      "h",
      "height",
      "imwidth",
      "imheight",
      "maxwidth",
      "maxheight",
    ];

    for (const key of smallQueryKeys) {
      const value = Number(parsedUrl.searchParams.get(key));
      if (value && value < minDimension) {
        return true;
      }
    }
  } catch (_) {
    // Ignore malformed URLs here; other URL validators handle them.
  }

  return false;
}

function isLowQualityProductImageUrl(value) {
  return hasSmallImageDimensionHint(value, 500);
}

function isStructurallyBadProductImageUrl(value) {
  const lowerUrl = String(value || "").toLowerCase();

  if (!lowerUrl) {
    return true;
  }

  return (
    lowerUrl.includes("logo") ||
    lowerUrl.includes("favicon") ||
    lowerUrl.includes("icon") ||
    lowerUrl.includes("sprite") ||
    lowerUrl.includes("placeholder") ||
    lowerUrl.includes("no-image") ||
    lowerUrl.includes("no_image") ||
    lowerUrl.includes("missing-image") ||
    lowerUrl.includes("blank") ||
    lowerUrl.includes("default-image") ||
    lowerUrl.includes("banner") ||
    lowerUrl.includes("hero") ||
    lowerUrl.includes("background") ||
    lowerUrl.includes("classy-fabric") ||
    lowerUrl.includes("theme") ||
    lowerUrl.includes("pattern") ||
    lowerUrl.includes("separator") ||
    lowerUrl.includes("texture") ||
    lowerUrl.includes("swatch") ||
    lowerUrl.endsWith(".svg")
  );
}

function isBadProductImageUrl(value) {
  return (
    isStructurallyBadProductImageUrl(value) ||
    isLowQualityProductImageUrl(value)
  );
}

function hasVerifiedLargeProductImage(item, minDimension = 500) {
  const width = Number(item?.product_image_width || 0);
  const height = Number(item?.product_image_height || 0);

  return Boolean(
    item?.product_image_resolution_verified === true &&
      width >= minDimension &&
      height >= minDimension
  );
}

function isUsableProductImageForItem(item) {
  if (!item?.image_url || isStructurallyBadProductImageUrl(item.image_url)) {
    return false;
  }

  // Measured dimensions from the fetched image are authoritative. URL text is
  // only a fallback hint while no verified dimensions are available.
  return (
    hasVerifiedLargeProductImage(item) ||
    !isLowQualityProductImageUrl(item.image_url)
  );
}

function normalizeJsonLdType(value) {
  if (Array.isArray(value)) {
    return value.map((item) => String(item || "").toLowerCase());
  }

  return [String(value || "").toLowerCase()];
}

function flattenJsonLd(value) {
  const items = [];

  function walk(node) {
    if (!node) {
      return;
    }

    if (Array.isArray(node)) {
      for (const child of node) {
        walk(child);
      }

      return;
    }

    if (typeof node !== "object") {
      return;
    }

    items.push(node);

    if (Array.isArray(node["@graph"])) {
      walk(node["@graph"]);
    }

    if (Array.isArray(node.itemListElement)) {
      walk(node.itemListElement);
    }
  }

  walk(value);

  return items;
}

function extractJsonLdObjects(html) {
  const objects = [];
  const scriptRegex =
    /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;

  let match;

  while ((match = scriptRegex.exec(String(html || ""))) !== null) {
    const rawJson = decodeHtmlEntities(match[1] || "").trim();

    if (!rawJson) {
      continue;
    }

    try {
      const parsed = JSON.parse(rawJson);
      objects.push(...flattenJsonLd(parsed));
    } catch {
      // Ignore invalid JSON-LD blocks.
    }
  }

  return objects;
}

function findJsonLdProduct(html) {
  const objects = extractJsonLdObjects(html);

  return (
    objects.find((item) =>
      normalizeJsonLdType(item?.["@type"]).some((type) => type.includes("product"))
    ) || null
  );
}


function findBestJsonLdProduct(html, pageUrl = "", expectedTitle = "") {
  const products = extractJsonLdObjects(html).filter((item) =>
    normalizeJsonLdType(item?.["@type"]).some((type) => type.includes("product"))
  );

  if (!products.length) {
    return null;
  }

  const expectedComparable = normalizeComparableValue(sanitizeProductTitleForCard(expectedTitle));
  const pageComparable = normalizeComparableValue(pageUrl);

  return products
    .map((product, index) => {
      let score = 0;
      const productUrl = getProductUrlFromJsonLd(product, pageUrl);
      const productComparable = normalizeComparableValue(productUrl);
      const titleComparable = normalizeComparableValue(product?.name);

      if (pageComparable && productComparable && pageComparable === productComparable) {
        score += 120;
      } else if (
        pageComparable &&
        productComparable &&
        (pageComparable.includes(productComparable) || productComparable.includes(pageComparable))
      ) {
        score += 60;
      }

      if (expectedComparable && titleComparable) {
        if (expectedComparable === titleComparable) {
          score += 90;
        } else {
          const expectedTokens = expectedComparable
            .split(/[^\p{L}\p{N}]+/u)
            .filter((token) => token.length >= 4);
          const titleTokens = new Set(
            titleComparable
              .split(/[^\p{L}\p{N}]+/u)
              .filter((token) => token.length >= 4)
          );
          score += expectedTokens.filter((token) => titleTokens.has(token)).length * 12;
        }
      }

      if (product?.offers) score += 8;
      if (product?.image) score += 4;

      return { product, score, index };
    })
    .sort((a, b) => b.score - a.score || a.index - b.index)[0]?.product || null;
}

function collectImageValuesFromObject(value, results = []) {
  if (!value) {
    return results;
  }

  if (typeof value === "string") {
    results.push(value);
    return results;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      collectImageValuesFromObject(item, results);
    }
    return results;
  }

  if (typeof value === "object") {
    for (const key of ["url", "contentUrl", "src", "image"]) {
      if (value?.[key]) {
        collectImageValuesFromObject(value[key], results);
      }
    }
  }

  return results;
}

function getProductImagesFromJsonLd(product, pageUrl) {
  const rawImages = collectImageValuesFromObject(product?.image);
  const seen = new Set();
  const images = [];

  for (const rawImage of rawImages) {
    const resolvedUrl = rawImage ? resolveUrl(rawImage, pageUrl) : null;
    if (
      !resolvedUrl ||
      !isHttpUrl(resolvedUrl) ||
      isBadProductImageUrl(resolvedUrl)
    ) {
      continue;
    }
    const key = canonicalProductImageAssetKey(resolvedUrl) || resolvedUrl;
    if (seen.has(key)) continue;
    seen.add(key);
    images.push(resolvedUrl);
    if (images.length >= 12) break;
  }

  return images;
}

function getProductImageFromJsonLd(product, pageUrl) {
  return getProductImagesFromJsonLd(product, pageUrl)[0] || null;
}

function extractCanonicalProductPageUrl(html, pageUrl) {
  const linkTags = String(html || "").match(/<link\b[^>]*>/gi) || [];
  for (const tag of linkTags) {
    const rel = String(getAttributeValueFromTag(tag, "rel") || "").toLowerCase();
    if (!rel.split(/\s+/).includes("canonical")) continue;
    const href = normalizeEscapedUrl(getAttributeValueFromTag(tag, "href"));
    const resolved = href ? resolveUrl(href, pageUrl) : null;
    if (resolved && isHttpUrl(resolved)) return resolved;
  }
  return pageUrl || "";
}

function getStructuredProductIdentifier(product, pageUrl = "") {
  const explicit = String(
    product?.sku ||
      product?.mpn ||
      product?.productID ||
      product?.gtin14 ||
      product?.gtin13 ||
      product?.gtin12 ||
      product?.gtin8 ||
      ""
  ).trim();
  if (explicit) return explicit;
  return getAuthoritativeProductIdentityHints({ url: pageUrl })[0] || "";
}

function getStructuredProductBrand(product) {
  const raw =
    typeof product?.brand === "string"
      ? product.brand
      : product?.brand?.name ||
        product?.manufacturer?.name ||
        product?.manufacturer ||
        "";
  return String(raw || "").trim();
}

function normalizeWebsiteProductSourceTypeForRuntime(value) {
  const raw = String(value || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  const aliases = { shop: "ecommerce", webshop: "ecommerce", retailer: "retailer_catalog", manufacturer: "manufacturer_catalog", product_catalog: "manufacturer_catalog" };
  return aliases[raw] || raw || "";
}

function getWebsiteProductSourceTypeForRule(rule, brandProfile = null) {
  const explicit = normalizeWebsiteProductSourceTypeForRuntime(
    rule?.website_product_source_type || brandProfile?.website_product_source_type || ""
  );
  if (explicit) return explicit;

  const reasonText = String(
    rule?.website_product_mode_reason || brandProfile?.website_product_mode_reason || ""
  );
  const taggedSourceType = reasonText.match(/\[source_type=([a-z_]+)\]/i)?.[1] || "";
  const taggedNormalized = normalizeWebsiteProductSourceTypeForRuntime(taggedSourceType);
  if (taggedNormalized) return taggedNormalized;

  // Backward-compatible inference for brand profiles analyzed before v144.53.
  // This avoids forcing an immediate re-analysis just to stop treating a
  // manufacturer catalog like a direct-stock retailer.
  const context = normalizeSearchText([
    rule?.website_product_mode_reason,
    brandProfile?.website_product_mode_reason,
    rule?.brand_profile?.industry,
    brandProfile?.industry,
    rule?.brand_profile?.brand_description,
    brandProfile?.brand_description,
  ].filter(Boolean).join(" "));
  if (/manufacturer|manufactur|producer|tillverk|official product catalog|product range|aterforsalj|återförsälj|dealer network/.test(context)) {
    return "manufacturer_catalog";
  }
  return "ecommerce";
}

function isManufacturerCatalogSource(rule, brandProfile = null) {
  return getWebsiteProductSourceTypeForRule(rule, brandProfile) === "manufacturer_catalog";
}

function normalizeProductAvailabilityStatus(value) {
  const raw = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\/schema\.org\//i, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ");
  if (!raw) return "unknown";
  if (/discontinued|utgått|utgatt|utgången|utgangen/.test(raw)) return "discontinued";
  if (/out of stock|outofstock|sold out|soldout|unavailable|slut i lager|ej i lager/.test(raw)) return "out_of_stock";
  if (/pre ?order|förbeställ|forbestall/.test(raw)) return "preorder";
  if (/back ?order|restorder/.test(raw)) return "backorder";
  if (/in stock|instock|i lager/.test(raw)) return "in_stock";
  if (/catalog current|current catalog|official catalog|current official product|current product range/.test(raw)) return "catalog_current";
  if (/available|orderable|buyable|kan köpas|kan kopas/.test(raw)) return "available";
  return "unknown";
}

function getStructuredProductAvailability(product) {
  const offers = Array.isArray(product?.offers)
    ? product.offers
    : product?.offers
      ? [product.offers]
      : [];
  for (const offer of offers) {
    const normalized = normalizeProductAvailabilityStatus(offer?.availability);
    if (normalized !== "unknown") return normalized;
  }
  return "unknown";
}

function getProductPromotionAvailability(item) {
  return normalizeProductAvailabilityStatus(
    item?.locked_product_availability ||
      item?.availability_status ||
      item?.availability ||
      item?.product_availability ||
      ""
  );
}

function isProductKnownUnavailableForPromotion(item) {
  return ["out_of_stock", "discontinued"].includes(
    getProductPromotionAvailability(item)
  );
}

function isProductConfirmedPurchasable(item) {
  const availability = getProductPromotionAvailability(item);
  if (availability === "in_stock") {
    return true;
  }

  // Some commerce platforms (including Quickbutik stores) do not expose a
  // literal "in stock" string or structured stock quantity. A freshly opened
  // official product detail page with a real purchase action is sufficient
  // current purchasability proof as long as the page did not expose an
  // out-of-stock/discontinued signal. inferCurrentProductAvailability() checks
  // those negative signals before returning "available".
  return Boolean(
    availability === "available" &&
      item?.product_page_verified === true &&
      item?.concrete_product_verified === true &&
      item?.purchase_action_detected === true &&
      !isProductKnownUnavailableForPromotion(item)
  );
}

function isProductEligibleForWebsiteSource(item, rule, brandProfile = null) {
  if (isProductKnownUnavailableForPromotion(item)) return false;
  if (!isManufacturerCatalogSource(rule, brandProfile)) {
    return isProductConfirmedPurchasable(item);
  }

  const availability = getProductPromotionAvailability(item);
  const hasIdentity = Boolean(item?.url && item?.title && item?.image_url);
  const hasOfficialVerification = Boolean(
    item?.product_identity_locked === true ||
    item?.concrete_product_verified === true ||
    item?.product_page_verified === true ||
    item?.authoritative_web_agent_selected === true ||
    item?.indexed_security_fallback_verified === true ||
    item?.locked_product_page_object === true ||
    item?.exact_page_verified === true ||
    availability === "catalog_current"
  );
  return hasIdentity && hasOfficialVerification;
}

function hasDirectProductPurchaseAction(html) {
  return /(?:add[-_\s]?to[-_\s]?(?:cart|bag)|buy\s+now|order\s+now|lägg\s+i\s+varukorg|lagg\s+i\s+varukorg|köp\s+nu|kop\s+nu|beställ\s+nu|bestall\s+nu|product-form(?:__submit)?)/i.test(
    String(html || "")
  );
}

function inferCurrentProductAvailability({ product, html, fallback = "unknown" }) {
  const structured = getStructuredProductAvailability(product);
  if (structured !== "unknown") return structured;

  const pageText = normalizeSearchText(stripHtmlToText(html || ""));
  if (/\b(?:denna produkt har utgatt|denna produkt har utgått|product has been discontinued|discontinued product)\b/i.test(pageText)) {
    return "discontinued";
  }
  if (/\b(?:out of stock|sold out|slut i lager|ej i lager|currently unavailable)\b/i.test(pageText)) {
    return "out_of_stock";
  }
  if (hasDirectProductPurchaseAction(html)) return "available";

  return normalizeProductAvailabilityStatus(fallback);
}

function isProductEligibleForPromotion(item) {
  if (isProductKnownUnavailableForPromotion(item)) return false;
  // v144.19: purchase buttons alone are not stock proof. Some retailers keep
  // "add to cart" visible for order items with zero current stock.
  return isProductConfirmedPurchasable(item);
}

function findExactPageJsonLdProduct(html, pageUrl) {
  const products = extractJsonLdObjects(html).filter((item) =>
    normalizeJsonLdType(item?.["@type"]).some((type) => type.includes("product"))
  );
  if (!products.length) return null;

  const canonicalPage = normalizeComparableValue(
    canonicalizeWebsiteProductUrl(pageUrl, pageUrl) || pageUrl
  );
  const exact = products.find((product) => {
    const productUrl = getProductUrlFromJsonLd(product, pageUrl);
    const comparable = normalizeComparableValue(
      canonicalizeWebsiteProductUrl(productUrl, pageUrl) || productUrl
    );
    return canonicalPage && comparable && canonicalPage === comparable;
  });
  if (exact) return exact;

  // A single Product entity on a direct product page is unambiguous. If the
  // page exposes several Product entities and none points to the current URL,
  // do not guess which recommendation/variant is the main product.
  return products.length === 1 ? products[0] : null;
}

function buildLockedProductIdentityFingerprint({
  url,
  identifier,
  title,
  primaryImageUrl,
}) {
  return crypto
    .createHash("sha256")
    .update(
      [
        normalizeComparableValue(url),
        normalizeComparableValue(identifier),
        normalizeComparableValue(title),
        canonicalProductImageAssetKey(primaryImageUrl) ||
          normalizeComparableValue(primaryImageUrl),
      ].join("|")
    )
    .digest("hex")
    .slice(0, 24);
}

function extractLockedProductObjectFromHtml({ html, pageUrl, websiteUrl }) {
  if (!html || !pageUrl) return null;

  const canonicalUrl =
    canonicalizeWebsiteProductUrl(
      extractCanonicalProductPageUrl(html, pageUrl),
      websiteUrl || pageUrl
    ) || pageUrl;
  if (
    !canonicalUrl ||
    !isHttpUrl(canonicalUrl) ||
    (websiteUrl && !isSameOrSubdomainUrl(canonicalUrl, websiteUrl)) ||
    (websiteUrl && !matchesConfiguredWebsiteMarket(canonicalUrl, websiteUrl)) ||
    isLikelyNonProductUrl(canonicalUrl, websiteUrl || pageUrl) ||
    isLikelyBadDiscoveryPageUrl(canonicalUrl, websiteUrl || pageUrl)
  ) {
    return null;
  }

  const product = findExactPageJsonLdProduct(html, canonicalUrl);
  const productSchemaFound = Boolean(product?.name || product?.offers || product?.image);
  const ecommerceProofFound = hasEcommerceProofText(html);
  const pageClassification = classifyCommercePage({
    html,
    url: canonicalUrl,
    productSchemaFound,
    ecommerceProofFound,
  });
  const purchaseActionDetected = hasDirectProductPurchaseAction(html);

  // v144.39: use the shared commerce classifier as the universal final page
  // proof. This covers schema-less/custom/headless storefronts and nested URL
  // structures without retailer-specific exceptions, while still rejecting
  // search/category/campaign/article/API/listing pages before any image is bound.
  const hasPageBoundProductProof = Boolean(
    pageClassification.pageType === "product" &&
      Number(pageClassification.confidence || 0) >= 78
  );
  const exactProductPageVerified = Boolean(
    hasPageBoundProductProof &&
      (
        productSchemaFound ||
        purchaseActionDetected ||
        isLikelyProductDetailUrl(canonicalUrl) ||
        Number(pageClassification.confidence || 0) >= 88
      )
  );
  const structuredImages = product
    ? getProductImagesFromJsonLd(product, canonicalUrl)
    : [];
  const ogImageRaw = getMetaContent(html, ["og:image", "twitter:image"]);
  const ogImage = ogImageRaw ? resolveUrl(ogImageRaw, canonicalUrl) : null;
  const canUsePageMetadataImage = Boolean(
    product ||
      /\bproduct\b/i.test(getMetaContent(html, ["og:type"])) ||
      isLikelyProductDetailUrl(canonicalUrl) ||
      hasPageBoundProductProof
  );
  const imageUrls = [...structuredImages];
  if (
    canUsePageMetadataImage &&
    ogImage &&
    isHttpUrl(ogImage) &&
    !isBadProductImageUrl(ogImage) &&
    !imageUrls.some(
      (value) =>
        (canonicalProductImageAssetKey(value) || value) ===
        (canonicalProductImageAssetKey(ogImage) || ogImage)
    )
  ) {
    imageUrls.push(ogImage);
  }

  const rawTitle =
    String(product?.name || "").trim() ||
    String(getMetaContent(html, ["og:title", "twitter:title"]) || "").trim() ||
    String(extractPageTitle(html) || "").trim();
  const title = sanitizeProductTitleForCard(rawTitle) || rawTitle;

  // v144.38: Product Engine V2 may already have proven an exact Quickbutik
  // product from this same page via its main gallery even when the page lacks
  // one canonical JSON-LD Product object or product-shaped OG metadata. Reuse
  // that same exact-page gallery evidence instead of contradicting the earlier
  // verification and terminally failing the occurrence. The later semantic
  // image gate still verifies that the chosen pixels depict this exact product.
  if (!imageUrls.length && exactProductPageVerified) {
    const exactPageGalleryImage = extractBestProductImageFromHtml(
      html,
      canonicalUrl,
      title
    );
    if (
      exactPageGalleryImage &&
      isHttpUrl(exactPageGalleryImage) &&
      !isBadProductImageUrl(exactPageGalleryImage)
    ) {
      imageUrls.push(exactPageGalleryImage);
    }
  }

  const primaryImageUrl = imageUrls[0] || "";
  if (!title || !primaryImageUrl) return null;

  const identifier = getStructuredProductIdentifier(product, canonicalUrl);
  const brand = getStructuredProductBrand(product);
  const category = String(
    product?.category || getMetaContent(html, ["product:category", "category"]) || ""
  ).trim();
  const color = String(
    product?.color || getMetaContent(html, ["product:color", "color"]) || ""
  ).trim();
  const description = String(
    product?.description ||
      getMetaContent(html, ["og:description", "description", "twitter:description"]) ||
      ""
  ).trim();
  const availability = inferCurrentProductAvailability({
    product,
    html,
    fallback: "unknown",
  });
  const source = structuredImages.length
    ? "json_ld_main_product_object"
    : ogImage && imageUrls.some((value) =>
        (canonicalProductImageAssetKey(value) || value) ===
        (canonicalProductImageAssetKey(ogImage) || ogImage)
      )
      ? "page_level_product_metadata"
      : "exact_product_page_gallery";

  return {
    title,
    url: canonicalUrl,
    identifier,
    brand,
    category,
    color,
    description,
    availability,
    purchaseActionDetected,
    exactProductPageVerified,
    primaryImageUrl,
    imageUrls: imageUrls.slice(0, 12),
    source,
    fingerprint: buildLockedProductIdentityFingerprint({
      url: canonicalUrl,
      identifier,
      title,
      primaryImageUrl,
    }),
  };
}


function imageUrlMatchesProductIdentity(imageUrl, productUrl, productTitle = "") {
  const imageComparable = normalizeComparableValue(imageUrl);
  const productComparable = normalizeComparableValue(productUrl);
  const titleTokens = String(productTitle || "")
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((token) => token.length >= 4);

  if (!imageComparable) {
    return false;
  }

  const slug = productComparable.split("/").filter(Boolean).at(-1) || "";
  const slugTokens = slug.split(/[^\p{L}\p{N}]+/u).filter((token) => token.length >= 4);

  if (slug && imageComparable.includes(slug)) {
    return true;
  }

  const meaningfulTokens = [...new Set([...slugTokens, ...titleTokens])];
  const matches = meaningfulTokens.filter((token) => imageComparable.includes(token)).length;

  return matches >= Math.min(2, meaningfulTokens.length || 2);
}

function extractBestProductImageFromHtml(html, pageUrl, productTitle = "") {
  // Product.image belongs to the Product entity selected for this exact page.
  // Prefer that explicit relationship before inferring a gallery image from
  // general page markup, which may also contain site-wide brand assets.
  const product = findBestJsonLdProduct(html, pageUrl, productTitle);
  const jsonLdImage = getProductImageFromJsonLd(product, pageUrl);

  if (jsonLdImage) {
    return jsonLdImage;
  }

  // If structured product data is unavailable, gallery placement is stronger
  // evidence than words in a CDN filename. Keep filename matching only as a
  // final conservative fallback for unstructured pages.
  const galleryCandidates = collectProductImageCandidates({
    html,
    pageUrl,
    productTitle,
  }).filter((candidate) => !isBadProductImageUrl(candidate?.url));
  const mainGalleryImage =
    selectMostLikelyMainProductGalleryImage(galleryCandidates);

  if (mainGalleryImage?.url) {
    return mainGalleryImage.url;
  }

  const ogImage = getMetaContent(html, ["og:image", "twitter:image"]);
  const resolvedOgImage = ogImage ? resolveUrl(ogImage, pageUrl) : null;

  if (
    resolvedOgImage &&
    isHttpUrl(resolvedOgImage) &&
    !isBadProductImageUrl(resolvedOgImage)
  ) {
    return resolvedOgImage;
  }

  const imageCandidates = extractImageCandidates(html, pageUrl)
    .filter((image) => image?.url && !isBadProductImageUrl(image.url));

  // Safety rule: never upgrade to a sharper image if we cannot tie it to the same product page.
  // A lower-resolution correct product image is better than a sharp image from a recommended product.
  const matchedImage = imageCandidates.find((image) =>
    imageUrlMatchesProductIdentity(image.url, pageUrl, productTitle)
  );

  return matchedImage?.url || null;
}

async function extractProductDataFromProductPage({
  productUrl,
  websiteUrl,
  webSearchProduct,
  renderProductPage = null,
}) {
  let effectiveProductUrl = productUrl;
  let html = await fetchHtml(productUrl);
  const expectedTitle = sanitizeProductTitleForCard(webSearchProduct?.title || "");
  let product = findBestJsonLdProduct(html, effectiveProductUrl, expectedTitle);
  let productSchemaFound = Boolean(product?.name || product?.offers || product?.image);
  let ecommerceProofFound = hasEcommerceProofText(html);
  let detectedPlatform = detectCommercePlatform({
    html,
    url: effectiveProductUrl,
  });
  const hintedPlatform = String(
    webSearchProduct?.commerce_platform || ""
  ).toLowerCase();
  let commercePlatform =
    detectedPlatform !== "generic"
      ? detectedPlatform
      : hintedPlatform === "magento"
        ? "generic"
        : hintedPlatform || detectedPlatform;
  let pageClassification = classifyCommercePage({
    html,
    url: effectiveProductUrl,
    productSchemaFound,
    ecommerceProofFound,
  });
  let renderedProductPageUsed = false;

  const ambiguousProductCandidate =
    pageClassification.reason === "multiple_product_cards" &&
    (isLikelyProductDetailUrl(effectiveProductUrl) ||
      Boolean(
        expectedTitle &&
          webSearchProduct?.image_url
      ));

  if (
    ambiguousProductCandidate &&
    typeof renderProductPage === "function"
  ) {
    const rendered = await renderProductPage(effectiveProductUrl);
    if (rendered?.html) {
      renderedProductPageUsed = true;
      html = rendered.html;
      effectiveProductUrl = rendered.finalUrl || effectiveProductUrl;
      product = findBestJsonLdProduct(
        html,
        effectiveProductUrl,
        expectedTitle
      );
      productSchemaFound = Boolean(
        product?.name || product?.offers || product?.image
      );
      ecommerceProofFound = hasEcommerceProofText(html);
      detectedPlatform = detectCommercePlatform({
        html,
        url: effectiveProductUrl,
      });
      commercePlatform =
        detectedPlatform !== "generic"
          ? detectedPlatform
          : hintedPlatform === "magento"
            ? "generic"
            : hintedPlatform || detectedPlatform;
      pageClassification = classifyCommercePage({
        html,
        url: effectiveProductUrl,
        productSchemaFound,
        ecommerceProofFound,
      });
      console.log("Product Engine V2 reclassified ambiguous page after rendered verification", {
        productUrl,
        finalUrl: effectiveProductUrl,
        pageType: pageClassification.pageType,
        pageTypeReason: pageClassification.reason,
        platform: commercePlatform,
      });
    }
  }

  if (["category", "campaign", "brand", "search", "article", "internal_api"].includes(pageClassification.pageType)) {
    console.log("Product Engine V2 skipped non-product page", {
      productUrl,
      pageType: pageClassification.pageType,
      pageTypeReason: pageClassification.reason,
      platform: commercePlatform,
    });
    if (
      ambiguousProductCandidate &&
      pageClassification.reason === "multiple_product_cards"
    ) {
      const error = new Error(
        "A product-looking URL remained ambiguous after main-product verification."
      );
      error.code = "ambiguous_product_page";
      error.pageTypeReason = pageClassification.reason;
      throw error;
    }
    return null;
  }

  const rawTitle =
    String(product?.name || "").trim() ||
    String(webSearchProduct?.title || "").trim() ||
    extractPageTitle(html);
  const title = sanitizeProductTitleForCard(rawTitle) || rawTitle;

  const metaDescription = getMetaContent(html, [
    "description",
    "og:description",
    "twitter:description",
  ]);

  const description =
    String(product?.description || "").trim() ||
    String(metaDescription || "").trim() ||
    truncateText(stripHtmlToText(html), 700);
  const productCategory = String(
    product?.category ||
      getMetaContent(html, ["product:category", "category"]) ||
      ""
  ).trim();
  const productTags = collectUniqueTerms(
    [
      ...(Array.isArray(product?.keywords)
        ? product.keywords
        : String(product?.keywords || getMetaContent(html, ["keywords"]) || "").split(/[,;|]/u)),
      productCategory,
    ],
    30
  );
  const purchaseActionDetected = hasDirectProductPurchaseAction(html);
  const currentAvailability = inferCurrentProductAvailability({
    product,
    html,
    fallback:
      webSearchProduct?.availability_status ||
      webSearchProduct?.availability ||
      "unknown",
  });

  const directProductProof =
    productSchemaFound ||
    pageClassification.pageType === "product";
  const productUrlProof = isLikelyProductDetailUrl(effectiveProductUrl);
  const productTitleIdentityProof =
    Boolean(expectedTitle) &&
    haveProductTitlesIdentityAgreement(expectedTitle, title);
  const structuredCommerceProductProof =
    pageClassification.pageType === "product" &&
    productSchemaFound &&
    ecommerceProofFound &&
    Boolean(title);
  const concreteProductProof =
    pageClassification.pageType === "product" &&
    (
      productUrlProof ||
      productTitleIdentityProof ||
      structuredCommerceProductProof ||
      (purchaseActionDetected && Number(pageClassification.confidence || 0) >= 88)
    );
  let imageUrl = extractBestProductImageFromHtml(
    html,
    effectiveProductUrl,
    title
  );
  // v144.47: keep the provenance of the image that Product Engine V2 has
  // already bound to this exact fetched product page. The final product-lock
  // stage must not throw away this proof and then fail simply because a second,
  // stricter HTML parser represents the same storefront differently.
  let productImagePageBound = Boolean(imageUrl);
  let productImagePageBoundSource = imageUrl
    ? "product_engine_exact_page_static"
    : null;
  let productImageSourcePageUrl = imageUrl ? effectiveProductUrl : null;

  // A page can prove that it is a real product while keeping its main gallery
  // behind client-side rendering. In that case render once and trust the
  // gallery structure; opaque CDN filenames do not need to repeat the title.
  if (
    !imageUrl &&
    directProductProof &&
    !renderedProductPageUsed &&
    typeof renderProductPage === "function"
  ) {
    const rendered = await renderProductPage(effectiveProductUrl);
    if (rendered?.html) {
      const renderedProductUrl = rendered.finalUrl || effectiveProductUrl;
      const renderedImageUrl = extractBestProductImageFromHtml(
        rendered.html,
        renderedProductUrl,
        title
      );
      if (renderedImageUrl) {
        imageUrl = renderedImageUrl;
        effectiveProductUrl = renderedProductUrl;
        productImagePageBound = true;
        productImagePageBoundSource = "product_engine_exact_page_rendered";
        productImageSourcePageUrl = renderedProductUrl;
        console.log("Product page main-gallery image recovered after rendered verification", {
          productUrl,
          finalUrl: effectiveProductUrl,
          title,
          imageUrl,
        });
      }
    }
  }

  // Search/listing thumbnails are still a useful last resort once the target
  // page itself has supplied direct product proof. The later resolution pass
  // will replace this with the largest verified gallery asset when available.
  if (
    !imageUrl &&
    webSearchProduct?.image_url &&
    isHttpUrl(webSearchProduct.image_url) &&
    !isBadProductImageUrl(webSearchProduct.image_url) &&
    (concreteProductProof ||
      imageUrlMatchesProductIdentity(
        webSearchProduct.image_url,
        effectiveProductUrl,
        title
      ))
  ) {
    imageUrl = webSearchProduct.image_url;
    const hintedSourcePageUrl = String(
      webSearchProduct?.product_image_source_page_url || ""
    ).trim();
    const hintedSourceMatchesExactPage = Boolean(
      webSearchProduct?.product_image_page_bound === true &&
        hintedSourcePageUrl &&
        normalizeComparableValue(
          canonicalizeWebsiteProductUrl(hintedSourcePageUrl, effectiveProductUrl) ||
            hintedSourcePageUrl
        ) ===
          normalizeComparableValue(
            canonicalizeWebsiteProductUrl(effectiveProductUrl, effectiveProductUrl) ||
              effectiveProductUrl
          )
    );
    productImagePageBound = hintedSourceMatchesExactPage;
    productImagePageBoundSource = hintedSourceMatchesExactPage
      ? String(
          webSearchProduct?.product_image_page_bound_source ||
            "verified_exact_page_hint"
        )
      : "discovery_image_hint";
    productImageSourcePageUrl = hintedSourceMatchesExactPage
      ? hintedSourcePageUrl
      : null;
  }

  const normalizedItem = normalizeWebsiteItem(
    {
      title,
      type: "product",
      url: effectiveProductUrl,
      description,
      image_url: imageUrl,
    },
    websiteUrl
  );

  if (!normalizedItem) {
    return null;
  }

  if (!normalizedItem.image_url) {
    console.log("Product page candidate has no usable image", {
      productUrl,
      title,
    });
  }

  const verifiedProductItem = {
    ...normalizedItem,
    item_key: createItemKey(normalizedItem),
    reason: webSearchProduct?.reason || "",
    source_page_url: webSearchProduct?.source_page_url || null,
    source_search_url: webSearchProduct?.source_search_url || null,
    campaign_fit_source: webSearchProduct?.campaign_fit_source || null,
    campaign_role: webSearchProduct?.campaign_role || null,
    campaign_relevance_class:
      webSearchProduct?.campaign_relevance_class || null,
    campaign_relevance_evidence: Array.isArray(
      webSearchProduct?.campaign_relevance_evidence
    )
      ? webSearchProduct.campaign_relevance_evidence
      : [],
    campaign_research_rank:
      Number(webSearchProduct?.campaign_research_rank || 0) || null,
    ai_campaign_fit_score:
      Number(webSearchProduct?.ai_campaign_fit_score || 0) || null,
    ai_campaign_fit_source:
      webSearchProduct?.ai_campaign_fit_source || null,
    ai_campaign_fit_model:
      webSearchProduct?.ai_campaign_fit_model || null,
    campaign_fit_verdict:
      webSearchProduct?.campaign_fit_verdict || null,
    campaign_theme_fit:
      webSearchProduct?.campaign_theme_fit === true
        ? true
        : webSearchProduct?.campaign_theme_fit === false
          ? false
          : null,
    campaign_primary_web_researched:
      webSearchProduct?.campaign_primary_web_researched === true,
    campaign_final_reviewed:
      webSearchProduct?.campaign_final_reviewed === true,
    discovery_score: Number(webSearchProduct?.discovery_score || webSearchProduct?.score || 0),
    campaign_fit_score: Number(webSearchProduct?.campaign_fit_score || 0),
    product_page_verified: true,
    concrete_product_verified: concreteProductProof,
    product_schema_verified: productSchemaFound,
    ecommerce_proof_found: ecommerceProofFound,
    commerce_platform: commercePlatform,
    category: productCategory,
    tags: productTags,
    availability: currentAvailability,
    availability_status: currentAvailability,
    purchase_action_detected: purchaseActionDetected,
    page_type: pageClassification.pageType === "unknown" ? "product" : pageClassification.pageType,
    page_type_confidence: pageClassification.confidence,
    page_type_reason: pageClassification.reason,
    // v144.47: this is deterministic exact-page evidence, not a semantic AI
    // approval. The final resolver may reuse it only when the source page URL
    // is the same product URL and all concrete-product checks passed.
    product_image_page_bound: Boolean(
      productImagePageBound && concreteProductProof && imageUrl
    ),
    product_image_page_bound_source:
      productImagePageBound && concreteProductProof && imageUrl
        ? productImagePageBoundSource
        : null,
    product_image_source_page_url:
      productImagePageBound && concreteProductProof && imageUrl
        ? productImageSourcePageUrl || effectiveProductUrl
        : null,
    technical_identity_same_page_verified: Boolean(
      productImagePageBound && concreteProductProof && imageUrl
    ),
    last_verified_at: new Date().toISOString(),
  };

  const confidence = getCarouselProductConfidence(verifiedProductItem);

  if (!concreteProductProof || confidence < CAROUSEL_PRODUCT_CONFIDENCE_SOFT_MIN) {
    console.log("Rejected product page candidate because product proof was too weak", {
      productUrl,
      title,
      confidence,
      productSchemaFound,
      ecommerceProofFound,
      productUrlProof,
      productTitleIdentityProof,
      structuredCommerceProductProof,
      pageType: pageClassification.pageType,
      pageTypeReason: pageClassification.reason,
      platform: commercePlatform,
    });
    return null;
  }

  return {
    ...verifiedProductItem,
    product_confidence: confidence,
  };
}

const PRODUCT_PATH_PATTERNS_FOR_RUNTIME = [
  /\/(?:products?|produkt(?:er)?|product-detail|item|artikel)\//i,
  /\/(?:p|pd)\//i,
  /\/collections\/[^/]+\/products\//i,
  /\/[^/?#]+\/[^/?#]+_\d{6,}\/\d{6,}(?:\/|$)/i,
  /\/[^/?#]+-[a-z0-9]*\d[a-z0-9]{4,}-[a-z0-9]*\d[a-z0-9]{1,}\.html(?:\/|$)/i,
];


function getProductUrlFromJsonLd(product, pageUrl) {
  const offers = Array.isArray(product?.offers)
    ? product.offers
    : product?.offers
      ? [product.offers]
      : [];
  const rawUrl =
    product?.url ||
    offers.find((offer) => offer?.url)?.url ||
    product?.mainEntityOfPage?.['@id'] ||
    product?.mainEntityOfPage?.url ||
    "";

  const resolvedUrl = rawUrl ? resolveUrl(String(rawUrl), pageUrl) : null;
  return resolvedUrl && isHttpUrl(resolvedUrl) ? resolvedUrl : null;
}

function extractJsonLdProductCandidatesFromHtml({
  html,
  pageUrl,
  websiteUrl,
  campaignPrompt,
}) {
  const objects = extractJsonLdObjects(html);
  const candidates = [];

  for (const object of objects) {
    if (!normalizeJsonLdType(object?.['@type']).some((type) => type.includes('product'))) {
      continue;
    }

    const title = String(object?.name || "").trim();
    const url = getProductUrlFromJsonLd(object, pageUrl) || pageUrl;
    const imageUrl = getProductImageFromJsonLd(object, pageUrl);
    const description = String(object?.description || "").trim();

    if (!title || !url || !isSameOrSubdomainUrl(url, websiteUrl)) {
      continue;
    }
    if (isLikelyBadDiscoveryPageUrl(url, websiteUrl)) {
      continue;
    }

    candidates.push({
      title,
      url,
      image_url: imageUrl,
      description,
      reason: `Product found in structured data on ${pageUrl}`,
      score: 40 + scorePossibleProductLink({ url, text: title, campaignPrompt }),
    });
  }

  return dedupeUrlItems(candidates);
}

function extractProductUrlCandidatesFromText({
  text,
  pageUrl,
  websiteUrl,
  campaignPrompt,
}) {
  const candidates = [];
  const source = String(text || "");
  const origin = getWebsiteOrigin(websiteUrl);
  const host = getHostnameWithoutWww(websiteUrl);
  const patterns = [
    /https?:\/\/[^"'<>\s]+/gi,
    /["']((?:\/[^"'<>\s]+){1,})["']/g,
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(source)) !== null) {
      const raw = String(match[1] || match[0] || "")
        .replace(/\\u002F/g, "/")
        .replace(/\\\//g, "/")
        .replace(/&amp;/g, "&")
        .trim();

      if (!raw || raw.length > 700) continue;

      const resolvedUrl = raw.startsWith("http")
        ? raw
        : resolveUrl(raw, origin || pageUrl);
      if (!resolvedUrl || !isHttpUrl(resolvedUrl)) continue;
      if (!isSameOrSubdomainUrl(resolvedUrl, websiteUrl)) continue;
      if (isLikelyNonProductUrl(resolvedUrl, websiteUrl)) continue;

      const lower = resolvedUrl.toLowerCase();
      const looksItemLike =
        lower.includes("/p/") ||
        /\/[^/?#]+-p\d{3,}/i.test(lower) ||
        /\/[^/?#]+\d{5,}/i.test(lower);

      if (!looksItemLike && host && !lower.includes(host)) continue;

      candidates.push({
        title: "",
        url: resolvedUrl.split("#")[0],
        reason: `Item-like URL found in embedded page data on ${pageUrl}`,
        score:
          (looksItemLike ? 28 : 6) +
          scorePossibleProductLink({
            url: resolvedUrl,
            text: "",
            campaignPrompt,
          }),
      });
    }
  }

  return dedupeUrlItems(candidates);
}

function extractFocusedCategoryExpansionUrls({ html, pageUrl, categoryUrl }) {
  const urls = [];
  const categoryOrigin = getWebsiteOrigin(categoryUrl);
  let categoryPath = "";

  try {
    categoryPath = new URL(categoryUrl).pathname.replace(/\/$/, "").toLowerCase();
  } catch {
    categoryPath = "";
  }

  for (const link of extractLinks(html, pageUrl)) {
    const url = link?.url;
    if (!url || !isHttpUrl(url) || !isSameOrSubdomainUrl(url, categoryUrl)) continue;

    try {
      const parsed = new URL(url);
      const path = parsed.pathname.replace(/\/$/, "").toLowerCase();
      const text = normalizeSearchText(link?.text || "");
      const isPagination =
        /[?&](?:page|p)=\d+/i.test(parsed.search) ||
        /\/(?:page|sida)\/\d+/i.test(path) ||
        /^(?:next|nästa|nasta|more|visa fler|show more|\d+)$/i.test(text);
      const isChildCategory =
        categoryPath &&
        path.startsWith(`${categoryPath}/`) &&
        !isLikelyBadDiscoveryPageUrl(url, categoryUrl) &&
        !PRODUCT_PATH_PATTERNS_FOR_RUNTIME.some((pattern) => pattern.test(path));

      if (isPagination || isChildCategory) {
        urls.push(url);
      }
    } catch {
      // Ignore malformed links.
    }
  }

  const hasPaginationSignal =
    /rel=["']next["']|class=["'][^"']*pagination|[?&](?:page|p)=\d+|\/(?:page|sida)\/\d+|nästa|nasta|show more|visa fler/i.test(
      String(html || "")
    );

  if (categoryOrigin && hasPaginationSignal) {
    try {
      const current = new URL(pageUrl);
      const currentPage = Number(current.searchParams.get("page") || 1);
      if (currentPage < 4) {
        const next = new URL(current.toString());
        next.searchParams.set("page", String(currentPage + 1));
        urls.push(next.toString());
      }
    } catch {
      // Query-string pagination is only a best-effort fallback.
    }
  }

  return Array.from(new Set(urls));
}


function isMissingProductCandidateQueueError(error) {
  const message = String(error?.message || "");
  return /website_product_candidate_queue|schema cache|does not exist|relation .* does not exist/i.test(message);
}

async function upsertWebsiteProductCandidateQueue({
  supabase,
  rule,
  sourceUrl,
  categoryUrl,
  candidates,
}) {
  if (!supabase || !rule?.user_id || !rule?.brand_profile_id || !Array.isArray(candidates)) return false;
  const nowIso = new Date().toISOString();
  const rows = dedupeProductCandidateQueueRows(
    dedupeUrlItems(candidates)
    .map((candidate) => {
      const productUrl = canonicalizeWebsiteProductUrl(candidate?.url, sourceUrl || categoryUrl);
      if (!productUrl) return null;
      return {
        user_id: rule.user_id,
        brand_profile_id: rule.brand_profile_id,
        automation_rule_id: rule.id || null,
        source_url: sourceUrl || categoryUrl,
        category_url: categoryUrl || candidate?.source_page_url || null,
        product_url: productUrl,
        canonical_product_url: productUrl,
        title: String(candidate?.title || "").trim() || null,
        image_url: candidate?.image_url || null,
        discovery_score: Number(candidate?.score || candidate?.discovery_score || 0),
        status: "pending",
        next_attempt_at: nowIso,
        last_seen_at: nowIso,
        metadata: {
          source_page_url: candidate?.source_page_url || categoryUrl || null,
          campaign_fit_source: candidate?.campaign_fit_source || null,
          commerce_platform: candidate?.commerce_platform || null,
          reason: candidate?.reason || null,
          campaign_role: candidate?.campaign_role || null,
          campaign_relevance_class:
            candidate?.campaign_relevance_class || null,
          campaign_relevance_evidence: Array.isArray(
            candidate?.campaign_relevance_evidence
          )
            ? candidate.campaign_relevance_evidence.slice(0, 8)
            : [],
          campaign_research_rank:
            Number(candidate?.campaign_research_rank || 0) || null,
          ai_campaign_fit_score:
            Number(candidate?.ai_campaign_fit_score || 0) || null,
          campaign_fit_score:
            Number(candidate?.campaign_fit_score || 0) || null,
          campaign_fit_verdict:
            candidate?.campaign_fit_verdict || null,
          campaign_theme_fit:
            candidate?.campaign_theme_fit === true
              ? true
              : candidate?.campaign_theme_fit === false
                ? false
                : null,
          ai_campaign_fit_source:
            candidate?.ai_campaign_fit_source || null,
          ai_campaign_fit_model:
            candidate?.ai_campaign_fit_model || null,
          campaign_primary_web_researched:
            candidate?.campaign_primary_web_researched === true,
          campaign_final_reviewed:
            candidate?.campaign_final_reviewed === true,
        },
      };
    })
    .filter(Boolean)
  ).slice(0, 200);
  if (!rows.length) return false;
  const { error } = await supabase
    .from("website_product_candidate_queue")
    .upsert(rows, {
      onConflict:
        "brand_profile_id,automation_rule_id,canonical_product_url",
    });
  if (error && !isMissingProductCandidateQueueError(error)) {
    console.log("Product candidate queue could not be stored", {
      ruleId: rule.id,
      categoryUrl,
      count: rows.length,
      message: error.message,
    });
  }
  return !error;
}

async function loadWebsiteProductCandidateQueue({ supabase, rule, sourceUrl, categoryUrl, limit = 120 }) {
  if (!supabase || !rule?.brand_profile_id) return [];
  let query = supabase
    .from("website_product_candidate_queue")
    .select("automation_rule_id,product_url,title,image_url,discovery_score,category_url,metadata,status,next_attempt_at")
    .eq("brand_profile_id", rule.brand_profile_id)
    .eq("automation_rule_id", rule.id)
    .in("status", ["pending", "rate_limited"])
    .lte("next_attempt_at", new Date().toISOString())
    .order("discovery_score", { ascending: false })
    .limit(limit);
  if (categoryUrl) query = query.eq("category_url", categoryUrl);
  const { data, error } = await query;
  if (error) {
    if (!isMissingProductCandidateQueueError(error)) {
      console.log("Product candidate queue could not be loaded", {
        ruleId: rule.id,
        categoryUrl,
        message: error.message,
      });
    }
    return [];
  }
  return (data || []).map((row) => ({
    title: row.title || "",
    url: row.product_url,
    image_url: row.image_url || "",
    score: Number(row.discovery_score || 0),
    source_page_url: row.category_url || categoryUrl || sourceUrl || "",
    campaign_fit_source: row?.metadata?.campaign_fit_source || "persistent_candidate_queue",
    commerce_platform: row?.metadata?.commerce_platform || "generic",
    reason: row?.metadata?.reason || "",
    campaign_role: row?.metadata?.campaign_role || null,
    campaign_relevance_class:
      row?.metadata?.campaign_relevance_class || null,
    campaign_relevance_evidence: Array.isArray(
      row?.metadata?.campaign_relevance_evidence
    )
      ? row.metadata.campaign_relevance_evidence
      : [],
    campaign_research_rank:
      Number(row?.metadata?.campaign_research_rank || 0) || null,
    ai_campaign_fit_score:
      Number(row?.metadata?.ai_campaign_fit_score || 0) || null,
    campaign_fit_score:
      Number(row?.metadata?.campaign_fit_score || 0) || null,
    campaign_fit_verdict:
      row?.metadata?.campaign_fit_verdict || null,
    campaign_theme_fit:
      row?.metadata?.campaign_theme_fit === true
        ? true
        : row?.metadata?.campaign_theme_fit === false
          ? false
          : null,
    ai_campaign_fit_source:
      row?.metadata?.ai_campaign_fit_source || null,
    ai_campaign_fit_model:
      row?.metadata?.ai_campaign_fit_model || null,
    campaign_primary_web_researched:
      row?.metadata?.campaign_primary_web_researched === true,
    campaign_final_reviewed:
      row?.metadata?.campaign_final_reviewed === true,
  }));
}

async function updateWebsiteProductCandidateQueueStatus({
  supabase,
  rule,
  productUrls,
  status,
  errorMessage = null,
  nextAttemptAt = null,
}) {
  const urls = Array.from(new Set((productUrls || []).filter(Boolean)));
  if (!supabase || !rule?.brand_profile_id || !urls.length) return;
  const payload = {
    status,
    last_error: errorMessage ? String(errorMessage).slice(0, 1200) : null,
    updated_at: new Date().toISOString(),
  };
  if (nextAttemptAt !== undefined) payload.next_attempt_at = nextAttemptAt;
  if (status === "verified") payload.verified_at = new Date().toISOString();
  const { error } = await supabase
    .from("website_product_candidate_queue")
    .update(payload)
    .eq("brand_profile_id", rule.brand_profile_id)
    .eq("automation_rule_id", rule.id)
    .in("canonical_product_url", urls);
  if (error && !isMissingProductCandidateQueueError(error)) {
    console.log("Product candidate queue status could not be updated", {
      ruleId: rule.id,
      status,
      count: urls.length,
      message: error.message,
    });
  }
}

function isStrongProductCardUrl(value, baseUrl) {
  try {
    const url = new URL(value, baseUrl);
    const path = url.pathname.toLowerCase();
    if (/\/(?:products?|produkt(?:er)?|product-detail|item)\//i.test(path)) return true;
    if (/\.(?:htm|html)$/i.test(path) && path.split("/").filter(Boolean).length >= 2) return true;
    return false;
  } catch {
    return false;
  }
}

function getFocusedCategoryCandidatePriority(candidate, categoryUrl) {
  try {
    const url = new URL(candidate?.url || "", categoryUrl);
    const path = url.pathname.toLowerCase();

    if (/\/(?:products?|produkt(?:er)?|product-detail|item)\//i.test(path)) {
      return 4;
    }

    if (/\/(?:p|pd)\//i.test(path)) {
      return 3;
    }

    if (
      isStrongProductCardUrl(url.toString(), categoryUrl) &&
      candidate?.title &&
      candidate?.image_url &&
      !isLikelyBadDiscoveryPageUrl(url.toString(), categoryUrl)
    ) {
      return 2;
    }

    if (
      candidate?.title &&
      candidate?.image_url &&
      !isLikelyBadDiscoveryPageUrl(url.toString(), categoryUrl)
    ) {
      return 1;
    }
  } catch {
    // Weak or malformed links stay at the end of the verification queue.
  }

  return 0;
}

function rankFocusedCategoryCandidatesForVerification(candidates, categoryUrl) {
  return dedupeUrlItems(candidates || [])
    .map((candidate, originalIndex) => ({
      candidate,
      originalIndex,
      productUrlPriority: getFocusedCategoryCandidatePriority(candidate, categoryUrl),
      discoveryScore: Number(candidate?.score || 0),
    }))
    .sort((a, b) => {
      if (a.productUrlPriority !== b.productUrlPriority) {
        return b.productUrlPriority - a.productUrlPriority;
      }
      if (a.discoveryScore !== b.discoveryScore) {
        return b.discoveryScore - a.discoveryScore;
      }
      return a.originalIndex - b.originalIndex;
    })
    .map((entry) => entry.candidate);
}

function buildTrustedCategoryCardProducts(candidates, categoryUrl, limit = 12) {
  return dedupeUrlItems(candidates || [])
    .filter((candidate) =>
      candidate?.title && candidate?.url && candidate?.image_url &&
      isStrongProductCardUrl(candidate.url, categoryUrl) &&
      !isLikelyBadDiscoveryPageUrl(candidate.url, categoryUrl)
    )
    .map((candidate) => {
      const normalized = normalizeWebsiteItem(candidate, categoryUrl);
      if (!normalized || !isValidCarouselProduct(normalized)) return null;
      return {
        ...candidate,
        ...normalized,
        page_type: "product",
        page_type_confidence: Math.max(72, Number(candidate?.page_type_confidence || 0)),
        page_type_reason: "trusted_category_product_card",
        verification_level: "category_card",
        product_confidence: Math.max(62, Number(candidate?.product_confidence || 0)),
        campaign_fit_source: candidate?.campaign_fit_source || "trusted_category_product_card",
        automation_search_method: candidate?.automation_search_method || "trusted_category_product_card",
        selection_priority: Math.max(180, Number(candidate?.selection_priority || 0)),
        last_verified_at: null,
      };
    })
    .filter(Boolean)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, limit);
}

async function discoverProductsFromFocusedCategory({
  supabase = null,
  categoryUrl,
  rule,
  limit = WEBSITE_PRODUCT_DISCOVERY_VERIFY_LIMIT,
  diagnostics = null,
  deadlineMs = Date.now() + WEBSITE_VERIFICATION_SOFT_DEADLINE_MS,
  excludeProductUrls = [],
  verificationCache = null,
}) {
  const knownDomainState = await getWebsiteDomainFetchState(categoryUrl).catch(() => null);
  if (isWebsiteAccessProtectedState(knownDomainState)) {
    console.info("Focused category direct crawl skipped for known protected website", {
      ruleId: rule?.id || null,
      categoryUrl,
    });
    return [];
  }

  const campaignPrompt = buildCampaignResearchText(rule);
  const requestedProductScale = Math.max(
    1,
    Math.min(CAROUSEL_PRODUCT_SLIDE_TARGET, Number(limit) || 1)
  );
  const targets = getAdaptiveProductPoolTargets(requestedProductScale);
  const focusedCandidateTarget = Math.max(
    12,
    Math.min(60, Math.max(Number(limit || 0) * 3, requestedProductScale * 6))
  );
  const singleProductFocusedDiscovery = Number(limit || 0) <= 8;
  const productVerificationReserveMs = singleProductFocusedDiscovery ? 42_000 : 35_000;
  const pageQueue = [categoryUrl];
  const visitedPages = new Set();
  const candidates = [];
  let detectedPlatform = "generic";
  let rateLimited = false;
  let rateLimitRetryAfterMs = 0;
  const excludedProductUrls = new Set(
    (excludeProductUrls || [])
      .map((value) => canonicalizeWebsiteProductUrl(value, categoryUrl))
      .filter(Boolean)
      .map(normalizeComparableValue)
  );

  while (
    pageQueue.length &&
    visitedPages.size < 8 &&
    candidates.length < focusedCandidateTarget &&
    Date.now() < deadlineMs - productVerificationReserveMs
  ) {
    const pageUrl = pageQueue.shift();
    const comparable = normalizeComparableValue(pageUrl);
    if (!pageUrl || visitedPages.has(comparable)) continue;
    visitedPages.add(comparable);

    try {
      const html = await fetchHtml(pageUrl);
      detectedPlatform = detectCommercePlatform({ html, url: pageUrl }) || detectedPlatform;
      const cardCandidates = extractProductCardCandidatesFromHtml({
        html,
        pageUrl,
        websiteUrl: categoryUrl,
        campaignPrompt,
      });
      const jsonLdCandidates = extractJsonLdProductCandidatesFromHtml({
        html,
        pageUrl,
        websiteUrl: categoryUrl,
      });
      const linkCandidates = extractProductLinksFromDiscoveryPage({
        html,
        pageUrl,
        websiteUrl: categoryUrl,
        campaignPrompt,
      });

      candidates.push(
        ...[...cardCandidates, ...jsonLdCandidates, ...linkCandidates].map((item) => ({
          ...item,
          commerce_platform: detectedPlatform,
          source_page_url: item.source_page_url || pageUrl,
        }))
      );

      const expansionUrls = extractFocusedCategoryExpansionUrls({
        html,
        pageUrl,
        categoryUrl,
      });
      for (const expansionUrl of expansionUrls) {
        if (!visitedPages.has(normalizeComparableValue(expansionUrl))) {
          pageQueue.push(expansionUrl);
        }
      }
    } catch (error) {
      if (isWebsiteRateLimitError(error)) {
        rateLimited = true;
        rateLimitRetryAfterMs = Math.max(rateLimitRetryAfterMs, Number(error.retryAfterMs || 0));
        console.log("Focused category discovery paused by website rate limit", {
          categoryUrl,
          pageUrl,
          retryAfterMs: rateLimitRetryAfterMs,
        });
        break;
      }
      console.log("Focused category page unavailable during Product Engine V2 discovery", {
        categoryUrl,
        pageUrl,
        message: error.message,
      });
    }
  }

  const queuedCandidates = await loadWebsiteProductCandidateQueue({
    supabase,
    rule,
    sourceUrl: categoryUrl,
    categoryUrl,
    limit: Math.max(80, targets.minimumCandidatePool * 3),
  });

  let dedupedCandidates = rankFocusedCategoryCandidatesForVerification(
    [...candidates, ...queuedCandidates],
    categoryUrl
  )
    .filter((candidate) => {
      const canonicalUrl = canonicalizeWebsiteProductUrl(candidate?.url, categoryUrl);
      return !canonicalUrl || !excludedProductUrls.has(normalizeComparableValue(canonicalUrl));
    })
    .slice(0, Math.max(limit * 6, targets.minimumCandidatePool * 4, 180));

  const focusedMinimumBeforeBroadFallback = Math.max(
    12,
    Math.min(targets.minimumCandidatePool, Math.max(Number(limit || 0) * 2, requestedProductScale * 4))
  );
  if (!rateLimited && dedupedCandidates.length < focusedMinimumBeforeBroadFallback && Date.now() < deadlineMs - 60_000) {
    try {
      const broaderCandidates = await discoverProductCandidatesFromWebsite({
        websiteUrl: categoryUrl,
        campaignPrompt,
        usedItems: [],
        fastCampaignContinuation: false,
        excludeUsed: false,
        supabase,
        rule,
      });
      dedupedCandidates = rankFocusedCategoryCandidatesForVerification(
        [...dedupedCandidates, ...broaderCandidates],
        categoryUrl
      )
        .filter((candidate) => {
          const canonicalUrl = canonicalizeWebsiteProductUrl(candidate?.url, categoryUrl);
          return !canonicalUrl || !excludedProductUrls.has(normalizeComparableValue(canonicalUrl));
        })
        .slice(0, Math.max(limit * 6, targets.minimumCandidatePool * 4, 180));
    } catch (error) {
      if (isWebsiteRateLimitError(error)) {
        rateLimited = true;
        rateLimitRetryAfterMs = Math.max(rateLimitRetryAfterMs, Number(error.retryAfterMs || 0));
      } else {
        throw error;
      }
    }
  }

  await upsertWebsiteProductCandidateQueue({
    supabase,
    rule,
    sourceUrl: categoryUrl,
    categoryUrl,
    candidates: dedupedCandidates,
  });

  const requestedVerifiedCount = singleProductFocusedDiscovery
    ? 1
    : Math.min(
        24,
        Math.max(
          CAROUSEL_PRODUCT_SLIDE_TARGET + 3,
          targets.minimumVerifiedPool,
          Number(limit) || 0
        )
      );
  const verified = await verifyDiscoveredWebsiteProductCandidates({
    candidates: dedupedCandidates,
    websiteUrl: categoryUrl,
    limit: requestedVerifiedCount,
    diagnostics,
    supabase,
    rule,
    deadlineMs,
    verificationCache,
  });

  rateLimited = rateLimited || Boolean(verified.rateLimited);
  rateLimitRetryAfterMs = Math.max(
    rateLimitRetryAfterMs,
    Number(verified.retryAfterMs || 0)
  );

  const trustedCards = buildTrustedCategoryCardProducts(
    dedupedCandidates,
    categoryUrl,
    Math.max(CAROUSEL_PRODUCT_SLIDE_TARGET + CAROUSEL_PRODUCT_RESERVE_TARGET, 10)
  );
  const result = dedupeWebsiteItemsByUrlTitleAndImage([
    ...verified.map((item) => ({ ...item, selection_priority: Math.max(320, Number(item?.selection_priority || 0)) })),
    ...trustedCards,
  ]).slice(0, Math.max(limit, CAROUSEL_PRODUCT_SLIDE_TARGET + CAROUSEL_PRODUCT_RESERVE_TARGET));

  result.rateLimited = rateLimited;
  result.retryAfterMs = rateLimitRetryAfterMs;
  result.pendingCandidateCount = Math.max(0, dedupedCandidates.length - verified.length);

  console.log("Product Engine V2 focused category discovery finished", {
    categoryUrl,
    platform: detectedPlatform,
    visitedPageCount: visitedPages.size,
    candidateCount: dedupedCandidates.length,
    deeplyVerifiedCount: verified.length,
    trustedCategoryCardCount: trustedCards.length,
    usableProductCount: result.length,
    rateLimited,
    requiredCount: CAROUSEL_PRODUCT_SLIDE_TARGET,
    reserveTarget: CAROUSEL_PRODUCT_RESERVE_TARGET,
    excludedPreviouslyVerifiedCount: excludedProductUrls.size,
  });

  return result;
}

function isLikelyBadDiscoveryPageUrl(value, websiteUrl) {
  if (isBadProductUrl(value)) {
    return true;
  }

  try {
    const url = new URL(value);
    const path = url.pathname.toLowerCase();

    if (!path || path === "/" || isWeakItemUrl(value, websiteUrl)) {
      return true;
    }

    const hasProductPath =
      /\/products?\//i.test(path) ||
      /\/produkt(er)?\//i.test(path) ||
      /\/p\//i.test(path) ||
      /\/[^/?#]+-p\d{3,}/i.test(path);

    const listingPathParts = [
      "/collections",
      "/collection",
      "/category",
      "/categories",
      "/kategori",
      "/kategorier",
      "/catalog",
      "/katalog",
      "/brand",
      "/brands",
      "/varumarke",
      "/varumarken",
      "/tag",
      "/tags",
    ];

    if (!hasProductPath && listingPathParts.some((part) => path.includes(part))) {
      return true;
    }

    const blockedPathParts = [
      "/blog",
      "/news",
      "/nyheter",
      "/article",
      "/artiklar",
      "/cart",
      "/checkout",
      "/kundvagn",
      "/kassa",
      "/account",
      "/login",
      "/sign-in",
      "/privacy",
      "/integritet",
      "/cookie",
      "/terms",
      "/villkor",
      "/contact",
      "/kontakt",
      "/about",
      "/om-oss",
      "/search",
      "/sok",
      "/sök",
      "/kundservice",
      "/faq",
    ];

    return blockedPathParts.some((part) => path.includes(part));
  } catch {
    return true;
  }
}

function isLikelyInvalidDiscoveryResearchUrl(value, websiteUrl) {
  try {
    const url = new URL(value);
    const path = url.pathname.toLowerCase();

    if (!path || path === "/" || isWeakItemUrl(value, websiteUrl)) {
      return true;
    }

    const blockedPathParts = [
      "/blog",
      "/news",
      "/nyheter",
      "/article",
      "/artiklar",
      "/cart",
      "/checkout",
      "/kundvagn",
      "/kassa",
      "/account",
      "/login",
      "/sign-in",
      "/privacy",
      "/integritet",
      "/cookie",
      "/terms",
      "/villkor",
      "/contact",
      "/kontakt",
      "/about",
      "/om-oss",
      "/kundservice",
      "/faq",
    ];

    return blockedPathParts.some((part) => path.includes(part));
  } catch {
    return true;
  }
}

function dedupeUrlItems(items) {
  const seen = new Set();
  const result = [];

  for (const item of items || []) {
    const normalizedUrl = normalizeComparableValue(item?.url);

    if (!normalizedUrl || seen.has(normalizedUrl)) {
      continue;
    }

    seen.add(normalizedUrl);
    result.push(item);
  }

  return result;
}

function scorePossibleProductLink({ url, text, campaignPrompt }) {
  let score = 0;

  try {
    const parsedUrl = new URL(url);
    const pathSegments = parsedUrl.pathname.split("/").filter(Boolean);

    // Language-neutral link scoring. Product relevance is handled by structured
    // website data and AI research, not by Swedish/English keyword lists.
    if (pathSegments.length >= 1 && pathSegments.length <= 5) {
      score += 8;
    }

    if (pathSegments.length > 6) {
      score -= 6;
    }

    if (parsedUrl.search) {
      score -= 2;
    }
  } catch {
    score -= 10;
  }

  if (text && String(text).trim().length >= 4) {
    score += 4;
  }

  const terms = extractCampaignTerms({ prompt: campaignPrompt });
  if (terms.length) {
    const haystack = normalizeSearchText(`${url || ""} ${text || ""}`);
    for (const term of terms) {
      if (haystack.includes(term)) {
        score += 35;
      }
    }
  }

  return score;
}

function extractProductLinksFromDiscoveryPage({
  html,
  pageUrl,
  websiteUrl,
  campaignPrompt,
}) {
  const links = extractLinks(html, pageUrl);
  const candidates = [];

  candidates.push(
    ...extractProductCardCandidatesFromHtml({
      html,
      pageUrl,
      websiteUrl,
      campaignPrompt,
    })
  );

  candidates.push(
    ...extractJsonLdProductCandidatesFromHtml({
      html,
      pageUrl,
      websiteUrl,
      campaignPrompt,
    })
  );

  candidates.push(
    ...extractProductUrlCandidatesFromText({
      text: html,
      pageUrl,
      websiteUrl,
      campaignPrompt,
    })
  );

  for (const link of links) {
    const url = link?.url;

    if (!url || !isHttpUrl(url)) {
      continue;
    }

    if (!isSameOrSubdomainUrl(url, websiteUrl)) {
      continue;
    }

    if (isLikelyNonProductUrl(url, websiteUrl)) {
      continue;
    }

    if (isLikelyBadDiscoveryPageUrl(url, websiteUrl)) {
      continue;
    }

    const score = scorePossibleProductLink({
      url,
      text: link.text || "",
      campaignPrompt,
    });

    if (score < 0) {
      continue;
    }

    candidates.push({
      title: link.text || "",
      url,
      reason: `Product link found on discovery page: ${pageUrl}`,
      score,
      source_page_url: pageUrl,
      campaign_fit_source: "discovery_page_link",
    });
  }

  return dedupeUrlItems(candidates)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 180);
}

async function findProductCandidatesFromDiscoveryPages({
  discoveryPages,
  websiteUrl,
  campaignPrompt,
}) {
  const candidates = [];

  for (const page of discoveryPages || []) {
    try {
      const html = await fetchHtml(page.url);

      const pageCandidates = extractProductLinksFromDiscoveryPage({
        html,
        pageUrl: page.url,
        websiteUrl,
        campaignPrompt,
      });

      candidates.push(...pageCandidates);
    } catch (error) {
      if (isWebsiteRateLimitError(error)) {
        throw error;
      }
      const discoveryLogPayload = {
        discoveryPageUrl: page.url,
        message: error.message,
      };
      if (isWebsiteSecurityBlockedError(error)) {
        console.info("Protected retailer direct discovery fetch blocked; continuing with allowed fallback", discoveryLogPayload);
      } else {
        console.error("Could not fetch discovery page for product links", discoveryLogPayload);
      }
    }
  }

  return dedupeUrlItems(candidates)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 60);
}

function sortFreshProductCandidatesFirst(candidates, usedWebsiteItems, websiteUrl) {
  const rows = (candidates || []).map((item, index) => ({
    item,
    index,
    wasUsedRecently: hasWebsiteItemAlreadyBeenUsed(item, usedWebsiteItems || [], websiteUrl),
  }));

  return rows
    .sort((a, b) => {
      if (a.wasUsedRecently !== b.wasUsedRecently) {
        return a.wasUsedRecently ? 1 : -1;
      }

      const scoreDelta = Number(b.item?.score || 0) - Number(a.item?.score || 0);
      if (scoreDelta !== 0) {
        return scoreDelta;
      }

      return a.index - b.index;
    })
    .map((entry) => entry.item);
}

function getWebsiteOrigin(websiteUrl) {
  try {
    const url = new URL(websiteUrl);
    return `${url.protocol}//${url.hostname}`;
  } catch {
    return "";
  }
}

function makeSearchSlug(value) {
  return normalizeSearchText(value)
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

const weakShortSearchRoots = new Set([
  "and",
  "att",
  "den",
  "det",
  "dit",
  "din",
  "for",
  "med",
  "och",
  "per",
  "pre",
  "pro",
  "the",
  "til",
  "till",
]);

function addCampaignSearchVariants(searches, value) {
  const query = normalizeStoreSearchQueries([value], 1)[0];

  if (query) {
    searches.push(query);
  }
}

function extractDedicatedStoreSearchQueries(campaignPrompt) {
  return normalizeStoreSearchQueries(
    splitCampaignTermLine(
      extractPromptLineValue(campaignPrompt, "Product search queries")
    ),
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
}

function buildCampaignDiscoverySearches(campaignPrompt) {
  const rule = { prompt: campaignPrompt };
  const dedicatedQueries = extractDedicatedStoreSearchQueries(campaignPrompt);
  const explicitTerms = normalizeStoreSearchQueries(
    extractExplicitCampaignMatchTerms(rule),
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
  const coreThemeTerms = normalizeStoreSearchQueries(
    extractCampaignCoreThemeTerms(rule),
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
  const searches = [];

  // Product/category phrases made for the retailer's search box come first.
  // A broad occasion word is useful as a fallback, but must not consume the
  // limited query budget before concrete searches such as "party dress".
  for (const query of dedicatedQueries) {
    addCampaignSearchVariants(searches, query);
  }

  for (const term of explicitTerms) {
    addCampaignSearchVariants(searches, term);
  }

  for (const term of coreThemeTerms) {
    addCampaignSearchVariants(searches, term);
  }

  return Array.from(new Set(searches.filter(Boolean))).slice(
    0,
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT
  );
}

function buildLikelyDiscoveryUrls(websiteUrl, campaignPrompt = "", platform = "generic") {
  const origin = getWebsiteOrigin(websiteUrl);
  const discoveryBase = getWebsiteSearchBaseUrls(websiteUrl)[0] || origin;
  const urls = [];

  if (websiteUrl && isHttpUrl(websiteUrl)) {
    urls.push(websiteUrl);
  }

  if (!origin) {
    return Array.from(new Set(urls));
  }

  const normalizedPlatform = String(platform || "generic").toLowerCase();
  const campaignSearches = buildCampaignDiscoverySearches(campaignPrompt);

  if (normalizedPlatform === "shopify") {
    for (const search of campaignSearches) {
      const searchSlug = makeSearchSlug(search);
      const encoded = encodeURIComponent(search.replace(/-/g, " "));
      urls.push(
        `${discoveryBase}/collections/${searchSlug}`,
        `${discoveryBase}/collections/${searchSlug}/products.json?limit=250`,
        `${discoveryBase}/search?q=${encoded}`,
        `${discoveryBase}/search?type=product&q=${encoded}`,
        `${discoveryBase}/collections/all/${searchSlug}`
      );
    }

    urls.push(`${discoveryBase}/collections/all`, `${discoveryBase}/products`);
  } else if (normalizedPlatform === "woocommerce") {
    for (const search of campaignSearches) {
      const encoded = encodeURIComponent(search.replace(/-/g, " "));
      urls.push(
        `${discoveryBase}/?s=${encoded}&post_type=product`,
        `${discoveryBase}/product-category/${makeSearchSlug(search)}`
      );
    }
    urls.push(`${discoveryBase}/shop`, `${discoveryBase}/product`);
  } else if (normalizedPlatform === "magento") {
    for (const search of campaignSearches) {
      const encoded = encodeURIComponent(search.replace(/-/g, " "));
      urls.push(`${discoveryBase}/catalogsearch/result/?q=${encoded}`);
    }
  } else if (normalizedPlatform !== "quickbutik") {
    // Generic fallback paths are deliberately conservative. Platform-specific
    // paths are never tried until the platform has been positively detected.
    urls.push(`${discoveryBase}/products`, `${discoveryBase}/produkter`, `${discoveryBase}/shop`, `${discoveryBase}/butik`);
  }

  urls.push(
    `${origin}/sitemap.xml`,
    `${origin}/sitemap_index.xml`,
    `${origin}/sitemap-products.xml`,
    `${origin}/sitemap_products_1.xml`,
    `${origin}/product-sitemap.xml`,
    `${origin}/products-sitemap.xml`
  );

  return Array.from(new Set(urls));
}

function buildStoreSearchQueries(campaignPrompt) {
  const searches = buildCampaignDiscoverySearches(campaignPrompt)
    .map((search) => String(search || "").trim())
    .filter(Boolean);

  return Array.from(new Set(searches)).slice(0, CAMPAIGN_STORE_SEARCH_QUERY_LIMIT);
}

function getWebsiteSearchBaseUrls(websiteUrl) {
  const origin = getWebsiteOrigin(websiteUrl);
  if (!origin) return [];

  let parsed;
  try {
    parsed = new URL(String(websiteUrl || ""));
  } catch {
    return [origin];
  }

  const localeSegments = [];
  for (const segment of String(parsed.pathname || "").split("/").filter(Boolean)) {
    if (
      localeSegments.length >= 2 ||
      !/^[a-z]{2}(?:-[a-z]{2})?$/i.test(segment)
    ) {
      break;
    }
    localeSegments.push(segment);
  }

  const localizedBase = localeSegments.length
    ? `${origin}/${localeSegments.join("/")}`
    : "";

  // A saved locale path is a market boundary, not merely a search hint.
  // Do not also probe the bare origin because multilingual Shopify stores often
  // expose sibling country/language catalogs there (for example /sv-se and /da-dk).
  return localizedBase ? [localizedBase] : [origin];
}

function buildStoreSearchUrls(websiteUrl, campaignPrompt = "", platform = "generic") {
  const origin = getWebsiteOrigin(websiteUrl);
  const searchBases = getWebsiteSearchBaseUrls(websiteUrl);
  const queries = buildStoreSearchQueries(campaignPrompt);
  const urls = [];

  if (!origin || !searchBases.length || !queries.length) {
    return [];
  }

  const normalizedPlatform = String(platform || "generic").toLowerCase();
  const queryParts = queries.map((query) => {
    const queryText = query.replace(/-/g, " ");
    const encoded = encodeURIComponent(queryText);
    const slug = encodeURIComponent(query);

    return { query, encoded, slug };
  });

  if (normalizedPlatform === "shopify") {
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/search?type=product&q=${encoded}`);
      }
    }
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/search?q=${encoded}`);
      }
    }
    for (const { encoded, slug } of queryParts) {
      for (const base of searchBases) {
        urls.push(
          `${base}/search?options[prefix]=last&q=${encoded}`,
          `${base}/collections/all?constraint=${slug}`
        );
      }
    }
  } else if (normalizedPlatform === "woocommerce") {
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/?s=${encoded}&post_type=product`);
      }
    }
  } else if (normalizedPlatform === "magento") {
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/catalogsearch/result/?q=${encoded}`);
      }
    }
  } else if (normalizedPlatform === "prestashop") {
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/search?controller=search&s=${encoded}`);
      }
    }
  } else if (normalizedPlatform !== "quickbutik") {
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/search?q=${encoded}`);
      }
    }
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/search?query=${encoded}`);
      }
    }
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/sok?q=${encoded}`);
      }
    }
    for (const { encoded } of queryParts) {
      for (const base of searchBases) {
        urls.push(`${base}/s%C3%B6k?q=${encoded}`);
      }
    }
  }

  return Array.from(new Set(urls)).slice(0, WEBSITE_STORE_SEARCH_FETCH_LIMIT);
}

function extractSearchFormUrlsFromHtml({
  html,
  pageUrl,
  campaignPrompt,
}) {
  const queries = buildStoreSearchQueries(campaignPrompt).slice(0, CAMPAIGN_SEARCH_FORM_QUERY_LIMIT);

  if (!queries.length) {
    return [];
  }

  const urls = [];
  const formRegex = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
  let match;

  while ((match = formRegex.exec(String(html || ""))) !== null) {
    const openTag = match[1] || "";
    const body = match[2] || "";
    const formHtml = `${openTag} ${body}`;
    const normalizedForm = normalizeSearchText(formHtml);
    const method = String(getAttributeValueFromTag(openTag, "method") || "get").toLowerCase();

    if (method && method !== "get") {
      continue;
    }

    const looksLikeSearchForm =
      normalizedForm.includes("search") ||
      normalizedForm.includes("sok") ||
      /type=["']search["']/i.test(formHtml);

    if (!looksLikeSearchForm) {
      continue;
    }

    const action = getAttributeValueFromTag(openTag, "action") || pageUrl;
    const actionUrl = resolveUrl(action, pageUrl) || pageUrl;
    const inputRegex = /<input\b[^>]*>/gi;
    const hiddenParams = [];
    const queryNames = [];
    let inputMatch;

    while ((inputMatch = inputRegex.exec(body)) !== null) {
      const inputTag = inputMatch[0] || "";
      const inputType = String(getAttributeValueFromTag(inputTag, "type") || "text").toLowerCase();
      const inputName = String(getAttributeValueFromTag(inputTag, "name") || "").trim();

      if (!inputName) {
        continue;
      }

      if (inputType === "hidden") {
        hiddenParams.push([
          inputName,
          getAttributeValueFromTag(inputTag, "value") || "",
        ]);
        continue;
      }

      if (
        inputType === "search" ||
        ["q", "query", "s", "search", "keyword", "keywords", "search_query", "term"].includes(inputName.toLowerCase())
      ) {
        queryNames.push(inputName);
      }
    }

    const queryName = queryNames[0] || "q";

    for (const query of queries) {
      try {
        const url = new URL(actionUrl);
        for (const [name, value] of hiddenParams) {
          if (name && !url.searchParams.has(name)) {
            url.searchParams.set(name, value);
          }
        }
        url.searchParams.set(queryName, query.replace(/-/g, " "));
        urls.push(url.toString());
      } catch {
        // Ignore malformed form actions.
      }
    }
  }

  return Array.from(new Set(urls)).slice(0, WEBSITE_STORE_SEARCH_FETCH_LIMIT);
}

function getStoreSearchQueryFromUrl(value) {
  try {
    const url = new URL(value);
    const queryKeys = [
      "q",
      "query",
      "s",
      "search",
      "keyword",
      "keywords",
      "search_query",
      "term",
      "constraint",
    ];

    for (const key of queryKeys) {
      const raw = url.searchParams.get(key);
      const normalized = normalizeSearchText(raw || "").replace(/[-_]+/g, " ").replace(/\s+/g, " ").trim();
      if (normalized) return normalized;
    }
  } catch {
    // Ignore malformed search URLs.
  }

  return "";
}

function normalizeStoreSearchProductSuggestion(product, origin, campaignPrompt) {
  const title = String(product?.title || product?.name || product?.product_title || "").trim();
  const rawUrl =
    product?.url ||
    product?.product_url ||
    (product?.handle ? `/products/${product.handle}` : "") ||
    "";
  const productUrl = rawUrl ? resolveUrl(rawUrl, origin) : "";
  const rawImage =
    product?.featured_image?.url ||
    product?.featured_image ||
    product?.image?.url ||
    product?.image ||
    product?.images?.[0]?.url ||
    product?.images?.[0] ||
    "";
  const imageUrl = rawImage ? resolveUrl(String(rawImage), origin) : "";

  if (!title || !productUrl || !isHttpUrl(productUrl)) {
    return null;
  }

  return {
    title,
    url: productUrl,
    image_url: imageUrl && isHttpUrl(imageUrl) ? imageUrl : null,
    description: String(product?.body || product?.body_html || product?.description || ""),
    reason: "Product found from store search suggestions",
    score: 105 + scorePossibleProductLink({ url: productUrl, text: title, campaignPrompt }),
    campaign_fit_source: "store_search_suggest",
  };
}

async function discoverShopifySearchSuggest({
  websiteUrl,
  campaignPrompt,
}) {
  const origin = getWebsiteOrigin(websiteUrl);
  const queries = buildStoreSearchQueries(campaignPrompt).slice(0, 6);
  const discovered = [];

  if (!origin || !queries.length) {
    return [];
  }

  for (const query of queries) {
    const encoded = encodeURIComponent(query.replace(/-/g, " "));
    const suggestUrl = `${origin}/search/suggest.json?q=${encoded}&resources[type]=product&resources[limit]=10`;

    try {
      const json = await fetchJson(suggestUrl);
      const products = Array.isArray(json?.resources?.results?.products)
        ? json.resources.results.products
        : [];

      for (const product of products) {
        const normalized = normalizeStoreSearchProductSuggestion(product, origin, campaignPrompt);
        if (normalized && !isLikelyNonProductUrl(normalized.url, websiteUrl)) {
          discovered.push({
            ...normalized,
            source_page_url: suggestUrl,
            source_search_url: suggestUrl,
            found_by_query: normalizeSearchText(query),
          });
        }
      }
    } catch (error) {
      console.log("Store search suggestion endpoint unavailable", {
        websiteUrl,
        query,
        message: error.message,
      });
    }
  }

  return dedupeUrlItems(discovered)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, WEBSITE_STORE_SEARCH_VERIFY_LIMIT);
}

function selectBalancedStoreSearchCandidates(
  candidates,
  limit,
  {
    rule = null,
    usedComparable = new Set(),
    excludeUsed = false,
  } = {}
) {
  const eligibleCandidates = dedupeUrlItems(candidates)
    .filter(
      (item) =>
        !excludeUsed ||
        !usedComparable.has(normalizeComparableValue(item?.url))
    )
    .map((item) => ({
      ...item,
      campaign_text_evidence_count: rule
        ? countCampaignCoreThemeTermMatches(item, rule)
        : 0,
    }));
  const groupedByQuery = new Map();

  for (const candidate of eligibleCandidates) {
    const query =
      normalizeSearchText(
        candidate?.found_by_query ||
          getStoreSearchQueryFromUrl(candidate?.source_search_url) ||
          candidate?.source_search_url ||
          "unattributed"
      ).trim() || "unattributed";
    const group = groupedByQuery.get(query) || [];
    group.push(candidate);
    groupedByQuery.set(query, group);
  }

  const selected = [];
  const seenUrls = new Set();
  const queryGroups = Array.from(groupedByQuery.values())
    .map((group) =>
      dedupeUrlItems(group).sort((a, b) => {
        const evidenceDelta =
          Number(b.campaign_text_evidence_count || 0) -
          Number(a.campaign_text_evidence_count || 0);
        if (evidenceDelta !== 0) return evidenceDelta;
        return Number(b.score || 0) - Number(a.score || 0);
      })
    );
  const perQueryTarget = Math.max(
    6,
    Math.ceil(Math.max(1, limit) / Math.max(1, queryGroups.length))
  );

  for (let round = 0; round < perQueryTarget; round += 1) {
    for (const group of queryGroups) {
      const candidate = group[round];
      if (!candidate) continue;
      const key = normalizeComparableValue(
        canonicalizeWebsiteProductUrl(candidate?.url, candidate?.source_search_url) ||
          candidate?.url
      );
      if (!key || seenUrls.has(key)) continue;
      seenUrls.add(key);
      selected.push(candidate);
      if (selected.length >= limit) return selected;
    }
  }

  for (const candidate of eligibleCandidates.sort((a, b) => {
    const evidenceDelta =
      Number(b.campaign_text_evidence_count || 0) -
      Number(a.campaign_text_evidence_count || 0);
    if (evidenceDelta !== 0) return evidenceDelta;
    return Number(b.score || 0) - Number(a.score || 0);
  })) {
    const key = normalizeComparableValue(candidate?.url);
    if (!key || seenUrls.has(key)) continue;
    seenUrls.add(key);
    selected.push(candidate);
    if (selected.length >= limit) break;
  }

  return selected;
}

function selectStoreSearchUrlsForFetch(urls, limit) {
  const uniqueUrls = Array.from(new Set((urls || []).filter(Boolean)));
  const grouped = new Map();

  for (const url of uniqueUrls) {
    const query = getStoreSearchQueryFromUrl(url) || `url:${url}`;
    const group = grouped.get(query) || [];
    group.push(url);
    grouped.set(query, group);
  }

  const prioritizedGroups = Array.from(grouped.entries())
    .map(([query, group], index) => ({
      query,
      group,
      index,
      tokenCount: tokenizeSearchText(query).length || Number.MAX_SAFE_INTEGER,
    }))
    .sort(
      (left, right) =>
        left.tokenCount - right.tokenCount || left.index - right.index
    )
    .map((entry) => entry.group);

  const selected = [];
  for (const group of prioritizedGroups) {
    if (group[0]) selected.push(group[0]);
    if (selected.length >= limit) return selected;
  }

  for (const group of prioritizedGroups) {
    for (const url of group.slice(1)) {
      selected.push(url);
      if (selected.length >= limit) return selected;
    }
  }

  return selected;
}

function extractStoreSearchPaginationUrls({
  html,
  pageUrl,
  websiteUrl,
  limit = 2,
}) {
  const currentQuery = getStoreSearchQueryFromUrl(pageUrl);
  const candidates = [];
  const tagRegex = /<(?:a|link)\b[^>]*>/gi;
  let match;

  while ((match = tagRegex.exec(String(html || ""))) !== null) {
    const tag = match[0] || "";
    const href = getAttributeValueFromTag(tag, "href");
    const url = href ? resolveUrl(href, pageUrl) : "";
    if (
      !url ||
      !isHttpUrl(url) ||
      normalizeComparableValue(url) === normalizeComparableValue(pageUrl) ||
      !isSameOrSubdomainUrl(url, websiteUrl)
    ) {
      continue;
    }

    let parsed;
    try {
      parsed = new URL(url);
    } catch {
      continue;
    }

    const normalizedTag = normalizeSearchText(tag);
    const hasStructuralPaginationSignal =
      /\/page\/\d+(?:\/|$)/i.test(parsed.pathname) ||
      ["page", "paged", "pageno", "page_number", "offset", "start"].some(
        (key) => parsed.searchParams.has(key)
      ) ||
      /\b(?:pagination|pager|page-numbers)\b/u.test(normalizedTag) ||
      /\brel\s*=\s*["']?next\b/i.test(tag);
    if (!hasStructuralPaginationSignal) {
      continue;
    }

    const candidateQuery = getStoreSearchQueryFromUrl(url);
    if (
      currentQuery &&
      candidateQuery &&
      normalizeSearchText(candidateQuery) !== normalizeSearchText(currentQuery)
    ) {
      continue;
    }

    candidates.push(url);
  }

  return Array.from(new Set(candidates)).slice(0, limit);
}

async function discoverProductCandidatesFromStoreSearch({
  websiteUrl,
  campaignPrompt,
  usedItems = [],
  excludeUsed = true,
  supabase = null,
  rule = null,
  deadlineMs = null,
}) {
  const knownDomainState = await getWebsiteDomainFetchState(websiteUrl).catch(() => null);
  if (isWebsiteAccessProtectedState(knownDomainState)) {
    console.info("Direct store-search discovery skipped for known protected website", {
      ruleId: rule?.id || null,
      websiteUrl,
    });
    return [];
  }

  const candidates = [];
  const usedComparable = new Set(
    (usedItems || [])
      .map((item) => normalizeComparableValue(item.item_url || item.product_url || item.url))
      .filter(Boolean)
  );

  let homeHtml = "";
  let detectedPlatform = "generic";
  let formSearchUrls = [];
  const searchDiagnostics = [];

  const searchFormInspectionUrls = Array.from(
    new Set([
      websiteUrl,
      ...getWebsiteSearchBaseUrls(websiteUrl),
    ].filter(Boolean))
  );
  for (const inspectionUrl of searchFormInspectionUrls) {
    try {
      homeHtml = await fetchHtml(inspectionUrl);
      const inspectedPlatform = detectCommercePlatform({
        html: homeHtml,
        url: inspectionUrl,
      });
      if (detectedPlatform === "generic" || inspectedPlatform !== "generic") {
        detectedPlatform = inspectedPlatform;
      }
      formSearchUrls.push(
        ...extractSearchFormUrlsFromHtml({
          html: homeHtml,
          pageUrl: inspectionUrl,
          campaignPrompt,
        })
      );
      formSearchUrls = Array.from(new Set(formSearchUrls)).slice(
        0,
        CAMPAIGN_SEARCH_FORM_URL_LIMIT
      );
      if (formSearchUrls.length >= CAMPAIGN_SEARCH_FORM_URL_LIMIT) break;
    } catch (error) {
      if (isWebsiteRateLimitError(error)) throw error;
      console.log("Could not inspect store search forms", {
        websiteUrl,
        inspectionUrl,
        message: error.message,
      });
    }
  }

  if (detectedPlatform === "shopify") {
    const suggestionCandidates = await discoverShopifySearchSuggest({
      websiteUrl,
      campaignPrompt,
    });
    candidates.push(...suggestionCandidates);

    const suggestionCounts = new Map();
    for (const candidate of suggestionCandidates) {
      const query = candidate?.found_by_query || getStoreSearchQueryFromUrl(candidate?.source_search_url);
      if (!query) continue;
      suggestionCounts.set(query, Number(suggestionCounts.get(query) || 0) + 1);
    }
    for (const [query, candidateCount] of suggestionCounts.entries()) {
      searchDiagnostics.push({
        source: "shopify_suggest",
        query,
        searchUrl: null,
        candidateCount,
      });
    }
  }

  const fallbackSearchUrls = buildStoreSearchUrls(
    websiteUrl,
    campaignPrompt,
    detectedPlatform
  );
  const initialSearchUrlLimit = Math.min(
    CAMPAIGN_STORE_SEARCH_QUERY_LIMIT,
    WEBSITE_STORE_SEARCH_FETCH_LIMIT
  );
  // Once the retailer exposes its real search form, use that contract for all
  // campaign queries. Guessing common /search URL shapes alongside a known form
  // created avoidable 404 pages and wasted the bounded retrieval budget.
  const allSearchUrls = Array.from(
    new Set(formSearchUrls.length ? formSearchUrls : fallbackSearchUrls)
  );
  const searchUrls = selectStoreSearchUrlsForFetch(
    allSearchUrls,
    initialSearchUrlLimit
  );
  const searchUrlQueue = [...searchUrls];
  const queuedSearchUrls = new Set(searchUrlQueue);
  const remainingSearchUrls = allSearchUrls.filter(
    (url) => !queuedSearchUrls.has(url)
  );
  const queueNextSearchAlternative = (query) => {
    if (searchUrlQueue.length >= CAMPAIGN_STORE_SEARCH_PAGE_FETCH_LIMIT) {
      return false;
    }
    const comparableQuery = normalizeSearchText(query || "");
    const alternativeIndex = remainingSearchUrls.findIndex(
      (url) =>
        normalizeSearchText(getStoreSearchQueryFromUrl(url) || "") ===
        comparableQuery
    );
    if (alternativeIndex < 0) {
      return false;
    }
    const [alternativeUrl] = remainingSearchUrls.splice(alternativeIndex, 1);
    if (!alternativeUrl || queuedSearchUrls.has(alternativeUrl)) {
      return false;
    }
    queuedSearchUrls.add(alternativeUrl);
    searchUrlQueue.push(alternativeUrl);
    return true;
  };
  let renderedSearchBrowserSession = null;
  let renderedSearchPageCount = 0;
  let renderedSearchUnavailable = false;
  const renderedSearchPageLimit = Math.max(
    0,
    Math.min(
      6,
      Number(process.env.RENDERED_STORE_SEARCH_PAGE_LIMIT || 4)
    )
  );

  try {
    for (
      let searchIndex = 0;
      searchIndex < searchUrlQueue.length &&
      searchIndex < CAMPAIGN_STORE_SEARCH_PAGE_FETCH_LIMIT;
      searchIndex += 1
    ) {
      if (
        deadlineMs &&
        Number.isFinite(Number(deadlineMs)) &&
        Date.now() >= Number(deadlineMs) - 45_000
      ) {
        break;
      }

      const searchUrl = searchUrlQueue[searchIndex];
      const foundByQuery = getStoreSearchQueryFromUrl(searchUrl);
      try {
        let html = await fetchHtml(searchUrl);
        let renderedSearchPage = false;
        let searchCandidates = extractProductLinksFromDiscoveryPage({
          html,
          pageUrl: searchUrl,
          websiteUrl,
          campaignPrompt,
        });

        if (
          !searchCandidates.length &&
          !renderedSearchUnavailable &&
          renderedSearchPageCount < renderedSearchPageLimit &&
          process.env.DISABLE_RENDERED_STORE_SEARCH !== "1" &&
          process.env.DISABLE_PRODUCT_IMAGE_BROWSER !== "1"
        ) {
          try {
            if (!renderedSearchBrowserSession) {
              renderedSearchBrowserSession = await createProductImageBrowserSession({
                validateUrl: assertPublicHttpUrl,
              });
            }
            renderedSearchPageCount += 1;
            const renderedSearchResult = await renderedSearchBrowserSession.renderHtml({
              pageUrl: searchUrl,
            });
            if (!renderedSearchResult?.html) {
              throw new Error("Rendered store-search page did not return HTML.");
            }
            html = renderedSearchResult.html;
            searchCandidates = extractProductLinksFromDiscoveryPage({
              html,
              pageUrl: searchUrl,
              websiteUrl,
              campaignPrompt,
            });
            renderedSearchPage = true;
          } catch (renderError) {
            renderedSearchUnavailable = true;
            console.log("Rendered store-search discovery unavailable", {
              searchUrl,
              message: renderError.message,
            });
          }
        }

        searchCandidates = searchCandidates.map((item) => ({
          ...item,
          source_page_url: item.source_page_url || searchUrl,
          source_search_url: searchUrl,
          found_by_query: foundByQuery || item?.found_by_query || null,
          reason: item.reason || `Product found from store search page: ${searchUrl}`,
          score: Number(item.score || 0) + 90,
          campaign_fit_source: item.campaign_fit_source || "store_search_page",
          commerce_platform: detectedPlatform,
        }));

        searchDiagnostics.push({
          source: renderedSearchPage
            ? "rendered_store_search_page"
            : "store_search_page",
          query: foundByQuery || null,
          searchUrl,
          candidateCount: searchCandidates.length,
        });
        candidates.push(...searchCandidates);

        if (searchUrlQueue.length < CAMPAIGN_STORE_SEARCH_PAGE_FETCH_LIMIT) {
          const paginationUrls = extractStoreSearchPaginationUrls({
            html,
            pageUrl: searchUrl,
            websiteUrl,
            limit: 2,
          });
          for (const paginationUrl of paginationUrls) {
            if (
              queuedSearchUrls.has(paginationUrl) ||
              searchUrlQueue.length >= CAMPAIGN_STORE_SEARCH_PAGE_FETCH_LIMIT
            ) {
              continue;
            }
            queuedSearchUrls.add(paginationUrl);
            searchUrlQueue.push(paginationUrl);
          }
        }
        if (!searchCandidates.length) {
          queueNextSearchAlternative(foundByQuery);
        }
      } catch (error) {
        if (isWebsiteRateLimitError(error)) throw error;
        queueNextSearchAlternative(foundByQuery);
        console.log("Store search URL unavailable", {
          searchUrl,
          platform: detectedPlatform,
          message: error.message,
        });
      }
    }
  } finally {
    if (renderedSearchBrowserSession) {
      await renderedSearchBrowserSession.close().catch(() => {});
    }
  }

  const result = selectBalancedStoreSearchCandidates(
    candidates,
    WEBSITE_STORE_SEARCH_CANDIDATE_POOL_LIMIT,
    {
      rule,
      usedComparable,
      excludeUsed,
    }
  ).slice(0, WEBSITE_STORE_SEARCH_CANDIDATE_POOL_LIMIT);

  const candidatesPersisted = await upsertWebsiteProductCandidateQueue({
    supabase,
    rule,
    sourceUrl: websiteUrl,
    categoryUrl: null,
    candidates: result,
  });

  console.log("Product Engine V2 store search finished", {
    websiteUrl,
    platform: detectedPlatform,
    formSearchUrlCount: formSearchUrls.length,
    fallbackSearchUrlCount: fallbackSearchUrls.length,
    candidateCount: result.length,
    excludeUsed,
    candidatesPersisted,
    renderedSearchPageCount,
    fetchedSearchPageCount: searchDiagnostics.filter((entry) =>
      /store_search_page/.test(entry.source)
    ).length,
    queries: buildStoreSearchQueries(campaignPrompt),
    searchDiagnostics: searchDiagnostics.slice(0, 30),
  });

  return result;
}

function extractUrlsFromXml(xml, pageUrl) {
  const urls = [];
  const locRegex = /<loc>\s*([^<]+?)\s*<\/loc>/gi;
  let match;

  while ((match = locRegex.exec(String(xml || ""))) !== null) {
    const rawUrl = String(match[1] || "").trim();
    const url = resolveUrl(rawUrl, pageUrl);

    if (url && isHttpUrl(url)) {
      urls.push(url);
    }
  }

  return Array.from(new Set(urls));
}

function scoreDiscoveredProductUrl(url, websiteUrl, campaignPrompt) {
  return scorePossibleProductLink({
    url,
    text: "",
    campaignPrompt,
  }) + (isLikelyNonProductUrl(url, websiteUrl) ? -100 : 0);
}

async function discoverShopifyProductsJson({ websiteUrl, campaignPrompt }) {
  const origin = getWebsiteOrigin(websiteUrl);
  const storefrontBase = getWebsiteSearchBaseUrls(websiteUrl)[0] || origin;

  if (!origin || !storefrontBase) {
    return [];
  }

  const discovered = [];

  for (let page = 1; page <= 3; page += 1) {
    const jsonUrl = `${storefrontBase}/products.json?limit=250&page=${page}`;

    try {
      const safeJsonUrl = await assertPublicHttpUrl(jsonUrl);
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), WEBSITE_FETCH_TIMEOUT_MS);
      const response = await fetch(safeJsonUrl, {
        headers: {
          "user-agent": "SpreeloBot/1.0 (+https://spreelo.com)",
          accept: "application/json,text/plain,*/*",
        },
        signal: controller.signal,
      });
      clearTimeout(timeout);

      if (!response.ok) {
        break;
      }

      const json = await response.json();
      const products = Array.isArray(json?.products) ? json.products : [];

      if (!products.length) {
        break;
      }

      for (const product of products) {
        const handle = String(product?.handle || "").trim();
        const title = String(product?.title || "").trim();
        const productUrl = handle ? `${storefrontBase}/products/${handle}` : "";
        const imageUrl =
          product?.image?.src ||
          product?.images?.[0]?.src ||
          null;
        const variants = Array.isArray(product?.variants)
          ? product.variants
          : [];
        const explicitInStock = variants.some(
          (variant) =>
            variant?.available === true ||
            (Number.isFinite(Number(variant?.inventory_quantity)) &&
              Number(variant?.inventory_quantity) > 0)
        );

        if (!productUrl || !title || isLikelyNonProductUrl(productUrl, websiteUrl)) {
          continue;
        }

        discovered.push({
          title,
          url: productUrl,
          image_url: imageUrl && isHttpUrl(imageUrl) ? imageUrl : null,
          description: String(product?.body_html || product?.body || ""),
          availability: explicitInStock ? "in_stock" : "unknown",
          availability_status: explicitInStock ? "in_stock" : "unknown",
          availability_evidence: explicitInStock
            ? "Current public Shopify product feed reports an available/inventory-positive variant."
            : "",
          stock_verified_at: explicitInStock ? new Date().toISOString() : null,
          stock_verification_source: explicitInStock
            ? "public_shopify_products_feed"
            : null,
          stock_verification_evidence: explicitInStock
            ? "Current public Shopify product feed reports an available/inventory-positive variant."
            : "",
          authoritative_public_commerce_feed: explicitInStock,
          product_identity_locked: explicitInStock && Boolean(imageUrl),
          technical_identity_same_page_verified: explicitInStock && Boolean(imageUrl),
          product_image_page_bound: explicitInStock && Boolean(imageUrl),
          product_image_page_bound_source: explicitInStock
            ? "public_shopify_products_feed"
            : null,
          product_image_source_page_url: productUrl,
          ecommerce_proof_found: true,
          concrete_product_verified: true,
          product_confidence: explicitInStock && imageUrl ? 100 : 70,
          reason: "Product found from Shopify products feed",
          score: scorePossibleProductLink({ url: productUrl, text: title, campaignPrompt }),
        });
      }
    } catch (error) {
      console.log("Shopify products.json discovery unavailable", {
        websiteUrl,
        message: error.message,
      });
      break;
    }
  }

  return dedupeUrlItems(discovered)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 80);
}

async function discoverWooCommerceStoreApiProducts({
  websiteUrl,
  campaignPrompt,
  maxPages = 2,
}) {
  const origin = getWebsiteOrigin(websiteUrl);
  if (!origin) return [];

  const discovered = [];
  for (let page = 1; page <= Math.max(1, Math.min(3, Number(maxPages || 2))); page += 1) {
    const apiUrl = `${origin}/wp-json/wc/store/v1/products?per_page=100&page=${page}`;
    try {
      const safeApiUrl = await assertPublicHttpUrl(apiUrl);
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), WEBSITE_FETCH_TIMEOUT_MS);
      const response = await fetch(safeApiUrl, {
        headers: {
          "user-agent": "SpreeloBot/1.0 (+https://spreelo.com)",
          accept: "application/json,text/plain,*/*",
        },
        signal: controller.signal,
      });
      clearTimeout(timeout);
      if (!response.ok) break;

      const products = await response.json();
      if (!Array.isArray(products) || !products.length) break;

      for (const product of products) {
        const title = String(product?.name || "").trim();
        const productUrl = String(product?.permalink || "").trim();
        const imageUrl = String(product?.images?.[0]?.src || "").trim() || null;
        const explicitInStock =
          product?.is_in_stock === true ||
          String(product?.stock_status || "").toLowerCase() === "instock";
        if (
          !title ||
          !productUrl ||
          !isHttpUrl(productUrl) ||
          !isSameOrSubdomainUrl(productUrl, websiteUrl) ||
          isLikelyNonProductUrl(productUrl, websiteUrl)
        ) {
          continue;
        }

        discovered.push({
          title,
          url: productUrl,
              image_url: imageUrl && isHttpUrl(imageUrl) ? imageUrl : null,
          description: String(product?.short_description || product?.description || ""),
          availability: explicitInStock ? "in_stock" : "unknown",
          availability_status: explicitInStock ? "in_stock" : "unknown",
          availability_evidence: explicitInStock
            ? "Current public WooCommerce Store API reports the product as in stock."
            : "",
          stock_verified_at: explicitInStock ? new Date().toISOString() : null,
          stock_verification_source: explicitInStock
            ? "public_woocommerce_store_api"
            : null,
          stock_verification_evidence: explicitInStock
            ? "Current public WooCommerce Store API reports the product as in stock."
            : "",
          authoritative_public_commerce_feed: explicitInStock,
          product_identity_locked: explicitInStock && Boolean(imageUrl),
          technical_identity_same_page_verified: explicitInStock && Boolean(imageUrl),
          product_image_page_bound: explicitInStock && Boolean(imageUrl),
          product_image_page_bound_source: explicitInStock
            ? "public_woocommerce_store_api"
            : null,
          product_image_source_page_url: productUrl,
          ecommerce_proof_found: true,
          concrete_product_verified: true,
          product_confidence: explicitInStock && imageUrl ? 100 : 70,
          commerce_platform: "woocommerce",
          reason: "Product found from public WooCommerce Store API",
          score: scorePossibleProductLink({
            url: productUrl,
            text: title,
            campaignPrompt,
          }),
        });
      }
    } catch (error) {
      console.log("WooCommerce Store API discovery unavailable", {
        websiteUrl,
        message: error?.message || String(error),
      });
      break;
    }
  }

  return dedupeUrlItems(discovered)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 120);
}

async function discoverPublicCommerceFeedCandidates({
  websiteUrl,
  campaignPrompt,
}) {
  const [shopifyResult, wooResult] = await Promise.allSettled([
    discoverShopifyProductsJson({ websiteUrl, campaignPrompt }),
    discoverWooCommerceStoreApiProducts({ websiteUrl, campaignPrompt }),
  ]);
  const candidates = [
    ...(shopifyResult.status === "fulfilled" ? shopifyResult.value : []),
    ...(wooResult.status === "fulfilled" ? wooResult.value : []),
  ].filter(
    (item) =>
      item?.authoritative_public_commerce_feed === true &&
      isProductConfirmedPurchasable(item) &&
      item?.title &&
      item?.url &&
      item?.image_url
  );

  if (candidates.length) {
    console.log("Protected/public commerce feed discovery found current in-stock products", {
      websiteUrl,
      candidateCount: candidates.length,
      sources: Array.from(
        new Set(candidates.map((item) => item?.stock_verification_source).filter(Boolean))
      ),
    });
  }
  return dedupeUrlItems(candidates).slice(0, 160);
}

