async function normalizeEditorialTypographyArtwork(generatedBuffer) {
  const normalized = await sharp(generatedBuffer)
    .rotate()
    .resize({ width: 1024, height: 1024, fit: "fill", kernel: sharp.kernel.lanczos3 })
    .ensureAlpha()
    .png({ compressionLevel: 9 })
    .toBuffer();

  const { data, info } = await sharp(normalized)
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  const pixelCount = Math.max(1, info.width * info.height);
  const alphaChannel = Buffer.alloc(pixelCount);
  let visiblePixelCount = 0;
  for (let pixel = 0; pixel < pixelCount; pixel += 1) {
    const alpha = data[pixel * info.channels + 3];
    alphaChannel[pixel] = alpha;
    if (alpha >= 24) visiblePixelCount += 1;
  }

  const visibleRatio = visiblePixelCount / pixelCount;
  if (visibleRatio < 0.0015) {
    throw new Error("Editorial typography overlay was visually empty");
  }
  if (visibleRatio > 0.32) {
    throw new Error("Editorial typography overlay contained too much opaque artwork");
  }

  const bounds = findAlphaBounds(alphaChannel, info.width, info.height, 24);
  if (!bounds) {
    throw new Error("Editorial typography overlay had no visible alpha bounds");
  }
  if (bounds.width > 990 || bounds.height > 920) {
    throw new Error("Editorial typography overlay looked like a full-frame image instead of typography");
  }

  return {
    artworkBuffer: await sharp(normalized)
      .extract(bounds)
      .png({ compressionLevel: 9 })
      .toBuffer(),
    bounds,
    visibleRatio: Number(visibleRatio.toFixed(4)),
  };
}

async function createWebsiteItemEditorialTypographyOverlay({
  openai,
  rule,
  postContent,
  layoutReferenceBuffer,
  productPlacement,
}) {
  const referenceFile = await toFile(
    await sharp(layoutReferenceBuffer)
      .rotate()
      .resize({ width: 1024, height: 1280, fit: "fill" })
      .png({ compressionLevel: 9 })
      .toBuffer(),
    "editorial-product-layout-reference.png",
    { type: "image/png" }
  );
  const prompt = buildWebsiteItemEditorialTypographyOverlayPrompt(rule, postContent);

  let lastError = null;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const response = await openai.images.edit({
        model: IMAGE_MODEL,
        image: referenceFile,
        prompt: attempt === 0
          ? prompt
          : `${prompt}\n\nRETRY CORRECTION: Return typography only on real alpha transparency. Keep the artwork compact and centered. No background, product, frame, panel or third line of copy.`,
        size: "1024x1024",
        quality: "medium",
        background: "transparent",
        output_format: "png",
      });
      const imageBase64 = response?.data?.[0]?.b64_json;
      if (!imageBase64) {
        throw new Error("OpenAI editorial typography generation returned empty image data");
      }
      const normalized = await normalizeEditorialTypographyArtwork(
        Buffer.from(imageBase64, "base64")
      );

      const productBottom = Number(productPlacement?.top || 0) + Number(productPlacement?.height || 0);
      const zoneTop = Math.max(820, Math.min(930, productBottom + 34));
      const zoneBottom = 1120;
      const zoneHeight = Math.max(170, zoneBottom - zoneTop);
      const maxWidth = 800;
      const sourceMeta = await sharp(normalized.artworkBuffer).metadata();
      const sourceWidth = Math.max(1, Number(sourceMeta.width || 1));
      const sourceHeight = Math.max(1, Number(sourceMeta.height || 1));
      const scale = Math.min(maxWidth / sourceWidth, zoneHeight / sourceHeight, 1.25);
      const targetWidth = Math.max(1, Math.round(sourceWidth * scale));
      const targetHeight = Math.max(1, Math.round(sourceHeight * scale));
      const overlayBuffer = await sharp(normalized.artworkBuffer)
        .resize({ width: targetWidth, height: targetHeight, fit: "fill", kernel: sharp.kernel.lanczos3 })
        .png({ compressionLevel: 9 })
        .toBuffer();
      const left = Math.round((1024 - targetWidth) / 2);
      const top = Math.round(zoneTop + Math.max(0, (zoneHeight - targetHeight) / 2));

      return {
        overlayBuffer,
        placement: { left, top, width: targetWidth, height: targetHeight },
        prompt,
        analysis: {
          visibleRatio: normalized.visibleRatio,
          sourceBounds: normalized.bounds,
          safeZoneTop: zoneTop,
          safeZoneBottom: zoneBottom,
        },
      };
    } catch (error) {
      lastError = error;
      console.warn("Editorial transparent typography attempt failed", {
        ruleId: rule?.id || null,
        attempt: attempt + 1,
        message: error?.message || String(error),
      });
    }
  }
  throw lastError || new Error("Editorial transparent typography generation failed");
}

export async function generateWebsiteItemEditorialPostImage(openai, rule, postContent, costTracker = null) {
  const sourceImageUrl = rule?.website_item?.image_url;
  if (!sourceImageUrl) {
    throw new Error("Product post requires a verified website product image");
  }

  const sourceImageBuffer = await fetchImageBufferForOverlay(sourceImageUrl);
  let nativeReference = null;

  try {
    nativeReference = await prepareNativeTransparentEditorialReference(sourceImageBuffer);
  } catch {
    nativeReference = null;
  }

  if (nativeReference) {
    const prompt = buildWebsiteItemEditorialPostImagePrompt(rule, postContent, {
      nativeTransparent: true,
      includeLogo: shouldUseLogoForEditorialProductPost(rule, rule?.brand_profile),
    });

    const canvasBuffer = await sharp({
      create: {
        width: 1024,
        height: 1280,
        channels: 4,
        background: { r: 0, g: 0, b: 0, alpha: 0 },
      },
    })
      .composite([{
        input: nativeReference.lockedProductBuffer,
        left: nativeReference.placement.left,
        top: nativeReference.placement.top,
      }])
      .png({ compressionLevel: 9 })
      .toBuffer();

    const referenceFile = await toFile(
      canvasBuffer,
      "editorial-native-transparent-product-canvas.png",
      { type: "image/png" }
    );

    const imageRequest = {
      model: IMAGE_MODEL,
      image: referenceFile,
      prompt,
      size: "1024x1280",
      quality: "medium",
    };
    const response = await openai.images.edit(imageRequest);
    await ensureOpenAIResponseCostTracked({
      tracker: costTracker,
      operation: "images.edit",
      request: imageRequest,
      response,
    });
    const imageBase64 = response?.data?.[0]?.b64_json;
    if (!imageBase64) {
      throw new Error("OpenAI native transparent editorial product-post generation returned empty image data");
    }

    console.info("Editorial product post generated in one GPT-Image-2 pass around the native transparent product", {
      ruleId: rule?.id || null,
      productTitle: rule?.website_item?.title || null,
      sourceImageUrl,
      placement: nativeReference.placement,
      nativeTransparency: nativeReference.nativeTransparency,
      campaignScoped: isCampaignScopedWebsiteRule(rule),
    });

    return {
      imageBase64,
      imagePrompt: prompt,
      productHandlingMode: "native_transparent_single_pass",
    };
  }

  const prompt = buildWebsiteItemEditorialPostImagePrompt(rule, postContent, {
    nativeTransparent: false,
    includeLogo: shouldUseLogoForEditorialProductPost(rule, rule?.brand_profile),
  });
  const normalizedSourceImageBuffer = await sharp(sourceImageBuffer)
    .rotate()
    .resize({
      width: 1536,
      height: 1536,
      fit: "inside",
      withoutEnlargement: true,
    })
    .png({ compressionLevel: 9 })
    .toBuffer();
  const referenceFile = await toFile(
    normalizedSourceImageBuffer,
    "verified-product-reference.png",
    { type: "image/png" }
  );

  const imageRequest = {
    model: IMAGE_MODEL,
    image: referenceFile,
    prompt,
    size: "1024x1280",
    quality: "medium",
  };
  const response = await openai.images.edit(imageRequest);
  await ensureOpenAIResponseCostTracked({
    tracker: costTracker,
    operation: "images.edit",
    request: imageRequest,
    response,
  });
  const imageBase64 = response?.data?.[0]?.b64_json;
  if (!imageBase64) {
    throw new Error("OpenAI editorial product-post generation returned empty image data");
  }

  console.info("Editorial product post generated with high-fidelity product recreation", {
    ruleId: rule?.id || null,
    productTitle: rule?.website_item?.title || null,
    sourceImageUrl,
    campaignScoped: isCampaignScopedWebsiteRule(rule),
  });

  return {
    imageBase64,
    imagePrompt: prompt,
    productHandlingMode: "high_fidelity_recreation",
  };
}

function websiteTextContainsAny(value, keywords = []) {
  const haystack = String(value || "").toLowerCase();
  return keywords.some((keyword) => haystack.includes(String(keyword || "").toLowerCase()));
}

function getWebsiteItemAdLayoutSeed(rule, postContent) {
  return [
    rule?.website_item?.item_key,
    rule?.website_item?.url,
    rule?.website_item?.title,
    rule?.brand_profile?.business_name,
    postContent,
  ]
    .filter(Boolean)
    .join(" | ");
}

function getDeterministicLayoutIndex(seed, count) {
  const safeCount = Math.max(1, Number(count || 1));
  const source = String(seed || "layout-seed");
  let hash = 0;

  for (let index = 0; index < source.length; index += 1) {
    hash = (hash << 5) - hash + source.charCodeAt(index);
    hash |= 0;
  }

  return Math.abs(hash) % safeCount;
}

function selectWebsiteItemAdLayoutFamily(rule, postContent) {
  const item = rule?.website_item || {};
  const productContext = [
    item?.title,
    item?.description,
    rule?.prompt,
    rule?.image_prompt,
    postContent,
    rule?.brand_profile?.business_name,
    rule?.brand_profile?.industry,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  const seed = getWebsiteItemAdLayoutSeed(rule, postContent);

  const layoutFamilies = {
    emotional_hero: {
      key: "emotional_hero",
      name: "Emotional hero",
      instruction:
        "Build the ad around one strong emotional promise or occasion. Use a cinematic/lifestyle background and let the exact product be the hero. Use one large headline, one short supporting line and a restrained CTA. Avoid a three-point feature list unless the product genuinely needs it.",
    },
    clean_premium: {
      key: "clean_premium",
      name: "Clean premium",
      instruction:
        "Use a polished premium product spotlight with generous negative space, refined typography and very little copy. The product should dominate. Use one concise headline, at most one small badge or proof point, and a subtle CTA/domain. Do not use a bullet list.",
    },
    benefits_icons: {
      key: "benefits_icons",
      name: "Benefits with icons",
      instruction:
        "Use a structured benefits-led layout. Show the exact product prominently and support it with 2 or 3 short verified benefits, preferably with simple visual icons or markers. Keep every benefit brief and mobile-readable. Do not invent features just to fill three slots.",
    },
    problem_solution: {
      key: "problem_solution",
      name: "Problem to solution",
      instruction:
        "Lead with a concrete customer problem or need that is supported by the product context, then present the exact product as the solution. Use a strong problem/solution headline structure, one short explanation and a clear CTA. Avoid generic feature bullets unless they directly explain the solution.",
    },
    technical_spec: {
      key: "technical_spec",
      name: "Technical specification",
      instruction:
        "Use a professional technical/product-information layout suited to construction, tools, B2B or specification-heavy products. Present 2 to 4 verified facts or use-cases in a clean grid or callout system, with strong hierarchy and no decorative lifestyle claims. Never invent specifications that are not present in the verified product data.",
    },
    seasonal_campaign: {
      key: "seasonal_campaign",
      name: "Seasonal campaign",
      instruction:
        "Make the campaign or season visually unmistakable while keeping the exact product central. Use one timely headline, a short supporting line and a clear CTA. Seasonal props and atmosphere may frame the product, but do not add fake sellable products or force a three-point list.",
    },
  };

  const pickFrom = (keys) => {
    const safeKeys = keys.filter((key) => layoutFamilies[key]);
    return layoutFamilies[safeKeys[getDeterministicLayoutIndex(seed, safeKeys.length)]];
  };

  const technicalProduct = websiteTextContainsAny(productContext, [
    "isover", "insulation", "isolering", "bygg", "construction", "fasad", "vindskydd", "membrane", "fog", "tätnings", "verktyg", "tool", "industrial", "b2b", "specifikation", "technical"
  ]);
  if (technicalProduct) {
    return pickFrom(["technical_spec", "problem_solution", "clean_premium"]);
  }

  const seasonalContext = Boolean(isCampaignScopedWebsiteRule(rule)) && websiteTextContainsAny(productContext, [
    "jul", "christmas", "halloween", "skolstart", "back to school", "school", "sommar", "summer", "vinter", "winter", "höst", "autumn", "spring", "valentine", "mors dag", "fars dag", "black friday", "cyber monday", "new year", "nyår"
  ]);
  if (seasonalContext) {
    return pickFrom(["seasonal_campaign", "emotional_hero", "benefits_icons"]);
  }

  if (websiteTextContainsAny(productContext, [
    "gift", "gåva", "present", "teddy", "nalle", "toy", "leksak", "baby", "barn", "kids", "love", "kärlek", "home", "decor", "inredning"
  ])) {
    return pickFrom(["emotional_hero", "seasonal_campaign", "clean_premium"]);
  }

  if (websiteTextContainsAny(productContext, [
    "skincare", "beauty", "serum", "cream", "cosmetic", "perfume", "parfum", "watch", "jewelry", "smycke", "luxury", "premium", "fashion", "sneaker", "shoe", "skor"
  ])) {
    return pickFrom(["clean_premium", "emotional_hero", "seasonal_campaign"]);
  }

  if (websiteTextContainsAny(productContext, [
    "feature", "material", "recycled", "återvunnen", "waterproof", "vattentät", "soft", "mjuk", "capacity", "storage", "funktion", "benefit"
  ])) {
    return pickFrom(["benefits_icons", "problem_solution", "clean_premium"]);
  }

  return pickFrom([
    "emotional_hero",
    "clean_premium",
    "benefits_icons",
    "problem_solution",
    "technical_spec",
    "seasonal_campaign",
  ]);
}

function buildWebsiteItemAdImagePrompt(rule, postContent) {
  const brandProfileText = formatBrandProfileForPrompt(rule.brand_profile);
  const websiteItemText = formatWebsiteItemForPrompt(rule.website_item);
  const customVisualDirection = String(rule?.image_prompt || "").trim();
  const selectedLayoutFamily = selectWebsiteItemAdLayoutFamily(rule, postContent);

  return `
Create one high-quality portrait 4:5 social media ad image using the provided product photo as the visual reference for the exact product.

Brand profile:
${brandProfileText}

Selected website item:
${websiteItemText}

Platform: ${rule.platform || "Facebook"}
Tone: ${rule.tone || "Professional"}
Language context: ${rule.language || "Auto"}
Website URL: ${rule.brand_profile?.website_url || "Not provided"}

${formatCampaignVisualContextForPrompt(rule)}

Selected ad layout family:
${selectedLayoutFamily?.name || "Feature split"}

Layout family instruction:
${selectedLayoutFamily?.instruction || "Use a clear product-focused ad layout with concise text and a strong CTA."}

User's post instruction:
${rule.prompt || "Not provided"}

Final post text this image should support:
${postContent || "Not provided"}

${customVisualDirection ? `Customer's visual direction:
${customVisualDirection}` : "No extra custom visual direction was provided."}

Rules:
- If a CAMPAIGN IDENTITY LOCK is provided above, it is authoritative over the User instruction, Final post text, product context and every other supporting field. Never write or visualize another named campaign, holiday, theme day, season, shopping event or occasion.
- The provided product image is the real product reference. Keep the product clearly recognizable.
- Preserve the product's core identity, silhouette, dominant colors, print/design, and overall appearance.
- Preserve the exact visible product color from the verified source image.
- Do not recolor the product or create a new color variant that is not verified.
- If multiple colors exist on the website, still keep the exact source-image color unless a different verified color is explicitly selected.
- When uncertain, keep the exact source-image color and appearance.
- Build a unique ad-style composition around that product so the final result feels custom-made for this exact item.
- The supplied reference is the only sellable product you may depict. Do not invent a second product, alternate garment, alternate print/design, package, accessory or other merchandise that could be mistaken for another item in the customer's catalog.
- People, environments and contextual props may support the scene, but any incidental object must stay clearly secondary and must not look like an additional advertised product.
- Follow the selected ad layout family above. Do not default to the same left-text/right-product feature-list layout unless that is the selected family.
- Let the chosen layout family influence the composition, text placement, product scale, and overall mood so different products can receive different visual treatments.
- Include readable marketing text in the image.
- Write all added marketing text in the selected post language.
- Use the exact verified product name when it appears in the image; do not rename the product.
- Preserve existing printed words or graphics on the product as accurately as possible.
- Keep the layout clean, simple, and spacious with fewer text elements and larger typography.
- Use one strong headline, one very short supporting line, and one short CTA.
- Never use internal automation/plan names, goal labels, slot labels, weekdays or scheduling metadata as visible ad copy.
- Do not repeat the product name or generic product category in multiple text elements. Every supporting line or callout must add distinct, verified information; if it adds nothing new, omit it.
- You may add up to 3 very short callout points or badges only if they are clearly supported by the website item and if they fit the selected layout family.
- If the selected layout family is more minimal, premium, or lifestyle-focused, prefer fewer callouts or no callouts at all.
- Do not write long paragraphs, dense body copy, or small filler text.
- Do not place compact text blocks, dense info cards, or small packed text boxes in the design.
- If callout boxes or badges are used, keep them short, bold, and easy to read, with one idea per element.
- Keep all added marketing text brief and highly legible on mobile. Prioritize bigger text over more text.
- Keep the total amount of added non-product text low.
- Do not include product prices, ratings, review stars or fake urgency. If an exact authorized customer-supplied campaign offer is provided above, show its discount and campaign code exactly as written; otherwise do not include discounts.
- Do not invent features, materials, delivery promises, guarantees, or claims that are not supported by the website item or post text.
- Keep the text concise, polished, and easy to read on social media.
- Do not add watermarks.
- Do not add unrelated UI or app screens.
- Avoid a generic template look; tailor the background, styling, and mood to this exact product.
- The image should feel premium and ready for a Facebook or Instagram feed post.

Output only the image.
`.trim();
}

export async function generateWebsiteItemAdImage(openai, rule, postContent, costTracker = null) {
  const sourceImageUrl = rule?.website_item?.image_url;

  if (!sourceImageUrl) {
    throw new Error("Website Text + Ad requires a verified website product image");
  }

  const selectedLayoutFamily = selectWebsiteItemAdLayoutFamily(rule, postContent);
  const prompt = buildWebsiteItemAdImagePrompt(rule, postContent);
  console.info("AI product ad layout selected", {
    ruleId: rule?.id || null,
    productUrl: rule?.website_item?.url || null,
    productTitle: rule?.website_item?.title || null,
    layoutFamily: selectedLayoutFamily?.key || null,
    layoutName: selectedLayoutFamily?.name || null,
  });
  const sourceImageBuffer = await fetchImageBufferForOverlay(sourceImageUrl);
  const normalizedSourceImageBuffer = await sharp(sourceImageBuffer)
    .rotate()
    .resize({
      width: 1536,
      height: 1536,
      fit: "inside",
      withoutEnlargement: true,
    })
    .png()
    .toBuffer();

  const referenceFile = await toFile(
    normalizedSourceImageBuffer,
    "website-product-reference.png",
    { type: "image/png" }
  );

  const imageRequest = {
    model: IMAGE_MODEL,
    image: referenceFile,
    prompt,
    size: "1024x1280",
    quality: "medium",
  };
  const response = await openai.images.edit(imageRequest);
  await ensureOpenAIResponseCostTracked({
    tracker: costTracker,
    operation: "images.edit",
    request: imageRequest,
    response,
  });

  const imageBase64 = response?.data?.[0]?.b64_json;

  if (!imageBase64) {
    throw new Error("OpenAI website ad image generation returned empty image data");
  }

  return {
    imageBase64,
    imagePrompt: prompt,
  };
}

