async function publishCarouselPostToInstagram({
  instagramUserId,
  accessToken,
  slideImageUrls,
  caption,
}) {
  const childIds = [];

  for (const imageUrl of slideImageUrls) {
    const childId = await createInstagramCarouselChild({
      instagramUserId,
      accessToken,
      imageUrl,
    });
    childIds.push(childId);
  }

  if (childIds.length < 2) {
    throw new Error("Instagram carousel publishing requires at least 2 slide images.");
  }

  const createResponse = await fetch(
    `https://graph.instagram.com/${INSTAGRAM_GRAPH_API_VERSION}/${instagramUserId}/media`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        media_type: "CAROUSEL",
        children: childIds,
        caption,
        access_token: accessToken,
      }),
    }
  );

  const createResult = await createResponse.json();

  if (!createResponse.ok || !createResult?.id) {
    throw new Error(
      getMetaErrorMessage(createResult, "Instagram carousel container creation failed")
    );
  }

  await waitForInstagramContainerReady({
    creationId: createResult.id,
    accessToken,
    instagramUserId,
  });

  const publishResponse = await fetch(
    `https://graph.instagram.com/${INSTAGRAM_GRAPH_API_VERSION}/${instagramUserId}/media_publish`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        creation_id: createResult.id,
        access_token: accessToken,
      }),
    }
  );

  const publishResult = await publishResponse.json();

  if (!publishResponse.ok || !publishResult?.id) {
    throw new Error(
      getMetaErrorMessage(publishResult, "Instagram carousel publish failed")
    );
  }

  return publishResult;
}

async function loadCarouselSlidesForPublish({ supabase, postId }) {
  const { data, error } = await supabase
    .from("post_slides")
    .select("id, slide_order, image_url, product_url, headline, body, cta_text, metadata")
    .eq("post_id", postId)
    .order("slide_order", { ascending: true });

  if (error) {
    throw new Error(error.message || "Could not load carousel slides");
  }

  return (data || []).filter((slide) => slide?.image_url);
}

function normalizePinterestDestinationUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";

  try {
    const url = new URL(raw);
    if (!['http:', 'https:'].includes(url.protocol)) return "";
    return url.toString();
  } catch {
    return "";
  }
}

function addPinterestOrganicTracking(destinationUrl, postId) {
  const normalized = normalizePinterestDestinationUrl(destinationUrl);
  if (!normalized) return "";

  try {
    const url = new URL(normalized);
    if (!url.searchParams.has('utm_source')) url.searchParams.set('utm_source', 'pinterest');
    if (!url.searchParams.has('utm_medium')) url.searchParams.set('utm_medium', 'organic_social');
    if (!url.searchParams.has('utm_campaign')) url.searchParams.set('utm_campaign', 'spreelo');
    if (postId && !url.searchParams.has('utm_content')) {
      url.searchParams.set('utm_content', String(postId));
    }
    const tracked = url.toString();
    if (tracked.length <= 2048) return tracked;
    return normalized.length <= 2048 ? normalized : "";
  } catch {
    return normalized.length <= 2048 ? normalized : "";
  }
}

function getPinterestCarouselDestination(slides = []) {
  const orderedSlides = Array.isArray(slides) ? slides : [];
  const outro = orderedSlides.find((slide) => {
    const role = String(getCarouselEmailSlideMetadata(slide)?.carousel_slide_role || '').toLowerCase();
    return role.includes('outro') && normalizePinterestDestinationUrl(slide?.product_url);
  });
  if (outro?.product_url) {
    return { url: normalizePinterestDestinationUrl(outro.product_url), source: 'carousel_outro' };
  }

  const firstProduct = orderedSlides.find((slide) => normalizePinterestDestinationUrl(slide?.product_url));
  if (firstProduct?.product_url) {
    return { url: normalizePinterestDestinationUrl(firstProduct.product_url), source: 'carousel_product_fallback' };
  }

  return { url: '', source: 'none' };
}

function resolvePinterestDestination({ post, content, carouselSlides = [] }) {
  const format = normalizeContentFormat(post?.content_format);

  if (format === 'carousel') {
    const carouselDestination = getPinterestCarouselDestination(carouselSlides);
    if (carouselDestination.url) return carouselDestination;
  }

  const postWebsiteUrl = normalizePinterestDestinationUrl(post?.website_url);
  if (postWebsiteUrl) {
    return { url: postWebsiteUrl, source: 'post_website_url' };
  }

  const explicitContentUrl = normalizePinterestDestinationUrl(
    extractUrlsFromText(String(content || ''))[0]?.replace(/[).,!?:;]+$/g, '') || ''
  );
  if (explicitContentUrl) {
    return { url: explicitContentUrl, source: 'caption_url' };
  }

  return { url: '', source: 'none' };
}

async function loadPinterestBrandFallbackDestination({ supabase, brandProfileId }) {
  if (!brandProfileId) return '';

  const { data, error } = await supabase
    .from('brand_profiles')
    .select('website_url, website_product_source_url')
    .eq('id', brandProfileId)
    .maybeSingle();

  if (error) {
    console.warn('Could not load Pinterest fallback destination for brand', {
      brandProfileId,
      message: error.message,
    });
    return '';
  }

  return (
    normalizePinterestDestinationUrl(data?.website_product_source_url) ||
    normalizePinterestDestinationUrl(data?.website_url) ||
    ''
  );
}

function buildPinterestPinCopy(content, destinationUrl = '', postId = '') {
  const raw = String(content || "").trim();
  const contentWithoutUrls = raw.replace(/https?:\/\/\S+/gi, " ").replace(/\s+/g, " ").trim();
  const titleSource =
    contentWithoutUrls.split(/(?<=[.!?])\s+|\n+/).map((item) => item.trim()).find(Boolean) ||
    "Spreelo";

  return {
    title: titleSource.slice(0, 100),
    description: contentWithoutUrls.slice(0, 800),
    link: addPinterestOrganicTracking(destinationUrl, postId),
  };
}

function pinterestPublishError(response, data, fallback) {
  const error = new Error(
    data?.message || data?.error_description || data?.error || fallback
  );
  error.status = response?.status || 0;
  error.pinterestCode = data?.code ?? data?.error_code ?? null;
  return error;
}

function isPinterestTransientPublishError(error) {
  if (error?.pinterestTransient === true) return true;
  const status = Number(error?.status || 0);
  const message = String(error?.message || "").toLowerCase();
  return Boolean(
    status === 408 ||
      status === 425 ||
      status === 429 ||
      (status >= 500 && status <= 599) ||
      /didn['’]?t finish|timed? out|timeout|task_flow:create_pin|_upload_pin_to_s3|temporar(?:y|ily) unavailable|try again|rate limit/.test(
        message
      )
  );
}

function pinterestPinMatchesPost(pin, postId) {
  const expected = String(postId || "").trim();
  if (!expected) return false;
  const link = String(pin?.link || "").trim();
  if (!link) return false;

  try {
    const url = new URL(link);
    return url.searchParams.get("utm_content") === expected;
  } catch {
    return link.includes(`utm_content=${encodeURIComponent(expected)}`) ||
      link.includes(`utm_content=${expected}`);
  }
}

function getPinterestProcessingReceipt(publishReceipts) {
  const receipt = publishReceipts?.pinterest;
  if (!receipt || typeof receipt !== "object" || Array.isArray(receipt)) return null;
  return String(receipt.state || "").toLowerCase() === "processing" ? receipt : null;
}

function isPinterestProcessingReceiptSettling(receipt, nowValue = new Date()) {
  if (!receipt) return false;
  const lastCreateMs = new Date(receipt.last_create_attempt_at || receipt.first_attempt_at || 0).getTime();
  if (!Number.isFinite(lastCreateMs) || lastCreateMs <= 0) return false;
  return nowValue.getTime() - lastCreateMs < PINTEREST_CREATE_SETTLE_MINUTES * 60_000;
}

function createPinterestProcessingPendingError(receipt) {
  const error = new Error(
    "Pinterest is still processing the previous Pin creation. Spreelo will verify the board before sending anything again."
  );
  error.pinterestTransient = true;
  error.pinterestProcessingPending = true;
  error.lastPinterestCreateAttemptAt = receipt?.last_create_attempt_at || null;
  return error;
}

async function findExistingPinterestPinForPost({ accessToken, boardId, postId }) {
  if (!accessToken || !boardId || !postId) return null;

  const url = new URL(
    `${getPinterestApiBaseUrl()}/boards/${encodeURIComponent(String(boardId))}/pins`
  );
  url.searchParams.set("page_size", String(PINTEREST_RECONCILE_PAGE_SIZE));

  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
    cache: "no-store",
  });
  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw pinterestPublishError(
      response,
      data,
      "Could not reconcile Pinterest publishing state"
    );
  }

  const items = Array.isArray(data?.items) ? data.items : [];
  return items.find((pin) => pinterestPinMatchesPost(pin, postId)) || null;
}

async function persistPublishedTarget({
  supabase,
  postId,
  publishedTargetSet,
  publishReceipts,
  target,
  receipt = null,
  nowIso,
}) {
  publishedTargetSet.add(target);
  if (receipt) publishReceipts[target] = receipt;

  const { error } = await supabase
    .from("posts")
    .update({
      published_targets: Array.from(publishedTargetSet),
      publish_receipts: publishReceipts,
      updated_at: nowIso,
    })
    .eq("id", postId);

  if (error) {
    throw new Error(`Could not persist ${target} publish receipt: ${error.message}`);
  }
}

async function registerPinterestVideoUpload(accessToken) {
  const response = await fetch(`${getPinterestApiBaseUrl()}/media`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ media_type: "video" }),
    cache: "no-store",
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data?.media_id || !data?.upload_url) {
    const error = pinterestPublishError(response, data, "Pinterest video upload could not be registered");
    error.pinterestPhase = "media_register";
    throw error;
  }
  return data;
}

async function uploadPinterestVideoFile({ uploadUrl, uploadParameters, videoUrl }) {
  await assertPublicHttpUrl(videoUrl);
  let sourceResponse;
  try {
    sourceResponse = await fetch(videoUrl, { cache: "no-store" });
  } catch (cause) {
    const error = new Error(`Could not download the rendered video for Pinterest: ${cause?.message || "network error"}`);
    error.pinterestPhase = "media_upload";
    error.pinterestTransient = true;
    throw error;
  }
  if (!sourceResponse.ok) {
    const error = new Error(`Could not download the rendered video for Pinterest (${sourceResponse.status})`);
    error.status = sourceResponse.status;
    error.pinterestPhase = "media_upload";
    throw error;
  }

  const contentType = String(sourceResponse.headers.get("content-type") || "video/mp4")
    .split(";")[0]
    .trim() || "video/mp4";
  const bytes = await sourceResponse.arrayBuffer();
  const form = new FormData();
  Object.entries(uploadParameters || {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null) form.append(key, String(value));
  });
  form.append("file", new Blob([bytes], { type: contentType }), "spreelo-video.mp4");

  let uploadResponse;
  try {
    uploadResponse = await fetch(uploadUrl, { method: "POST", body: form, cache: "no-store" });
  } catch (cause) {
    const error = new Error(`Pinterest video upload failed: ${cause?.message || "network error"}`);
    error.pinterestPhase = "media_upload";
    error.pinterestTransient = true;
    throw error;
  }
  if (!uploadResponse.ok && uploadResponse.status !== 204) {
    const responseText = await uploadResponse.text().catch(() => "");
    const error = new Error(`Pinterest video upload failed (${uploadResponse.status})${responseText ? `: ${responseText.slice(0, 240)}` : ""}`);
    error.status = uploadResponse.status;
    error.pinterestPhase = "media_upload";
    throw error;
  }
}

async function waitForPinterestVideoUpload({ accessToken, mediaId, postId }) {
  let lastStatus = "";
  for (let attempt = 1; attempt <= 8; attempt += 1) {
    const response = await fetch(`${getPinterestApiBaseUrl()}/media/${encodeURIComponent(String(mediaId))}`, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const error = pinterestPublishError(response, data, "Could not verify Pinterest video upload");
      error.pinterestPhase = "media_processing";
      throw error;
    }
    lastStatus = String(data?.status || "").trim().toLowerCase();
    if (lastStatus === "succeeded") {
      console.info("Pinterest video media upload ready", { postId: postId || null, mediaId: String(mediaId), attempt });
      return data;
    }
    if (["failed", "failure", "error"].includes(lastStatus)) {
      const error = new Error(`Pinterest rejected the uploaded video media (${lastStatus})`);
      error.pinterestPhase = "media_processing";
      throw error;
    }
    if (attempt < 8) await sleep(Math.min(1500 * attempt, 5000));
  }
  const error = new Error(`Pinterest video media is still processing (${lastStatus || "unknown"})`);
  error.pinterestPhase = "media_processing";
  error.pinterestTransient = true;
  throw error;
}

async function preparePinterestVideoMedia({ accessToken, videoUrl, postId }) {
  const registered = await registerPinterestVideoUpload(accessToken);
  await uploadPinterestVideoFile({ uploadUrl: registered.upload_url, uploadParameters: registered.upload_parameters, videoUrl });
  await waitForPinterestVideoUpload({ accessToken, mediaId: registered.media_id, postId });
  return String(registered.media_id);
}

async function publishPostToPinterest({
  accessToken,
  boardId,
  imageUrls,
  videoUrl = '',
  coverImageUrl = '',
  content,
  destinationUrl = '',
  postId = '',
}) {
  const uniqueImageUrls = [...new Set(
    (Array.isArray(imageUrls) ? imageUrls : [])
      .map((value) => String(value || "").trim())
      .filter(Boolean)
  )].slice(0, 5);

  if (!boardId) {
    throw new Error("Pinterest board is missing for this brand");
  }

  const normalizedVideoUrl = String(videoUrl || "").trim();
  const normalizedCoverImageUrl = String(coverImageUrl || uniqueImageUrls[0] || "").trim();

  if (!normalizedVideoUrl && !uniqueImageUrls.length) {
    throw new Error("Pinterest post is missing publishable media");
  }
  if (normalizedVideoUrl && !normalizedCoverImageUrl) {
    throw new Error("Pinterest video Pin is missing a required cover image");
  }

  const copy = buildPinterestPinCopy(content, destinationUrl, postId);
  let mediaSource;
  if (normalizedVideoUrl) {
    const mediaId = await preparePinterestVideoMedia({ accessToken, videoUrl: normalizedVideoUrl, postId });
    mediaSource = {
      source_type: "video_id",
      media_id: mediaId,
      cover_image_url: normalizedCoverImageUrl,
    };
  } else {
    mediaSource = uniqueImageUrls.length >= 2
      ? {
          source_type: "multiple_image_urls",
          // Pinterest supports title/description/link on every image in a
          // multi-image Pin. Repeat the campaign destination per slide so the
          // carousel keeps a website click-through instead of behaving like a
          // save-only gallery. The top-level link is kept as well below.
          items: uniqueImageUrls.map((url) => {
            const item = {
              url,
              title: copy.title,
              description: copy.description,
            };
            if (copy.link) item.link = copy.link;
            return item;
          }),
        }
      : {
          source_type: "image_url",
          url: uniqueImageUrls[0],
        };
  }

  const body = {
    board_id: String(boardId),
    title: copy.title,
    description: copy.description,
    media_source: mediaSource,
  };

  if (copy.link) {
    body.link = copy.link;
  }

  const response = await fetch(`${getPinterestApiBaseUrl()}/pins`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${accessToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
    cache: "no-store",
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok || !data?.id) {
    const error = pinterestPublishError(
      response,
      data,
      "Pinterest Pin publishing failed"
    );
    error.pinterestPhase = "create_pin";
    throw error;
  }

  console.log("Pinterest Pin payload accepted", {
    postId: postId || null,
    pinId: String(data.id),
    mediaType: normalizedVideoUrl ? "video" : uniqueImageUrls.length >= 2 ? "multiple_images" : "image",
    imageCount: normalizedVideoUrl ? 0 : uniqueImageUrls.length,
    hasDestination: Boolean(copy.link),
    perImageDestinations: uniqueImageUrls.length >= 2 && copy.link ? uniqueImageUrls.length : 0,
  });

  return data;
}

function summarizePinterestPinMedia(pin) {
  const media = pin?.media && typeof pin.media === "object" ? pin.media : {};
  const mediaType = String(media?.media_type || "").trim().toLowerCase();
  const items = Array.isArray(media?.items) ? media.items : [];
  const imageCount = mediaType === "multiple_images"
    ? items.length
    : mediaType === "image"
      ? 1
      : 0;
  const creativeType = String(pin?.creative_type || "").trim().toLowerCase();
  const isVideo = mediaType === "video" || creativeType === "video";
  return { mediaType, imageCount, creativeType, isVideo };
}

async function getPinterestPinById({ accessToken, pinId }) {
  const response = await fetch(
    `${getPinterestApiBaseUrl()}/pins/${encodeURIComponent(String(pinId))}`,
    {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    }
  );
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw pinterestPublishError(
      response,
      data,
      "Could not verify the published Pinterest Pin"
    );
  }
  return data;
}

async function verifyPinterestPublishedMedia({
  accessToken,
  pinId,
  expectedImageCount,
  expectedMediaKind = "image",
  postId,
}) {
  const expected = Math.max(1, Number(expectedImageCount || 1));
  const expectsVideo = String(expectedMediaKind || "image").toLowerCase() === "video";
  let lastPin = null;
  let lastSummary = { mediaType: "", imageCount: 0, creativeType: "", isVideo: false };

  // Pinterest can need a short moment to populate media metadata immediately
  // after creation. Read the Pin back before Spreelo marks the target done.
  for (let attempt = 1; attempt <= 6; attempt += 1) {
    try {
      lastPin = await getPinterestPinById({ accessToken, pinId });
      lastSummary = summarizePinterestPinMedia(lastPin);
      const valid = expectsVideo
        ? lastSummary.isVideo
        : expected >= 2
        ? lastSummary.mediaType === "multiple_images" &&
          lastSummary.imageCount === expected
        : lastSummary.mediaType === "image" && lastSummary.imageCount === 1;
      if (valid) {
        console.info("Pinterest published media verified", {
          postId: postId || null,
          pinId: String(pinId),
          expectedImageCount: expectsVideo ? 0 : expected,
          expectedMediaKind: expectsVideo ? "video" : "image",
          mediaType: lastSummary.mediaType,
          imageCount: lastSummary.imageCount,
          attempt,
        });
        return lastPin;
      }
    } catch (error) {
      if (isPinterestAuthError(error)) throw error;
      if (attempt >= 6) throw error;
    }
    if (attempt < 6) await sleep(Math.min(1500 * attempt, 5000));
  }

  const error = new Error(
    expectsVideo
      ? `Pinterest returned Pin ${pinId}, but Spreelo could not verify the video media yet (received ${lastSummary.mediaType || lastSummary.creativeType || "unknown"}). The post was not marked published.`
      : expected >= 2
      ? `Pinterest returned Pin ${pinId}, but Spreelo could not verify the ${expected}-image carousel (received ${lastSummary.mediaType || "unknown"} with ${lastSummary.imageCount} image(s)). The post was not marked published.`
      : `Pinterest returned Pin ${pinId}, but Spreelo could not verify the single-image media. The post was not marked published.`
  );
  error.pinterestMediaVerificationFailed = true;
  error.pinterestTransient = true;
  error.pinId = String(pinId);
  error.expectedImageCount = expected;
  error.actualMediaType = lastSummary.mediaType || null;
  error.actualImageCount = lastSummary.imageCount;
  throw error;
}

async function getPinterestConnectionForBrand({
  supabase,
  userId,
  brandProfileId,
}) {
  if (!userId || !brandProfileId) {
    return null;
  }

  const { data, error } = await supabase
    .from("social_connections")
    .select(
      "id, page_id, page_name, page_access_token, token_expires_at, refresh_token, refresh_token_expires_at, permissions, status"
    )
    .eq("user_id", userId)
    .eq("brand_profile_id", brandProfileId)
    .eq("platform", "pinterest")
    .eq("status", "connected")
    .order("updated_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) {
    console.error("Could not load Pinterest connection for brand", {
      userId,
      brandProfileId,
      message: error.message,
    });
    return null;
  }

  return data || null;
}

